test("JS oracle: ABI v3 FUN_0086e6c0 list/SSO/load status", () => {
  assert.equal(luaEngineRunScriptListEmpty(0x100, 0x100), 1);
  assert.equal(luaEngineRunScriptListEmpty(0x100, 0x200), 0);
  assert.equal(luaEngineMsvcStringSsoLocal(0x0f), 1);
  assert.equal(luaEngineMsvcStringSsoLocal(LUA_MSVC_STRING_HEAP_THRESHOLD), 0);
  assert.equal(luaEngineMsvcStringDataPtr(0xaaa, 0xbbb, 0x0f), 0xaaa);
  assert.equal(luaEngineMsvcStringDataPtr(0xaaa, 0xbbb, 0x10), 0xbbb);
  assert.equal(luaEngineMsvcStringNeedsHeapFree(0x0f), 0);
  assert.equal(luaEngineMsvcStringNeedsHeapFree(0x10), 1);
  assert.equal(luaEngineMsvcStringFreeBytes(0x0f), 0x10);
  assert.equal(luaEngineMsvcStringFreeBytes(0xfff), 0x1000);
  assert.equal(luaEngineMsvcStringAlignedFree(0xfff), 0);
  assert.equal(luaEngineMsvcStringAlignedFree(LUA_MSVC_STRING_ALIGN_THRESHOLD), 1);

  // slack = (ptr - real) - 4; ok if <= 0x1f
  // ptr=0x1040, real=0x1000 → slack = 0x40-4 = 0x3c > 0x1f → fail
  assert.equal(luaEngineMsvcStringAlignedHeaderOk(0x1040, 0x1000), 0);
  // ptr=0x1010, real=0x1000 → slack = 0x10-4 = 0xc ≤ 0x1f → ok
  assert.equal(luaEngineMsvcStringAlignedHeaderOk(0x1010, 0x1000), 1);
  // boundary slack == 0x1f
  assert.equal(luaEngineMsvcStringAlignedHeaderOk(0x1023, 0x1000), 1);
  assert.equal(luaEngineMsvcStringAlignedHeaderOk(0x1024, 0x1000), 0);
  assert.equal(LUA_MSVC_STRING_ALIGN_SLACK_MAX, 0x1f);

  assert.equal(luaEngineRunScriptTakeDebugPath(0), 0);
  assert.equal(luaEngineRunScriptTakeDebugPath(1), 1);
  assert.equal(luaEngineLuaStatusOk(0), 1);
  assert.equal(luaEngineLuaStatusOk(1), 0);
  assert.equal(luaEngineLuaStatusOk(-1), 0);
  assert.equal(luaEngineRunScriptFailFlag(0, 0), 0);
  assert.equal(luaEngineRunScriptFailFlag(1, 0), 1);
  assert.equal(luaEngineRunScriptFailFlag(0, 2), 1);
  assert.equal(luaEngineRunScriptFailFlag(3, 4), 1);
  assert.equal(luaEngineRunScriptSuccessBool(0), 1);
  assert.equal(luaEngineRunScriptSuccessBool(1), 0);
});

