test("JS oracle: ABI v6 stack-ref construct + pop pure islands", () => {
  assert.equal(LUA_STACK_REF_CONSTRUCT_PUSH_DELTA, 1);
  assert.equal(LUA_STACK_REF_CONSTRUCT_GLOBAL_NAME_VA, 0x00b6ea60);

  assert.equal(luaEngineStackRefConstructStateStore(0), 0);
  assert.equal(luaEngineStackRefConstructStateStore(0x12340000), 0x12340000);
  assert.equal(luaEngineStackRefConstructStateStore(0xffffffff), 0xffffffff);
  assert.equal(luaEngineStackRefConstructSlotsInit(), 0);
  assert.equal(luaEngineStackRefConstructSlotsAfterGlobal(0), 1);
  assert.equal(luaEngineStackRefConstructSlotsAfterGlobal(5), 6);
  assert.equal(luaEngineStackRefConstructSlotsAfterGlobal(0xffffffff), 0);
  assert.equal(luaEngineStackRefConstructReturnThis(0x00aabb00), 0x00aabb00);
  assert.equal(luaEngineStackRefConstructReturnThis(0), 0);

  // pop slots ready: signed slots >= count
  assert.equal(luaEngineStackRefPopSlotsReady(0, 0), 1);
  assert.equal(luaEngineStackRefPopSlotsReady(3, 3), 1);
  assert.equal(luaEngineStackRefPopSlotsReady(5, 3), 1);
  assert.equal(luaEngineStackRefPopSlotsReady(2, 3), 0);
  assert.equal(luaEngineStackRefPopSlotsReady(-1, 0), 0);
  assert.equal(luaEngineStackRefPopSlotsReady(0, -1), 1);

  // settop index = ~count — pop 1 → -2, pop 3 → -4
  assert.equal(luaEngineStackRefPopSettopIndex(1), 0xfffffffe);
  assert.equal(luaEngineStackRefPopSettopIndex(3), 0xfffffffc);
  assert.equal(luaEngineStackRefPopSettopIndex(0), 0xffffffff);
  assert.equal(luaEngineStackRefPopSettopIndex(1) | 0, -2);
  assert.equal(luaEngineStackRefPopSettopIndex(3) | 0, -4);
  // fixed return path uses -4 for count=3
  assert.equal(luaEngineStackRefPopSettopIndex(3), luaEngineStackRefSettopIndex());

  assert.equal(luaEngineStackRefPopSlotsAfter(3, 3), 0);
  assert.equal(luaEngineStackRefPopSlotsAfter(10, 3), 7);
  assert.equal(luaEngineStackRefPopSlotsAfter(0, 1), 0xffffffff);
  assert.equal(luaEngineStackRefPopSlotsAfter(5, 0), 5);
});

