  assert.equal(luaEngineStackRefClassCreateReturnThis(0x00aabb00), 0x00aabb00);
  assert.equal(luaEngineStackRefClassCreateReturnThis(0), 0);

  // EntityPtr registry keys for create-path rawseti at -1/-2/-3
  assert.equal(LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_1, 0x00c8297e);
  assert.equal(LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_2, 0x00c8297d);
