  assert.equal(luaEngineClassCreateRegistryKeyMinus2(), LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_2);
  assert.equal(luaEngineClassCreateRegistryKeyMinus3(), LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_3);
  // consecutive: key(rel) = key_m1 + rel + 1
  assert.equal(
    luaEngineClassCreateRegistryKeyAtRel(LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_1, -1),
    LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_1,
  );
  assert.equal(
    luaEngineClassCreateRegistryKeyAtRel(LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_1, -2),
    LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_2,
  );
  assert.equal(
    luaEngineClassCreateRegistryKeyAtRel(LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_1, -3),
    LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_3,
  );
  // wrap edge: key_m1=0, rel=-1 → 0; rel=0 → 1
