test("JS oracle: ABI v9 method helper IAT-chain pure islands", () => {
  // Corrected chain: newuserdata → pushcclosure → absindex → pushstring → rotate → rawset
  assert.equal(LUA_METHOD_INSTALL_ABSINDEX_INDEX_U32, 0xfffffffd);
  assert.equal(LUA_METHOD_INSTALL_ROTATE_INDEX_U32, 0xfffffffe);
  assert.equal(LUA_METHOD_INSTALL_ROTATE_N, 1);
  assert.equal(LUA_METHOD_INSTALL_STACK_ARG_BYTES, 0x38);

  assert.equal(luaEngineMethodInstallAbsindexIndex(), LUA_METHOD_INSTALL_ABSINDEX_INDEX_U32);
  assert.equal(luaEngineMethodInstallRotateIndex(), LUA_METHOD_INSTALL_ROTATE_INDEX_U32);
  assert.equal(luaEngineMethodInstallRotateN(), LUA_METHOD_INSTALL_ROTATE_N);
  assert.equal(luaEngineMethodInstallStackArgBytes(), LUA_METHOD_INSTALL_STACK_ARG_BYTES);

  // absindex −3 matches historical v8 table index + relative −3
  assert.equal(
    luaEngineMethodInstallAbsindexIndex(),
    luaEngineMethodInstallTablePushvalueIndex(),
  );
  assert.equal(
    luaEngineMethodInstallAbsindexIndex(),
    luaEngineRelativeStackIndexMinus3(),
  );

  // rotate idx −2 matches relative −2; rotate n matches v5 set-meta push-n
  assert.equal(
    luaEngineMethodInstallRotateIndex(),
    luaEngineRelativeStackIndexMinus2(),
  );
  assert.equal(luaEngineMethodInstallRotateN(), luaEngineRegisterSetMetaPushN());

  // rawset index is absindex return (identity)
  for (const abs of [0, 1, 3, 0x10, 0x7fffffff, 0xffffffff]) {
    assert.equal(luaEngineMethodInstallRawsetIndex(abs), abs >>> 0);
  }

  // stack cleanup: 6 IAT calls arg bytes → PE add esp, 0x38
  // newuserdata(8)+pushcclosure(12)+absindex(8)+pushstring(8)+rotate(12)+rawset(8)=0x38
  assert.equal(0x8 + 0xc + 0x8 + 0x8 + 0xc + 0x8, LUA_METHOD_INSTALL_STACK_ARG_BYTES);
});

