  assert.match(h, /ISAAC_LUA_PROPERTY_CLOSURE_STORE_KIND_INDIRECT = 4[,\s}]/);
  // every v22 export is declared in the header
  assert.match(h, /isaac_lua_engine_closure_count\(/);
