  assert.match(h, /isaac_lua_engine_closure_return_value\(/);
  assert.match(h, /isaac_lua_engine_closure_cluster_count\(/);
  assert.match(h, /isaac_lua_engine_closure_cluster_rep_va\(/);
  assert.match(h, /isaac_lua_engine_closure_cluster_bodies\(/);
  assert.match(h, /isaac_lua_engine_closure_cluster_body_bytes\(/);
  assert.match(h, /isaac_lua_engine_closure_cluster_body_insns\(/);
  assert.match(h, /isaac_lua_engine_closure_cluster_band\(/);
  assert.match(h, /isaac_lua_engine_closure_cluster_operand_fields\(/);
  assert.match(h, /isaac_lua_engine_closure_cluster_free_fields\(/);
  assert.match(h, /isaac_lua_engine_closure_type_gate_taken\(/);
  assert.match(h, /isaac_lua_engine_closure_const_gate_raises\(/);
  assert.match(h, /isaac_lua_engine_closure_boolean_normalize\(/);
  assert.match(h, /isaac_lua_engine_closure_push_i32_lo\(/);
  assert.match(h, /isaac_lua_engine_closure_push_i32_hi\(/);
  assert.match(h, /isaac_lua_engine_closure_push_u32_lo\(/);
  assert.match(h, /isaac_lua_engine_closure_push_u32_hi\(/);
  assert.match(h, /isaac_lua_engine_closure_push_u16_lo\(/);
  assert.match(h, /isaac_lua_engine_closure_push_u16_hi\(/);
  assert.match(h, /isaac_lua_engine_closure_store_value\(/);
  assert.match(h, /isaac_lua_engine_closure_upvalue_index\(/);
  // and none of them narrows a scalar parameter to uint8_t
  const decls = h.split("\n").filter((l) => l.includes("isaac_lua_engine_closure_"));
  assert.ok(decls.length >= 34, "closure prototypes present");
  for (const d of decls) {
    assert.doesNotMatch(d, /\buint8_t\b/, d);
  }
  // the JS model and the header must agree on every literal
  assert.equal(LUA_PROPERTY_CLOSURE_TOTAL, 326);
