test("JS oracle: ABI v27 first band-C primary BODY 0x008c32d0 pure islands", () => {
  assert.equal(luaEngineBandCPrimaryVa(), LUA_BAND_C_EXAMPLE_BODY_VA);
  assert.equal(luaEngineBandCPrimaryVa(), 0x008c32d0);
  assert.equal(luaEngineBandCPrimaryTypeIndex(), 1);
  assert.equal(luaEngineBandCPrimaryCheckFlag(), 1);
  assert.equal(luaEngineBandCPrimaryCheckStackIndex(), 1);
  assert.equal(luaEngineBandCPrimaryClassKey(), 0x00c82a30);
  assert.equal(luaEngineBandCPrimaryClassKey(), luaEngineBandCClassKey(0));
  assert.equal(luaEngineBandCPrimaryObjectFieldOff(), 4);
  assert.equal(luaEngineBandCPrimaryTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineBandCPrimaryIatLuaType(), 0x00b18400);
  assert.equal(luaEngineBandCPrimaryIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineBandCPrimaryPushVa(), LUA_BAND_C_PUSH_I32_VA);
  assert.equal(luaEngineBandCPrimaryReturnValue(), 1);
  assert.equal(luaEngineBandCPrimaryNilStillCalls(), 1);
  assert.equal(luaEngineBandCNextVa(), 0x008c5a90);
  assert.equal(LUA_INLINE_NEXT_VA, LUA_FOURTH_NOARG_SETTER_NEXT_VA);
  assert.equal(luaEngineBandCVa(10), 0x008c4e90);

  // FULL-WORD type gate (PE 85 c0 / 75 04). 0x100 takes the check path.
  assert.equal(luaEngineBandCPrimaryTypeGateTaken(0), 0);
  assert.equal(luaEngineBandCPrimaryTypeGateTaken(1), 1);
  assert.equal(luaEngineBandCPrimaryTypeGateTaken(0x100), 1);
  assert.equal(luaEngineBandCPrimaryTypeGateTaken(0xffffff00), 1);
  assert.equal(luaEngineBandCPrimaryTypeGateTaken(0xffffffff), 1);

  // nil path zeros this; nonzero type keeps the class-check result.
  assert.equal(luaEngineBandCPrimaryThis(0, 0xdeadbeef), 0);
  assert.equal(luaEngineBandCPrimaryThis(1, 0xdeadbeef), 0xdeadbeef);
  assert.equal(luaEngineBandCPrimaryThis(0x100, 0x40c3a0), 0x40c3a0);
  assert.equal(luaEngineBandCPrimaryThis(0xffffff00, 0xffffffff), 0xffffffff);
});

test("native/Wasm differential: ABI v27 band-C primary this-select + type gate", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.bandCPrimaryVa() >>> 0, luaEngineBandCPrimaryVa());
  assert.equal(native.bandCPrimaryTypeIndex() >>> 0, luaEngineBandCPrimaryTypeIndex());
  assert.equal(native.bandCPrimaryCheckFlag() >>> 0, luaEngineBandCPrimaryCheckFlag());
  assert.equal(native.bandCPrimaryCheckStackIndex() >>> 0, luaEngineBandCPrimaryCheckStackIndex());
  assert.equal(native.bandCPrimaryClassKey() >>> 0, luaEngineBandCPrimaryClassKey());
  assert.equal(native.bandCPrimaryObjectFieldOff() >>> 0, luaEngineBandCPrimaryObjectFieldOff());
  assert.equal(native.bandCPrimaryTouserdataIndex() >>> 0, luaEngineBandCPrimaryTouserdataIndex());
  assert.equal(native.bandCPrimaryIatLuaType() >>> 0, luaEngineBandCPrimaryIatLuaType());
  assert.equal(native.bandCPrimaryIatLuaTouserdata() >>> 0, luaEngineBandCPrimaryIatLuaTouserdata());
  assert.equal(native.bandCPrimaryPushVa() >>> 0, luaEngineBandCPrimaryPushVa());
  assert.equal(native.bandCPrimaryReturnValue() >>> 0, luaEngineBandCPrimaryReturnValue());
  assert.equal(native.bandCPrimaryNilStillCalls() | 0, luaEngineBandCPrimaryNilStillCalls());
  assert.equal(native.bandCNextVa() >>> 0, luaEngineBandCNextVa());

  // UNMASKED wide values - never pre-mask Wasm-side args.
  const WIDE = [
    0, 1, 0xff, 0x100, 0x1ff, 0x1000, 0x7fffffff,
    0x80000000, 0xffffff00, 0xfffffffe, 0xffffffff,
  ];
  for (const t of WIDE) {
    assert.equal(
      native.bandCPrimaryTypeGateTaken(t) | 0,
      luaEngineBandCPrimaryTypeGateTaken(t),
      "type gate 0x" + (t >>> 0).toString(16));
    for (const th of WIDE) {
      assert.equal(
        native.bandCPrimaryThis(t, th) >>> 0,
        luaEngineBandCPrimaryThis(t, th),
        "this 0x" + (t >>> 0).toString(16) + "/" + (th >>> 0).toString(16));
    }
  }
  // PE direction pins
  assert.equal(native.bandCPrimaryTypeGateTaken(0x100) | 0, 1);
  assert.equal(native.bandCPrimaryThis(0, 0xdeadbeef) >>> 0, 0);
  assert.equal(native.bandCPrimaryNilStillCalls() | 0, 1);
});

