test("JS oracle: ABI v28 band-C primary template covers all 10 sites", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  assert.equal(luaEngineBandCPrimaryStride(), 0x60);
  assert.equal(luaEngineBandCPrimaryIdenticalBytes(), 87);
  assert.equal(LUA_BAND_C_PRIMARY_DIFF_OFF_KEY, 0x1f);
  assert.equal(LUA_BAND_C_PRIMARY_DIFF_OFF_CHECK_REL, 0x2b);
  assert.equal(LUA_BAND_C_PRIMARY_DIFF_OFF_PUSH_REL, 0x4f);
  assert.equal(LUA_BAND_C_PRIMARY_COUNT, 10);
  assert.equal(luaEngineBandCNextVa(), 0x008c5a90);
  assert.equal(luaEngineBandCVa(10), 0x008c4e90);
  // ≥2 distinct BSS class keys (0 vs 1) — not a single-body peel.
  assert.equal(luaEngineBandCPrimaryClassKeyAt(0), 0x00c82a30);
  assert.equal(luaEngineBandCPrimaryClassKeyAt(1), 0x00c82a3c);
  assert.notEqual(luaEngineBandCPrimaryClassKeyAt(0),
    luaEngineBandCPrimaryClassKeyAt(1));
  assert.equal(luaEngineBandCPrimaryVaAt(0), 0x008c32d0);
  assert.equal(luaEngineBandCPrimaryVaAt(9), 0x008c3630);

  // VA law + class-key table agreement on every primary.
  for (let i = 0; i < LUA_BAND_C_PRIMARY_COUNT; i += 1) {
    const va = luaEngineBandCPrimaryVaAt(i);
    assert.equal(va, luaEngineBandCVa(i), "va law " + i);
    assert.equal(va, (0x008c32d0 + 0x60 * i) >>> 0, "stride " + i);
    assert.equal(luaEngineBandCShape(i), LUA_BAND_C_SHAPE_PRIMARY, "shape " + i);
    assert.equal(luaEngineBandCBodyBytes(i), 0x5c, "bytes " + i);
    assert.equal(luaEngineBandCPrimaryClassKeyAt(i), luaEngineBandCClassKey(i), "key " + i);
    assert.equal(luaEngineBandCPrimaryIndexForVa(va), i, "index " + i);
    // shared CF (v27 law by reference) holds on every site
    assert.equal(luaEngineBandCPrimaryTypeGateTaken(0), 0);
    assert.equal(luaEngineBandCPrimaryTypeGateTaken(0x100), 1);
    assert.equal(luaEngineBandCPrimaryThis(0, 0xdeadbeef), 0);
    assert.equal(luaEngineBandCPrimaryNilStillCalls(), 1);
  }

  // out-of-range + non-stride VAs
  assert.equal(luaEngineBandCPrimaryVaAt(-1), 0);
  assert.equal(luaEngineBandCPrimaryVaAt(10), 0);
  assert.equal(luaEngineBandCPrimaryClassKeyAt(-1), 0);
  assert.equal(luaEngineBandCPrimaryClassKeyAt(10), 0);
  assert.equal(luaEngineBandCPrimaryIndexForVa(0), -1);
  assert.equal(luaEngineBandCPrimaryIndexForVa(0x008c32d0 + 1), -1);
  assert.equal(luaEngineBandCPrimaryIndexForVa(0x008c32d0 + 0x60 * 10), -1);
  assert.equal(luaEngineBandCPrimaryIndexForVa(0x008c4e90), -1);

  // mutant: a low-byte type gate would take 0x100 as 0. PE is FULL-WORD.
  assert.notEqual(luaEngineBandCPrimaryTypeGateTaken(0x100),
    ((0x100 & 0xff) !== 0) ? 1 : 0);
  // mutant: a +0x5c stride would miss every site after the first.
  assert.notEqual(luaEngineBandCPrimaryVaAt(1), (0x008c32d0 + 0x5c) >>> 0);
  assert.equal(luaEngineBandCPrimaryVaAt(1), 0x008c3330);
});

