test("JS oracle: ABI v29 band-C secondary template covers all 16 sites", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  assert.equal(luaEngineBandCSecondaryStride(), 0xc0);
  assert.equal(luaEngineBandCSecondaryIdenticalBytes(), 158);
  assert.equal(LUA_BAND_C_SECONDARY_DIFF_OFF_FLAG, 0x25);
  assert.equal(LUA_BAND_C_SECONDARY_DIFF_OFF_KEY, 0x27);
  assert.equal(LUA_BAND_C_SECONDARY_DIFF_OFF_CHECK_REL, 0x33);
  assert.equal(LUA_BAND_C_SECONDARY_DIFF_OFF_WRAP_KEY, 0x74);
  assert.equal(LUA_BAND_C_SECONDARY_COUNT, 16);
  assert.equal(luaEngineBandCSecondaryVaAt(0), 0x008c4e90);
  assert.equal(luaEngineBandCSecondaryVaAt(15), 0x008c59d0);
  assert.equal(luaEngineBandCNextVa(), 0x008c5a90);
  assert.equal(LUA_INLINE_NEXT_VA, LUA_FOURTH_NOARG_SETTER_NEXT_VA);
  assert.equal(luaEngineBandCSecondaryCheckintegerIndex(), 2);
  assert.equal(luaEngineBandCSecondaryWrapUdSize(), 8);
  assert.equal(luaEngineBandCSecondaryWrapTagVa(), 0x00b753c8);
  assert.equal(luaEngineBandCSecondaryReturnValue(), 1);
  assert.equal(LUA_BAND_C_SECONDARY_NULL_STILL_RETURNS, 1);
  assert.equal(LUA_BAND_C_SECONDARY_WRAP_FIELD_OFF, 4);
  assert.equal(LUA_BAND_C_SECONDARY_RAWGETP_REGISTRY_INDEX_U32, 0xfff0b9d8);
  assert.equal(LUA_BAND_C_SECONDARY_SETMETA_INDEX_U32, 0xfffffffe);
  assert.equal(LUA_BAND_C_SECONDARY_IAT_CHECKINTEGER, 0x00b183f4);
  assert.equal(LUA_BAND_C_SECONDARY_IAT_NEWUSERDATA, 0x00b1839c);
  assert.equal(LUA_BAND_C_SECONDARY_IAT_RAWGETP, 0x00b183bc);
  assert.equal(LUA_BAND_C_SECONDARY_IAT_SETMETATABLE, 0x00b18398);
  assert.equal(LUA_BAND_C_SECONDARY_IAT_PUSHNIL, 0x00b183e0);

  // ≥2 distinct BSS class keys (0 vs 2) — not a single-body peel.
  assert.equal(luaEngineBandCSecondaryClassKeyAt(0), 0x00c82a41);
  assert.equal(luaEngineBandCSecondaryClassKeyAt(2), 0x00c82a43);
  assert.notEqual(luaEngineBandCSecondaryClassKeyAt(0),
    luaEngineBandCSecondaryClassKeyAt(2));
  // ≥2 wrap keys and both check-flag values.
  assert.notEqual(luaEngineBandCSecondaryWrapKeyAt(0),
    luaEngineBandCSecondaryWrapKeyAt(1));
  assert.equal(luaEngineBandCSecondaryCheckFlagAt(0), 0);
  assert.equal(luaEngineBandCSecondaryCheckFlagAt(1), 1);

  for (let i = 0; i < LUA_BAND_C_SECONDARY_COUNT; i += 1) {
    const va = luaEngineBandCSecondaryVaAt(i);
    assert.equal(va, luaEngineBandCVa(LUA_BAND_C_PRIMARY_COUNT + i), "va law " + i);
    assert.equal(va, (0x008c4e90 + 0xc0 * i) >>> 0, "stride " + i);
    assert.equal(luaEngineBandCShape(LUA_BAND_C_PRIMARY_COUNT + i),
      LUA_BAND_C_SHAPE_SECONDARY, "shape " + i);
    assert.equal(luaEngineBandCBodyBytes(LUA_BAND_C_PRIMARY_COUNT + i), 0xa4, "bytes " + i);
    assert.equal(luaEngineBandCSecondaryClassKeyAt(i),
      luaEngineBandCClassKey(LUA_BAND_C_PRIMARY_COUNT + i), "key " + i);
    assert.equal(luaEngineBandCSecondaryIndexForVa(va), i, "index " + i);
    // shared CF (v27 law by reference) holds on every site
    assert.equal(luaEngineBandCPrimaryTypeGateTaken(0), 0);
    assert.equal(luaEngineBandCPrimaryTypeGateTaken(0x100), 1);
    assert.equal(luaEngineBandCPrimaryThis(0, 0xdeadbeef), 0);
    assert.equal(luaEngineBandCPrimaryNilStillCalls(), 1);
  }

  // out-of-range + non-stride VAs
  assert.equal(luaEngineBandCSecondaryVaAt(-1), 0);
  assert.equal(luaEngineBandCSecondaryVaAt(16), 0);
  assert.equal(luaEngineBandCSecondaryClassKeyAt(-1), 0);
  assert.equal(luaEngineBandCSecondaryClassKeyAt(16), 0);
  assert.equal(luaEngineBandCSecondaryCheckFlagAt(-1), 0);
  assert.equal(luaEngineBandCSecondaryWrapKeyAt(-1), 0);
  assert.equal(luaEngineBandCSecondaryIndexForVa(0), -1);
  assert.equal(luaEngineBandCSecondaryIndexForVa(0x008c4e90 + 1), -1);
  assert.equal(luaEngineBandCSecondaryIndexForVa(0x008c4e90 + 0xc0 * 16), -1);
  assert.equal(luaEngineBandCSecondaryIndexForVa(0x008c32d0), -1);
  assert.equal(luaEngineBandCSecondaryIndexForVa(0x008c5a90), -1);

  // mutant: a low-byte null gate would take 0x100 as 0. PE is FULL-WORD.
  assert.equal(luaEngineBandCSecondaryResultNullGate(0), 1);
  assert.equal(luaEngineBandCSecondaryResultNullGate(1), 0);
  assert.equal(luaEngineBandCSecondaryResultNullGate(0x100), 0);
  assert.notEqual(luaEngineBandCSecondaryResultNullGate(0x100),
    ((0x100 & 0xff) === 0) ? 1 : 0);
  // mutant: a +0xa4 stride would miss every site after the first.
  assert.notEqual(luaEngineBandCSecondaryVaAt(1), (0x008c4e90 + 0xa4) >>> 0);
  assert.equal(luaEngineBandCSecondaryVaAt(1), 0x008c4f50);
});

test("native/Wasm differential: ABI v29 band-C secondary template + mutant", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.bandCSecondaryStride() >>> 0, luaEngineBandCSecondaryStride());
  assert.equal(native.bandCSecondaryIdenticalBytes() >>> 0, luaEngineBandCSecondaryIdenticalBytes());
  assert.equal(native.bandCNextVa() >>> 0, 0x008c5a90);
  assert.equal(native.bandCSecondaryCheckintegerIndex() >>> 0,
    luaEngineBandCSecondaryCheckintegerIndex());
  assert.equal(native.bandCSecondaryWrapUdSize() >>> 0, luaEngineBandCSecondaryWrapUdSize());
  assert.equal(native.bandCSecondaryWrapTagVa() >>> 0, luaEngineBandCSecondaryWrapTagVa());
  assert.equal(native.bandCSecondaryReturnValue() >>> 0, luaEngineBandCSecondaryReturnValue());

  const WIDE = [
    0, 1, 0xff, 0x100, 0x1ff, 0x1000, 0x7fffffff,
    0x80000000, 0xffffff00, 0xfffffffe, 0xffffffff,
  ];
  for (let i = -1; i <= LUA_BAND_C_SECONDARY_COUNT; i += 1) {
    assert.equal(native.bandCSecondaryVaAt(i) >>> 0, luaEngineBandCSecondaryVaAt(i), "va_at " + i);
    assert.equal(native.bandCSecondaryClassKeyAt(i) >>> 0, luaEngineBandCSecondaryClassKeyAt(i), "key_at " + i);
    assert.equal(native.bandCSecondaryCheckFlagAt(i) >>> 0, luaEngineBandCSecondaryCheckFlagAt(i), "flag_at " + i);
    assert.equal(native.bandCSecondaryWrapKeyAt(i) >>> 0, luaEngineBandCSecondaryWrapKeyAt(i), "wrap_at " + i);
  }
  for (const va of WIDE.concat([
    0x008c4e90, 0x008c4f50, 0x008c5010, 0x008c50d0, 0x008c5190,
    0x008c5250, 0x008c5310, 0x008c53d0, 0x008c5490, 0x008c5550,
    0x008c5610, 0x008c56d0, 0x008c5790, 0x008c5850, 0x008c5910,
    0x008c59d0, 0x008c4e91, 0x008c5a50, 0x008c5a90, 0x008c32d0,
  ])) {
    assert.equal(
      native.bandCSecondaryIndexForVa(va) | 0,
      luaEngineBandCSecondaryIndexForVa(va),
      "idx 0x" + (va >>> 0).toString(16));
  }
  for (const r of WIDE) {
    assert.equal(
      native.bandCSecondaryResultNullGate(r) | 0,
      luaEngineBandCSecondaryResultNullGate(r),
      "null 0x" + (r >>> 0).toString(16));
  }
  // PE direction + mutant (FULL-WORD null gate, stride 0xc0)
  assert.equal(native.bandCSecondaryResultNullGate(0x100) | 0, 0);
  assert.notEqual(native.bandCSecondaryResultNullGate(0x100) | 0, 1);
  assert.equal(native.bandCSecondaryVaAt(1) >>> 0, 0x008c4f50);
  assert.notEqual(native.bandCSecondaryVaAt(1) >>> 0, (0x008c4e90 + 0xa4) >>> 0);
  assert.equal(native.bandCSecondaryIndexForVa(0x008c59d0) | 0, 15);
  assert.equal(native.bandCSecondaryClassKeyAt(2) >>> 0, 0x00c82a43);
  assert.equal(native.bandCSecondaryWrapKeyAt(0) >>> 0, 0x00c82a4a);
  assert.equal(native.bandCSecondaryCheckFlagAt(1) >>> 0, 1);
});

