test("JS oracle: ABI v30 leftover extra BODY 0x008a0600 pure islands", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  assert.equal(luaEngineLeftoverExtraVa(), 0x008a0600);
  assert.equal(luaEngineLeftoverExtraVa(), LUA_INLINE_RESIDUAL_EXTRA_VA);
  assert.equal(luaEngineLeftoverExtraVa(), LUA_FOURTH_STRADDLER_VA);
  assert.equal(luaEngineLeftoverExtraVa(), LUA_LEFTOVER_EXTRA_BODY_VA);
  assert.equal(luaEngineLeftoverExtraBodyBytes(), 0x88);
  assert.equal(luaEngineLeftoverExtraBodyBytes(), luaEngineFourthBodyBytes(9));
  assert.equal(luaEngineLeftoverExtraClassKey(), 0x00c8297d);
  assert.equal(luaEngineLeftoverExtraClassKey(), luaEngineFourthClassKey(9));
  assert.equal(luaEngineLeftoverExtraClassKey(), LUA_CLASS_CREATE_REGISTRY_KEY_MINUS_2);
  assert.equal(luaEngineLeftoverExtraCheckFlag(), 1);
  assert.equal(LUA_LEFTOVER_EXTRA_CHECK_STACK_INDEX, 1);
  assert.equal(luaEngineLeftoverExtraWrapKey(), 0x00c8297a);
  assert.equal(luaEngineLeftoverExtraWrapKey(), LUA_SETREF_WRAPPER_REGISTRY_KEY_ARG2);
  assert.equal(luaEngineLeftoverExtraCodeUdVa(), 0x0040c3a0);
  assert.equal(luaEngineLeftoverExtraCodeUdVa(), luaEngineFourthCodeUdValue(9));
  assert.equal(luaEngineLeftoverExtraCodeUdVa(), LUA_BAND_C_EXAMPLE_UD_VA);
  assert.equal(luaEngineLeftoverExtraHasCheckinteger(), 0);
  assert.equal(LUA_LEFTOVER_EXTRA_HAS_CHECKINTEGER, 0);
  assert.equal(luaEngineLeftoverExtraReturnValue(), 1);
  assert.equal(LUA_LEFTOVER_EXTRA_NULL_STILL_RETURNS, 1);
  assert.equal(LUA_DTOR_008C5A90_VA, 0x008c5a90);
  assert.equal(LUA_DTOR_008C5A90_VA, LUA_BAND_C_NEXT_VA);
  assert.equal(luaEngineLeftoverExtraNextVa(), 0x008c5b90);
  assert.equal(LUA_INLINE_NEXT_VA, LUA_FOURTH_NOARG_SETTER_NEXT_VA);
  assert.notEqual(LUA_INLINE_NEXT_VA, LUA_BAND_C_NEXT_VA);
  assert.notEqual(LUA_INLINE_NEXT_VA, LUA_LEFTOVER_EXTRA_NEXT_VA);
  // v31 peels 0x008976a0. leftover extra NEXT stays the v30
  // sequential handoff past the two dtors.

  // Shared CF: v27 type gate / this-select / nil-still-calls BY REFERENCE.
  assert.equal(luaEngineBandCPrimaryTypeGateTaken(0), 0);
  assert.equal(luaEngineBandCPrimaryTypeGateTaken(0x100), 1);
  assert.equal(luaEngineBandCPrimaryThis(0, 0xdeadbeef), 0);
  assert.equal(luaEngineBandCPrimaryNilStillCalls(), 1);

  // Shared CF: v29 FULL-WORD null gate BY REFERENCE. 0x100 is NON-null.
  assert.equal(luaEngineLeftoverExtraResultNullGate(0), 1);
  assert.equal(luaEngineLeftoverExtraResultNullGate(1), 0);
  assert.equal(luaEngineLeftoverExtraResultNullGate(0x100), 0);
  assert.equal(luaEngineLeftoverExtraResultNullGate(0xffffff00), 0);
  assert.equal(
    luaEngineLeftoverExtraResultNullGate(0x100),
    luaEngineBandCSecondaryResultNullGate(0x100));

  // Distinct from v29 secondaries: no luaL_checkinteger.
  assert.notEqual(luaEngineLeftoverExtraHasCheckinteger(),
    luaEngineBandCSecondaryCheckintegerIndex());
  // Distinct wrap key from every band-C secondary wrap key.
  for (let i = 0; i < LUA_BAND_C_SECONDARY_COUNT; i += 1) {
    assert.notEqual(luaEngineLeftoverExtraWrapKey(),
      luaEngineBandCSecondaryWrapKeyAt(i), "wrap vs secondary " + i);
  }

  // mutant: a low-byte null gate would take 0x100 as 0. PE is FULL-WORD.
  assert.notEqual(luaEngineLeftoverExtraResultNullGate(0x100),
    ((0x100 & 0xff) === 0) ? 1 : 0);
  // mutant: claiming checkinteger would collapse this onto a v29 secondary.
  assert.notEqual(luaEngineLeftoverExtraHasCheckinteger(), 1);
});

