  assert.equal(native.leftoverExtraWrapKey() >>> 0, luaEngineLeftoverExtraWrapKey());
  assert.equal(native.leftoverExtraCodeUdVa() >>> 0, luaEngineLeftoverExtraCodeUdVa());
  assert.equal(native.leftoverExtraHasCheckinteger() | 0, luaEngineLeftoverExtraHasCheckinteger());
