test("JS oracle: ABI v31 fourth-region string getter BODY 0x008976a0", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  assert.equal(luaEngineFourthGetterVa(), 0x008976a0);
  assert.equal(luaEngineFourthGetterVa(), LUA_FOURTH_GETTER_BODY_VA);
  assert.equal(luaEngineFourthGetterVa(), luaEngineFourthVa(1));
  assert.equal(luaEngineFourthGetterBodyBytes(), 0x31);
  assert.equal(luaEngineFourthGetterBodyBytes(), luaEngineFourthBodyBytes(1));
  assert.equal(luaEngineFourthGetterFullBytes(), 0x43);
  assert.equal(luaEngineFourthGetterCodeUdVa(), 0x0085eee0);
  assert.equal(luaEngineFourthGetterCodeUdVa(), luaEngineFourthCodeUdValue(1));
  assert.equal(luaEngineFourthGetterTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineFourthGetterTouserdataIndex(),
    luaEngineBandCPrimaryTouserdataIndex());
  assert.equal(luaEngineFourthGetterIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineFourthGetterIatLuaTouserdata(),
    luaEngineBandCPrimaryIatLuaTouserdata());
  assert.equal(luaEngineFourthGetterIatLuaPushstring(), 0x00b18414);
  assert.equal(luaEngineFourthGetterIatLuaPushstring(), LUA_IAT_LUA_PUSHSTRING_VA);
  assert.equal(luaEngineFourthGetterIatLuaPushnil(), 0x00b183e0);
  assert.equal(luaEngineFourthGetterIatLuaPushnil(), LUA_BAND_C_SECONDARY_IAT_PUSHNIL);
  assert.equal(luaEngineFourthGetterHasTypeGate(), 0);
  assert.equal(luaEngineFourthGetterHasThisSelect(), 0);
  assert.equal(luaEngineFourthGetterHasCheckinteger(), 0);
  assert.equal(luaEngineFourthGetterSiblingCount(), 1);
  assert.equal(luaEngineFourthGetterReturnValue(), 1);
  assert.equal(LUA_FOURTH_GETTER_NULL_STILL_RETURNS, 1);
  assert.equal(luaEngineFourthGetterNextVa(), 0x008976f0);
  assert.equal(luaEngineFourthGetterNextVa(), luaEngineFourthVa(2));
  assert.equal(LUA_INLINE_NEXT_VA, LUA_FOURTH_NOARG_SETTER_NEXT_VA);

  // Shared CF: v29 FULL-WORD null gate BY REFERENCE. 0x100 is NON-null.
  assert.equal(luaEngineFourthGetterResultNullGate(0), 1);
  assert.equal(luaEngineFourthGetterResultNullGate(1), 0);
  assert.equal(luaEngineFourthGetterResultNullGate(0x100), 0);
  assert.equal(luaEngineFourthGetterResultNullGate(0xffffff00), 0);
  assert.equal(
    luaEngineFourthGetterResultNullGate(0x100),
    luaEngineBandCSecondaryResultNullGate(0x100));

  // Distinct from v27: this body has no lua_type / this-select.
  assert.notEqual(luaEngineFourthGetterHasTypeGate(),
    luaEngineBandCPrimaryTypeGateTaken(1));
  assert.notEqual(luaEngineFourthGetterHasThisSelect(),
    luaEngineBandCPrimaryNilStillCalls());
  // Distinct from v29 wrap: no checkinteger, no userdata wrap.
  assert.notEqual(luaEngineFourthGetterHasCheckinteger(),
    luaEngineBandCSecondaryCheckintegerIndex());

  // mutant: a low-byte null gate would take 0x100 as 0. PE is FULL-WORD.
  assert.notEqual(luaEngineFourthGetterResultNullGate(0x100),
    ((0x100 & 0xff) === 0) ? 1 : 0);
  // mutant: claiming a type gate would collapse this onto a v27 primary.
  assert.notEqual(luaEngineFourthGetterHasTypeGate(), 1);
  // mutant: claiming siblings would invent a template that is not in the PE.
  assert.notEqual(luaEngineFourthGetterSiblingCount(), 2);
});

test("native/Wasm differential: ABI v31 fourth-getter null gate + mutant", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.fourthGetterVa() >>> 0, luaEngineFourthGetterVa());
  assert.equal(native.fourthGetterBodyBytes() >>> 0, luaEngineFourthGetterBodyBytes());
  assert.equal(native.fourthGetterFullBytes() >>> 0, luaEngineFourthGetterFullBytes());
  assert.equal(native.fourthGetterCodeUdVa() >>> 0, luaEngineFourthGetterCodeUdVa());
  assert.equal(native.fourthGetterTouserdataIndex() >>> 0,
    luaEngineFourthGetterTouserdataIndex());
  assert.equal(native.fourthGetterIatLuaTouserdata() >>> 0,
    luaEngineFourthGetterIatLuaTouserdata());
  assert.equal(native.fourthGetterIatLuaPushstring() >>> 0,
    luaEngineFourthGetterIatLuaPushstring());
  assert.equal(native.fourthGetterIatLuaPushnil() >>> 0,
    luaEngineFourthGetterIatLuaPushnil());
  assert.equal(native.fourthGetterHasTypeGate() | 0, luaEngineFourthGetterHasTypeGate());
  assert.equal(native.fourthGetterHasThisSelect() | 0,
    luaEngineFourthGetterHasThisSelect());
  assert.equal(native.fourthGetterHasCheckinteger() | 0,
    luaEngineFourthGetterHasCheckinteger());
  assert.equal(native.fourthGetterSiblingCount() | 0,
    luaEngineFourthGetterSiblingCount());
  assert.equal(native.fourthGetterReturnValue() >>> 0,
    luaEngineFourthGetterReturnValue());
  assert.equal(native.fourthGetterNextVa() >>> 0, luaEngineFourthGetterNextVa());
  assert.equal(native.fourthGetterNextVa() >>> 0, 0x008976f0);

  const WIDE = [
    0, 1, 0xff, 0x100, 0x1ff, 0x1000, 0x7fffffff,
    0x80000000, 0xffffff00, 0xfffffffe, 0xffffffff,
  ];
  for (const r of WIDE) {
    assert.equal(
      native.fourthGetterResultNullGate(r) | 0,
      luaEngineFourthGetterResultNullGate(r),
      "null 0x" + (r >>> 0).toString(16));
    assert.equal(
      native.fourthGetterResultNullGate(r) | 0,
      native.bandCSecondaryResultNullGate(r) | 0,
      "v29 reuse 0x" + (r >>> 0).toString(16));
  }
  // PE direction + mutant (FULL-WORD null gate, no type gate, 1 site)
  assert.equal(native.fourthGetterResultNullGate(0x100) | 0, 0);
  assert.notEqual(native.fourthGetterResultNullGate(0x100) | 0, 1);
  assert.equal(native.fourthGetterHasTypeGate() | 0, 0);
  assert.notEqual(native.fourthGetterHasTypeGate() | 0, 1);
  assert.equal(native.fourthGetterHasThisSelect() | 0, 0);
  assert.equal(native.fourthGetterHasCheckinteger() | 0, 0);
  assert.equal(native.fourthGetterSiblingCount() | 0, 1);
  assert.notEqual(native.fourthGetterSiblingCount() | 0, 2);
  assert.equal(native.fourthGetterCodeUdVa() >>> 0, 0x0085eee0);
  assert.equal(native.fourthGetterVa() >>> 0, 0x008976a0);
});

