  assert.equal(luaEngineFourthSetterCheckintegerIndex(), 1);
  assert.equal(luaEngineFourthSetterStackClean(), 0x14);
  assert.equal(luaEngineFourthSetterTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineFourthSetterTouserdataIndex(),
    luaEngineFourthGetterTouserdataIndex());
  assert.equal(luaEngineFourthSetterIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineFourthSetterIatLuaTouserdata(),
    luaEngineFourthGetterIatLuaTouserdata());
  assert.equal(luaEngineFourthSetterIatCheckinteger(), 0x00b183f4);
