  assert.equal(luaEngineFourthBoolSetterStackClean(), 0x14);
  assert.equal(luaEngineFourthBoolSetterTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineFourthBoolSetterTouserdataIndex(),
    luaEngineFourthGetterTouserdataIndex());
  assert.equal(luaEngineFourthBoolSetterIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineFourthBoolSetterIatLuaTouserdata(),
    luaEngineFourthGetterIatLuaTouserdata());
  assert.equal(luaEngineFourthBoolSetterIatLuaToboolean(), 0x00b183e8);
  assert.equal(luaEngineFourthBoolSetterHasTypeGate(), 0);
  assert.equal(luaEngineFourthBoolSetterHasThisSelect(), 0);
  assert.equal(luaEngineFourthBoolSetterHasNullGate(), 0);
  assert.equal(luaEngineFourthBoolSetterHasPush(), 0);
  assert.equal(luaEngineFourthBoolSetterHasCheckinteger(), 0);
  assert.equal(luaEngineFourthBoolSetterSiblingCount(), 1);
  assert.equal(luaEngineFourthBoolSetterReturnValue(), 0);
  assert.equal(LUA_FOURTH_BOOL_SETTER_RETURN, 0);
  assert.equal(luaEngineFourthBoolSetterNextVa(), 0x00897770);
  assert.equal(luaEngineFourthBoolSetterNextVa(), luaEngineFourthVa(4));
  assert.equal(LUA_INLINE_NEXT_VA, LUA_FOURTH_NOARG_SETTER_NEXT_VA);

  // Distinct from v32 integer setter: toboolean, not checkinteger.
  assert.notEqual(luaEngineFourthBoolSetterBodyBytes(),
    luaEngineFourthSetterBodyBytes());
  assert.notEqual(luaEngineFourthBoolSetterIatLuaToboolean(),
    luaEngineFourthSetterIatCheckinteger());
  assert.notEqual(luaEngineFourthBoolSetterHasCheckinteger(), 1);
  // Distinct from v31 getter: ret 0, no null gate / push.
  assert.notEqual(luaEngineFourthBoolSetterReturnValue(),
    luaEngineFourthGetterReturnValue());
  assert.notEqual(luaEngineFourthBoolSetterHasNullGate(),
    LUA_FOURTH_GETTER_NULL_STILL_RETURNS);
  assert.notEqual(luaEngineFourthBoolSetterHasPush(), 1);
  // Distinct from v27: no type / this-select.
  assert.notEqual(luaEngineFourthBoolSetterHasTypeGate(),
    luaEngineBandCPrimaryTypeGateTaken(1));

  // FULL-WORD setne (v22 boolean-normalize BY REFERENCE). 0x100 is true.
  assert.equal(luaEngineFourthBoolSetterBooleanNormalize(0), 0);
  assert.equal(luaEngineFourthBoolSetterBooleanNormalize(1), 1);
  assert.equal(luaEngineFourthBoolSetterBooleanNormalize(0x100), 1);
  assert.equal(luaEngineFourthBoolSetterBooleanNormalize(0xffffffff), 1);
  assert.equal(luaEngineFourthBoolSetterBooleanNormalize(0x100),
    luaEngineClosureBooleanNormalize(0x100));

  // mutant: claiming checkinteger would collapse this onto the v32 setter.
  assert.notEqual(luaEngineFourthBoolSetterHasCheckinteger(), 1);
