test("JS oracle: ABI v34 fourth-region boolean getter BODY 0x00897770", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  assert.equal(luaEngineFourthBoolGetterVa(), 0x00897770);
  assert.equal(luaEngineFourthBoolGetterVa(), LUA_FOURTH_BOOL_GETTER_BODY_VA);
  assert.equal(luaEngineFourthBoolGetterVa(), luaEngineFourthVa(4));
  assert.equal(luaEngineFourthBoolGetterVa(), luaEngineFourthBoolSetterNextVa());
  assert.equal(luaEngineFourthBoolGetterBodyBytes(), 0x30);
  assert.equal(luaEngineFourthBoolGetterBodyBytes(), luaEngineFourthBodyBytes(4));
  assert.equal(luaEngineFourthBoolGetterStackClean(), 0x10);
  assert.equal(luaEngineFourthBoolGetterTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineFourthBoolGetterTouserdataIndex(),
    luaEngineFourthGetterTouserdataIndex());
  assert.equal(luaEngineFourthBoolGetterIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineFourthBoolGetterIatLuaTouserdata(),
    luaEngineFourthGetterIatLuaTouserdata());
  assert.equal(luaEngineFourthBoolGetterIatLuaPushboolean(), 0x00b183ec);
  assert.equal(luaEngineFourthBoolGetterHasTypeGate(), 0);
  assert.equal(luaEngineFourthBoolGetterHasThisSelect(), 0);
  assert.equal(luaEngineFourthBoolGetterHasNullGate(), 0);
  assert.equal(luaEngineFourthBoolGetterHasCheckinteger(), 0);
  assert.equal(luaEngineFourthBoolGetterSiblingCount(), 1);
  assert.equal(luaEngineFourthBoolGetterReturnValue(), 1);
  assert.equal(LUA_FOURTH_BOOL_GETTER_RETURN, 1);
  assert.equal(luaEngineFourthBoolGetterNextVa(), 0x008977a0);
  assert.equal(luaEngineFourthBoolGetterNextVa(), luaEngineFourthVa(5));
  assert.equal(LUA_INLINE_NEXT_VA, LUA_FOURTH_NOARG_SETTER_NEXT_VA);

  // Distinct from v33 setter: BYTE gate, pushboolean, ret 1, stack 0x10.
  assert.notEqual(luaEngineFourthBoolGetterBodyBytes(),
    luaEngineFourthBoolSetterBodyBytes());
  assert.notEqual(luaEngineFourthBoolGetterStackClean(),
    luaEngineFourthBoolSetterStackClean());
  assert.notEqual(luaEngineFourthBoolGetterReturnValue(),
    luaEngineFourthBoolSetterReturnValue());
  assert.notEqual(luaEngineFourthBoolGetterIatLuaPushboolean(),
    luaEngineFourthBoolSetterIatLuaToboolean());
  // Distinct from v31 getter: no FULL-WORD null gate / pushstring.
  assert.notEqual(luaEngineFourthBoolGetterBodyBytes(),
    luaEngineFourthGetterBodyBytes());
  assert.notEqual(luaEngineFourthBoolGetterHasNullGate(),
    LUA_FOURTH_GETTER_NULL_STILL_RETURNS);
  // Distinct from v27: no type / this-select.
  assert.notEqual(luaEngineFourthBoolGetterHasTypeGate(),
    luaEngineBandCPrimaryTypeGateTaken(1));

  // BYTE setne (test al,al). 0x100 is false. Drive UNMASKED.
  assert.equal(luaEngineFourthBoolGetterBooleanNormalize(0), 0);
  assert.equal(luaEngineFourthBoolGetterBooleanNormalize(1), 1);
  assert.equal(luaEngineFourthBoolGetterBooleanNormalize(0xff), 1);
  assert.equal(luaEngineFourthBoolGetterBooleanNormalize(0x100), 0);
  assert.equal(luaEngineFourthBoolGetterBooleanNormalize(0x1ff), 1);
  assert.equal(luaEngineFourthBoolGetterBooleanNormalize(0xffffffff), 1);
  assert.notEqual(luaEngineFourthBoolGetterBooleanNormalize(0x100),
    luaEngineFourthBoolSetterBooleanNormalize(0x100));
  assert.notEqual(luaEngineFourthBoolGetterBooleanNormalize(0x100),
    luaEngineClosureBooleanNormalize(0x100));

  // mutant: claiming FULL-WORD setne would treat 0x100 as true.
  assert.notEqual(luaEngineFourthBoolGetterBooleanNormalize(0x100), 1);
  // mutant: claiming a null gate would collapse this onto the v31 getter.
  assert.notEqual(luaEngineFourthBoolGetterHasNullGate(), 1);
  // mutant: claiming siblings would invent a template that is not in the PE.
  assert.notEqual(luaEngineFourthBoolGetterSiblingCount(), 2);
  // mutant: claiming ret 0 would collapse this onto the v33 setter.
  assert.notEqual(luaEngineFourthBoolGetterReturnValue(), 0);
});

