test("JS oracle: ABI v36 fourth-region number getter BODY 0x00897930", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  assert.equal(luaEngineFourthNumberGetterVa(), 0x00897930);
  assert.equal(luaEngineFourthNumberGetterVa(), LUA_FOURTH_NUMBER_GETTER_BODY_VA);
  assert.equal(luaEngineFourthNumberGetterVa(), luaEngineFourthVa(6));
  assert.equal(luaEngineFourthNumberGetterBodyBytes(), 0x36);
  assert.equal(luaEngineFourthNumberGetterBodyBytes(), luaEngineFourthBodyBytes(6));
  assert.equal(luaEngineFourthNumberGetterTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineFourthNumberGetterTouserdataIndex(),
    luaEngineFourthGetterTouserdataIndex());
  assert.equal(luaEngineFourthNumberGetterIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineFourthNumberGetterIatLuaTouserdata(),
    luaEngineFourthGetterIatLuaTouserdata());
  assert.equal(luaEngineFourthNumberGetterHostVaPush(), 0x0085c050);
  assert.equal(luaEngineFourthNumberGetterHostVaPush(),
    LUA_FOURTH_NUMBER_GETTER_HOST_VA_PUSH);
  assert.equal(luaEngineFourthNumberGetterHasTypeGate(), 0);
  assert.equal(luaEngineFourthNumberGetterHasThisSelect(), 0);
  assert.equal(luaEngineFourthNumberGetterHasNullGate(), 0);
  assert.equal(luaEngineFourthNumberGetterHasCheckinteger(), 0);
  assert.equal(luaEngineFourthNumberGetterSiblingCount(), 1);
  assert.equal(luaEngineFourthNumberGetterReturnValue(), 1);
  assert.equal(LUA_FOURTH_NUMBER_GETTER_RETURN, 1);
  assert.equal(luaEngineFourthNumberGetterNextVa(), 0x00897970);
  assert.equal(LUA_INLINE_NEXT_VA, LUA_FOURTH_NOARG_SETTER_NEXT_VA);

  // Skip 0x008977f0 ctor: v35 next stays the skipped body.
  assert.equal(luaEngineFourthNumberSetterNextVa(), 0x008977f0);
  assert.notEqual(luaEngineFourthNumberGetterVa(), 0x008977f0);
  assert.notEqual(luaEngineFourthNumberGetterNextVa(), 0x008977f0);

  // Distinct from v35 number setter: ret 1 / host push, not checknumber / ret 0.
  assert.notEqual(luaEngineFourthNumberGetterBodyBytes(),
    luaEngineFourthNumberSetterBodyBytes());
  assert.notEqual(luaEngineFourthNumberGetterReturnValue(),
    luaEngineFourthNumberSetterReturnValue());
  assert.notEqual(luaEngineFourthNumberGetterHostVaPush(),
    luaEngineFourthNumberSetterIatChecknumber());
  // Distinct from v34 boolean getter: host 0x85c050, not pushboolean IAT.
  assert.notEqual(luaEngineFourthNumberGetterBodyBytes(),
    luaEngineFourthBoolGetterBodyBytes());
  assert.notEqual(luaEngineFourthNumberGetterHostVaPush(),
    luaEngineFourthBoolGetterIatLuaPushboolean());
  // Distinct from v31 string getter: no FULL-WORD null gate / pushstring.
  assert.notEqual(luaEngineFourthNumberGetterHasNullGate(),
    LUA_FOURTH_GETTER_NULL_STILL_RETURNS);
  assert.notEqual(luaEngineFourthNumberGetterBodyBytes(),
    luaEngineFourthGetterBodyBytes());
  // Distinct from v27: no type / this-select.
  assert.notEqual(luaEngineFourthNumberGetterHasTypeGate(),
    luaEngineBandCPrimaryTypeGateTaken(1));

  // mutant: swap touserdata IAT → test fails.
  assert.notEqual(luaEngineFourthNumberGetterIatLuaTouserdata(), 0x00b183f4);
  assert.notEqual(luaEngineFourthNumberGetterIatLuaTouserdata(), 0x00b18324);
  // mutant: claiming a null gate would collapse this onto the v31 getter.
  assert.notEqual(luaEngineFourthNumberGetterHasNullGate(), 1);
  // mutant: claiming siblings would invent a template that is not in the PE.
  assert.notEqual(luaEngineFourthNumberGetterSiblingCount(), 2);
  // mutant: claiming ret 0 would collapse this onto the v35 setter.
  assert.notEqual(luaEngineFourthNumberGetterReturnValue(), 0);
  // mutant: claiming the skipped ctor VA.
  assert.notEqual(luaEngineFourthNumberGetterVa(), 0x008977f0);
});

