test("JS oracle: ABI v37 sequential indexed bool setter BODY 0x00897f00", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  assert.equal(luaEngineFourthIntBoolSetterVa(), 0x00897f00);
  assert.equal(luaEngineFourthIntBoolSetterVa(), LUA_FOURTH_INT_BOOL_SETTER_BODY_VA);
  assert.equal(luaEngineFourthIntBoolSetterBodyBytes(), 0x49);
  assert.equal(luaEngineFourthIntBoolSetterTobooleanIndex(), 2);
  assert.equal(luaEngineFourthIntBoolSetterCheckintegerIndex(), 1);
  assert.equal(luaEngineFourthIntBoolSetterStackClean(), 0x20);
  assert.equal(luaEngineFourthIntBoolSetterStackAlignMask(), 0xfffffff8);
  assert.equal(luaEngineFourthIntBoolSetterSkippedCtorVa(), 0x00897970);
  assert.equal(luaEngineFourthIntBoolSetterTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineFourthIntBoolSetterTouserdataIndex(),
    luaEngineFourthGetterTouserdataIndex());
  assert.equal(luaEngineFourthIntBoolSetterIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineFourthIntBoolSetterIatLuaTouserdata(),
    luaEngineFourthGetterIatLuaTouserdata());
  assert.equal(luaEngineFourthIntBoolSetterIatLuaToboolean(), 0x00b183e8);
  assert.equal(luaEngineFourthIntBoolSetterIatLuaToboolean(),
    luaEngineFourthBoolSetterIatLuaToboolean());
  assert.equal(luaEngineFourthIntBoolSetterIatCheckinteger(), 0x00b183f4);
  assert.equal(luaEngineFourthIntBoolSetterIatCheckinteger(),
    luaEngineFourthSetterIatCheckinteger());
  assert.equal(luaEngineFourthIntBoolSetterHasTypeGate(), 0);
  assert.equal(luaEngineFourthIntBoolSetterHasThisSelect(), 0);
  assert.equal(luaEngineFourthIntBoolSetterHasNullGate(), 0);
  assert.equal(luaEngineFourthIntBoolSetterHasPush(), 0);
  assert.equal(luaEngineFourthIntBoolSetterHasCheckinteger(), 1);
  assert.equal(luaEngineFourthIntBoolSetterSiblingCount(), 1);
  assert.equal(luaEngineFourthIntBoolSetterReturnValue(), 0);
  assert.equal(LUA_FOURTH_INT_BOOL_SETTER_RETURN, 0);
  assert.equal(luaEngineFourthIntBoolSetterNextVa(), 0x00897f50);
  assert.equal(LUA_INLINE_NEXT_VA, LUA_FOURTH_NOARG_SETTER_NEXT_VA);

  // Skip 0x00897970 ctor: v36 next stays the skipped body. Do not reopen 0x008977f0.
  assert.equal(luaEngineFourthNumberGetterNextVa(), 0x00897970);
  assert.equal(luaEngineFourthIntBoolSetterSkippedCtorVa(), 0x00897970);
  assert.notEqual(luaEngineFourthIntBoolSetterVa(), 0x00897970);
  assert.notEqual(luaEngineFourthIntBoolSetterVa(), 0x008977f0);
  assert.notEqual(luaEngineFourthIntBoolSetterNextVa(), 0x00897970);
  assert.equal(luaEngineFourthNumberSetterNextVa(), 0x008977f0);

  // Distinct from v33 boolean setter: toboolean index 2, checkinteger present, stack 0x20.
  assert.notEqual(luaEngineFourthIntBoolSetterBodyBytes(),
    luaEngineFourthBoolSetterBodyBytes());
  assert.notEqual(luaEngineFourthIntBoolSetterTobooleanIndex(),
    luaEngineFourthBoolSetterTobooleanIndex());
  assert.notEqual(luaEngineFourthIntBoolSetterHasCheckinteger(),
    luaEngineFourthBoolSetterHasCheckinteger());
  assert.notEqual(luaEngineFourthIntBoolSetterStackClean(),
    luaEngineFourthBoolSetterStackClean());
  // Distinct from v32 integer setter: also toboolean, stack 0x20 not 0x14.
  assert.notEqual(luaEngineFourthIntBoolSetterBodyBytes(),
    luaEngineFourthSetterBodyBytes());
  assert.notEqual(luaEngineFourthIntBoolSetterStackClean(),
    luaEngineFourthSetterStackClean());
  assert.equal(luaEngineFourthIntBoolSetterCheckintegerIndex(),
    luaEngineFourthSetterCheckintegerIndex());
  // Distinct from v34 boolean getter: ret 0 / FULL-WORD setne / no pushboolean.
  assert.notEqual(luaEngineFourthIntBoolSetterReturnValue(),
    luaEngineFourthBoolGetterReturnValue());
  assert.notEqual(luaEngineFourthIntBoolSetterIatLuaToboolean(),
    luaEngineFourthBoolGetterIatLuaPushboolean());
  // Distinct from v36 number getter: ret 0, no host push-f32.
  assert.notEqual(luaEngineFourthIntBoolSetterReturnValue(),
    luaEngineFourthNumberGetterReturnValue());
  assert.notEqual(luaEngineFourthIntBoolSetterVa(),
    luaEngineFourthNumberGetterVa());
  // Distinct from v31 getter: no FULL-WORD null gate / pushstring.
  assert.notEqual(luaEngineFourthIntBoolSetterHasNullGate(),
    LUA_FOURTH_GETTER_NULL_STILL_RETURNS);
  // Distinct from v27: no type / this-select.
  assert.notEqual(luaEngineFourthIntBoolSetterHasTypeGate(),
    luaEngineBandCPrimaryTypeGateTaken(1));

  // FULL-WORD setne (v22 boolean-normalize BY REFERENCE). 0x100 is true.
  assert.equal(luaEngineFourthIntBoolSetterBooleanNormalize(0), 0);
  assert.equal(luaEngineFourthIntBoolSetterBooleanNormalize(1), 1);
  assert.equal(luaEngineFourthIntBoolSetterBooleanNormalize(0x100), 1);
  assert.equal(luaEngineFourthIntBoolSetterBooleanNormalize(0x1ff), 1);
  assert.equal(luaEngineFourthIntBoolSetterBooleanNormalize(0xffffffff), 1);
  assert.equal(luaEngineFourthIntBoolSetterBooleanNormalize(0x100),
    luaEngineClosureBooleanNormalize(0x100));
  // mutant: BYTE test would treat 0x100 as false (v34 law).
  assert.notEqual(luaEngineFourthIntBoolSetterBooleanNormalize(0x100), 0);
  // mutant: claiming toboolean index 1 would collapse this onto the v33 setter.
  assert.notEqual(luaEngineFourthIntBoolSetterTobooleanIndex(), 1);
  // mutant: claiming has_checkinteger 0 would collapse this onto the v33 setter.
  assert.notEqual(luaEngineFourthIntBoolSetterHasCheckinteger(), 0);
  // mutant: claiming checkinteger index 2 would collapse onto v29 secondaries.
  assert.notEqual(luaEngineFourthIntBoolSetterCheckintegerIndex(), 2);
  // mutant: claiming a null gate would collapse this onto the v31 getter.
  assert.notEqual(luaEngineFourthIntBoolSetterHasNullGate(), 1);
  // mutant: claiming siblings would invent a template that is not in the PE.
  assert.notEqual(luaEngineFourthIntBoolSetterSiblingCount(), 2);
  // mutant: claiming ret 1 would collapse this onto a getter.
  assert.notEqual(luaEngineFourthIntBoolSetterReturnValue(), 1);
  // mutant: claiming the skipped ctor VA.
  assert.notEqual(luaEngineFourthIntBoolSetterVa(), 0x00897970);
  assert.notEqual(luaEngineFourthIntBoolSetterVa(), 0x00898f50);
});

