test("JS oracle: ABI v38 sequential indexed integer getter BODY 0x008984e0", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  assert.equal(luaEngineFourthIntGetterVa(), 0x008984e0);
  assert.equal(luaEngineFourthIntGetterVa(), LUA_FOURTH_INT_GETTER_BODY_VA);
  assert.equal(luaEngineFourthIntGetterBodyBytes(), 0x41);
  assert.equal(luaEngineFourthIntGetterCheckintegerIndex(), 1);
  assert.equal(luaEngineFourthIntGetterStackClean(), 0x14);
  assert.equal(luaEngineFourthIntGetterStackCleanPush(), 0x0c);
  assert.equal(luaEngineFourthIntGetterStackCleanPush(), LUA_MATERIALIZE_STACK_CLEAN_PUSHINT);
  assert.equal(luaEngineFourthIntGetterStackAlignMask(), 0xfffffff8);
  assert.equal(luaEngineFourthIntGetterSkippedSehVa(), 0x00897f50);
  assert.equal(luaEngineFourthIntGetterSkippedCtorVa(), 0x00898140);
  assert.equal(luaEngineFourthIntGetterTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineFourthIntGetterTouserdataIndex(),
    luaEngineFourthGetterTouserdataIndex());
  assert.equal(luaEngineFourthIntGetterIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineFourthIntGetterIatLuaTouserdata(),
    luaEngineFourthGetterIatLuaTouserdata());
  assert.equal(luaEngineFourthIntGetterIatCheckinteger(), 0x00b183f4);
  assert.equal(luaEngineFourthIntGetterIatCheckinteger(),
    luaEngineFourthSetterIatCheckinteger());
  assert.equal(luaEngineFourthIntGetterIatPushinteger(), 0x00b183f8);
  assert.equal(luaEngineFourthIntGetterIatPushinteger(),
    LUA_MATERIALIZE_EVENT_IAT_PUSHINTEGER);
  assert.equal(luaEngineFourthIntGetterHasTypeGate(), 0);
  assert.equal(luaEngineFourthIntGetterHasThisSelect(), 0);
  assert.equal(luaEngineFourthIntGetterHasNullGate(), 0);
  assert.equal(luaEngineFourthIntGetterHasPush(), 1);
  assert.equal(luaEngineFourthIntGetterHasCheckinteger(), 1);
  assert.equal(luaEngineFourthIntGetterSiblingCount(), 1);
  assert.equal(luaEngineFourthIntGetterReturnValue(), 1);
  assert.equal(LUA_FOURTH_INT_GETTER_RETURN, 1);
  assert.equal(luaEngineFourthIntGetterNextVa(), 0x00898530);
  assert.equal(LUA_INLINE_NEXT_VA, LUA_FOURTH_NOARG_SETTER_NEXT_VA);

  // Skip assigned SEH 0x00897f50. v37 next stays the skipped SEH.
  assert.equal(luaEngineFourthIntBoolSetterNextVa(), 0x00897f50);
  assert.equal(luaEngineFourthIntGetterSkippedSehVa(), 0x00897f50);
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x00897f50);
  // Do not reopen 0x00897970 or 0x008977f0.
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x00897970);
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x008977f0);
  assert.notEqual(luaEngineFourthIntGetterSkippedCtorVa(), 0x00897970);
  assert.notEqual(luaEngineFourthIntGetterSkippedCtorVa(), 0x008977f0);
  assert.equal(luaEngineFourthNumberGetterNextVa(), 0x00897970);
  assert.equal(luaEngineFourthNumberSetterNextVa(), 0x008977f0);
  // Skip wrap/ctor 0x00898140 and unref 0x00898490.
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x00898140);
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x00898490);
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x00898f50);

  // Distinct from v32 integer setter: ret 1 / has_push / body 0x41 not 0x32.
  assert.notEqual(luaEngineFourthIntGetterBodyBytes(),
    luaEngineFourthSetterBodyBytes());
  assert.notEqual(luaEngineFourthIntGetterReturnValue(),
    luaEngineFourthSetterReturnValue());
  assert.notEqual(luaEngineFourthIntGetterHasPush(),
    luaEngineFourthSetterHasPush());
  assert.equal(luaEngineFourthIntGetterCheckintegerIndex(),
    luaEngineFourthSetterCheckintegerIndex());
  assert.equal(luaEngineFourthIntGetterStackClean(),
    luaEngineFourthSetterStackClean());
  // Distinct from v37 indexed bool setter: no toboolean, ret 1, stack 0x14.
  assert.notEqual(luaEngineFourthIntGetterBodyBytes(),
    luaEngineFourthIntBoolSetterBodyBytes());
  assert.notEqual(luaEngineFourthIntGetterReturnValue(),
    luaEngineFourthIntBoolSetterReturnValue());
  assert.notEqual(luaEngineFourthIntGetterHasPush(),
    luaEngineFourthIntBoolSetterHasPush());
  assert.notEqual(luaEngineFourthIntGetterStackClean(),
    luaEngineFourthIntBoolSetterStackClean());
  assert.equal(luaEngineFourthIntGetterCheckintegerIndex(),
    luaEngineFourthIntBoolSetterCheckintegerIndex());
  // Distinct from v34 boolean getter: pushinteger not pushboolean; checkinteger.
  assert.notEqual(luaEngineFourthIntGetterIatPushinteger(),
    luaEngineFourthBoolGetterIatLuaPushboolean());
  assert.notEqual(luaEngineFourthIntGetterHasCheckinteger(),
    luaEngineFourthBoolGetterHasCheckinteger());
  // Distinct from v36 number getter: pushinteger IAT, not host 0x85c050.
  assert.notEqual(luaEngineFourthIntGetterIatPushinteger(),
    luaEngineFourthNumberGetterHostVaPush());
  assert.notEqual(luaEngineFourthIntGetterVa(),
    luaEngineFourthNumberGetterVa());
  // Distinct from v31 getter: no FULL-WORD null gate.
  assert.notEqual(luaEngineFourthIntGetterHasNullGate(),
    LUA_FOURTH_GETTER_NULL_STILL_RETURNS);
  // Distinct from v27: no type / this-select.
  assert.notEqual(luaEngineFourthIntGetterHasTypeGate(),
    luaEngineBandCPrimaryTypeGateTaken(1));

  // cdq lua_Integer hi (v14 BY REFERENCE). Drive UNMASKED.
  assert.equal(luaEngineFourthIntGetterLuaIntegerHi(0), 0);
  assert.equal(luaEngineFourthIntGetterLuaIntegerHi(1), 0);
  assert.equal(luaEngineFourthIntGetterLuaIntegerHi(0x7fffffff), 0);
  assert.equal(luaEngineFourthIntGetterLuaIntegerHi(0x80000000), 0xffffffff);
  assert.equal(luaEngineFourthIntGetterLuaIntegerHi(0xffffffff), 0xffffffff);
  assert.equal(luaEngineFourthIntGetterLuaIntegerHi(0x80000000),
    luaEngineMaterializeLuaIntegerHi(0x80000000));
  // mutant: unsigned hi would treat 0x80000000 as 0.
  assert.notEqual(luaEngineFourthIntGetterLuaIntegerHi(0x80000000), 0);
  // mutant: claiming ret 0 would collapse this onto the v32 setter.
  assert.notEqual(luaEngineFourthIntGetterReturnValue(), 0);
  // mutant: claiming has_push 0 would collapse this onto the v32 setter.
  assert.notEqual(luaEngineFourthIntGetterHasPush(), 0);
  // mutant: claiming has_checkinteger 0 would collapse onto v34/v36 getters.
  assert.notEqual(luaEngineFourthIntGetterHasCheckinteger(), 0);
  // mutant: claiming checkinteger index 2 would collapse onto v29 secondaries.
  assert.notEqual(luaEngineFourthIntGetterCheckintegerIndex(), 2);
  // mutant: claiming a null gate would collapse this onto the v31 getter.
  assert.notEqual(luaEngineFourthIntGetterHasNullGate(), 1);
  // mutant: claiming siblings would invent a template that is not in the PE.
  assert.notEqual(luaEngineFourthIntGetterSiblingCount(), 2);
  // mutant: claiming the skipped SEH / ctor / fourth-region VA.
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x00897f50);
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x00897970);
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x008977f0);
  assert.notEqual(luaEngineFourthIntGetterVa(), 0x00898f50);
});

test("native/Wasm differential: ABI v38 indexed-int-getter cdq + mutant", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.fourthIntGetterVa() >>> 0, luaEngineFourthIntGetterVa());
  assert.equal(native.fourthIntGetterBodyBytes() >>> 0,
    luaEngineFourthIntGetterBodyBytes());
  assert.equal(native.fourthIntGetterCheckintegerIndex() >>> 0,
    luaEngineFourthIntGetterCheckintegerIndex());
  assert.equal(native.fourthIntGetterStackClean() >>> 0,
    luaEngineFourthIntGetterStackClean());
  assert.equal(native.fourthIntGetterStackCleanPush() >>> 0,
    luaEngineFourthIntGetterStackCleanPush());
  assert.equal(native.fourthIntGetterStackAlignMask() >>> 0,
    luaEngineFourthIntGetterStackAlignMask());
  assert.equal(native.fourthIntGetterSkippedSehVa() >>> 0,
    luaEngineFourthIntGetterSkippedSehVa());
  assert.equal(native.fourthIntGetterSkippedCtorVa() >>> 0,
    luaEngineFourthIntGetterSkippedCtorVa());
  assert.equal(native.fourthIntGetterTouserdataIndex() >>> 0,
    luaEngineFourthIntGetterTouserdataIndex());
  assert.equal(native.fourthIntGetterIatLuaTouserdata() >>> 0,
    luaEngineFourthIntGetterIatLuaTouserdata());
  assert.equal(native.fourthIntGetterIatCheckinteger() >>> 0,
    luaEngineFourthIntGetterIatCheckinteger());
  assert.equal(native.fourthIntGetterIatPushinteger() >>> 0,
    luaEngineFourthIntGetterIatPushinteger());
  assert.equal(native.fourthIntGetterHasTypeGate() | 0,
    luaEngineFourthIntGetterHasTypeGate());
  assert.equal(native.fourthIntGetterHasThisSelect() | 0,
    luaEngineFourthIntGetterHasThisSelect());
  assert.equal(native.fourthIntGetterHasNullGate() | 0,
    luaEngineFourthIntGetterHasNullGate());
  assert.equal(native.fourthIntGetterHasPush() | 0,
    luaEngineFourthIntGetterHasPush());
  assert.equal(native.fourthIntGetterHasCheckinteger() | 0,
    luaEngineFourthIntGetterHasCheckinteger());
  assert.equal(native.fourthIntGetterSiblingCount() | 0,
    luaEngineFourthIntGetterSiblingCount());
  assert.equal(native.fourthIntGetterReturnValue() >>> 0,
    luaEngineFourthIntGetterReturnValue());
  assert.equal(native.fourthIntGetterNextVa() >>> 0,
    luaEngineFourthIntGetterNextVa());
  assert.equal(native.fourthIntGetterNextVa() >>> 0, 0x00898530);

  // v31 BY REFERENCE: same touserdata index / IAT.
  assert.equal(native.fourthIntGetterTouserdataIndex() >>> 0,
    native.fourthGetterTouserdataIndex() >>> 0);
  assert.equal(native.fourthIntGetterIatLuaTouserdata() >>> 0,
    native.fourthGetterIatLuaTouserdata() >>> 0);
  // v32 BY REFERENCE: same checkinteger IAT; v22 BY REFERENCE: pushinteger IAT.
  assert.equal(native.fourthIntGetterIatCheckinteger() >>> 0, 0x00b183f4);
  assert.equal(native.fourthIntGetterIatPushinteger() >>> 0, 0x00b183f8);
  assert.notEqual(native.fourthIntGetterIatCheckinteger() >>> 0,
    native.fourthIntGetterIatPushinteger() >>> 0);

  const WIDE = [
    0, 1, 0xff, 0x100, 0x1ff, 0x1000, 0x7fffffff,
    0x80000000, 0xffffff00, 0xfffffffe, 0xffffffff,
  ];
  for (const v of WIDE) {
    assert.equal(native.fourthIntGetterLuaIntegerHi(v) >>> 0,
      luaEngineFourthIntGetterLuaIntegerHi(v),
      "cdq hi " + v);
    assert.equal(native.fourthIntGetterLuaIntegerHi(v) >>> 0,
      luaEngineMaterializeLuaIntegerHi(v),
      "v14 ref " + v);
  }
  // PE direction + mutant
  assert.equal(native.fourthIntGetterIatLuaTouserdata() >>> 0, 0x00b183b0);
  assert.notEqual(native.fourthIntGetterIatLuaTouserdata() >>> 0, 0x00b18324);
  assert.equal(native.fourthIntGetterHasCheckinteger() | 0, 1);
  assert.notEqual(native.fourthIntGetterHasCheckinteger() | 0, 0);
  assert.equal(native.fourthIntGetterHasPush() | 0, 1);
  assert.notEqual(native.fourthIntGetterHasPush() | 0, 0);
  assert.equal(native.fourthIntGetterHasNullGate() | 0, 0);
  assert.notEqual(native.fourthIntGetterHasNullGate() | 0, 1);
  assert.equal(native.fourthIntGetterHasTypeGate() | 0, 0);
  assert.equal(native.fourthIntGetterHasThisSelect() | 0, 0);
  assert.equal(native.fourthIntGetterSiblingCount() | 0, 1);
  assert.notEqual(native.fourthIntGetterSiblingCount() | 0, 2);
  assert.equal(native.fourthIntGetterReturnValue() >>> 0, 1);
  assert.notEqual(native.fourthIntGetterReturnValue() >>> 0, 0);
  assert.equal(native.fourthIntGetterVa() >>> 0, 0x008984e0);
  assert.notEqual(native.fourthIntGetterVa() >>> 0, 0x00897f50);
  assert.notEqual(native.fourthIntGetterVa() >>> 0, 0x00897970);
  assert.notEqual(native.fourthIntGetterVa() >>> 0, 0x008977f0);
  assert.equal(native.fourthIntGetterBodyBytes() >>> 0, 0x41);
  assert.equal(native.fourthIntGetterSkippedSehVa() >>> 0, 0x00897f50);
  assert.equal(native.fourthIntGetterLuaIntegerHi(0x80000000) >>> 0, 0xffffffff);
  assert.notEqual(native.fourthIntGetterLuaIntegerHi(0x80000000) >>> 0, 0);
});

