  assert.equal(luaEngineFourthNoargSetterBodyBytes(), 0x1c);
  assert.equal(luaEngineFourthNoargSetterStackClean(), 0x08);
  assert.equal(luaEngineFourthNoargSetterSkipCount(), 0);
  assert.equal(luaEngineFourthNoargSetterCodeUdVa(), 0x009e94e0);
  assert.equal(luaEngineFourthNoargSetterInstallerVa(), 0x00893270);
  assert.equal(luaEngineFourthNoargSetterTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineFourthNoargSetterTouserdataIndex(),
    luaEngineFourthGetterTouserdataIndex());
  assert.equal(luaEngineFourthNoargSetterIatLuaTouserdata(), 0x00b183b0);
