    "isaac_lua_engine_lua_ref_ref_off",
    "isaac_lua_engine_lua_ref_string_off",
    "isaac_lua_engine_lua_ref_dtor_string_tidy_va",
    "isaac_lua_engine_lua_ref_dtor_unref_iat_va",
