    "isaac_lua_engine_lua_ref_dtor_stack_cleanup",
    "isaac_lua_engine_lua_ref_dtor_ret_args",
    "isaac_lua_engine_lua_ref_dtor_reach_thunk_count",
    "isaac_lua_engine_lua_ref_dtor_reach_thunk_va_for_index",
