test("ABI v47 install-helper mutants: eight translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce;
   * every one was applied to the native source, the differential FAILED,
   * and the file was restored byte-identical (sha256-verified). The
   * permanent tripwire is assert.notEqual + the explicit PE truth. */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: shape(8) DUAL_IMM -> SINGLE would break the chain-count law for
  // Clamped (0x8a00c0 runs TWO rawset chains — pushvalue dup + absindex
  // -5 then -3, cleanups 0x40+0x24).
  assert.equal(luaEngineInstallSiteChainCount(12), 2);
  assert.notEqual(luaEngineInstallSiteChainCount(12), 1);
  assert.equal(native.installSiteChainCount(12) | 0, 2);
  assert.notEqual(native.installSiteChainCount(12) | 0, 1);
  // M2: 0x8a0400 name imm 0xb70244 -> 0xb70200 (Lerp vs Resize cross).
  // PE @ 0x8a042a: push 0xb70244 ("Lerp").
  assert.equal(luaEngineInstallHelperNameImmVa(3), 0x00b70244);
  assert.notEqual(luaEngineInstallHelperNameImmVa(3), 0x00b70200);
  assert.equal(native.installHelperNameImmVa(3) >>> 0, 0x00b70244);
  assert.notEqual(native.installHelperNameImmVa(3) >>> 0, 0x00b70200);
  // M3: 0x89fee0 real_fn imm 0x85e630 -> 0x85e640 (off-by-one
  // __tostring). PE @ 0x89fefc: mov dword ptr [eax], 0x85e630.
  assert.equal(luaEngineInstallHelperRealFnImmVa(11), 0x0085e630);
  assert.notEqual(luaEngineInstallHelperRealFnImmVa(11), 0x0085e640);
  assert.equal(native.installHelperRealFnImmVa(11) >>> 0, 0x0085e630);
  assert.notEqual(native.installHelperRealFnImmVa(11) >>> 0, 0x0085e640);
  // M4: wrapper 0x8a8430 -> 0x8a8310 (Rotated wrapper pin). PE @
  // 0x8a0381: push 0x8a8430.
  assert.equal(luaEngineInstallHelperWrapperVa(4), 0x008a8430);
  assert.notEqual(luaEngineInstallHelperWrapperVa(4), 0x008a8310);
  assert.equal(native.installHelperWrapperVa(4) >>> 0, 0x008a8430);
  assert.notEqual(native.installHelperWrapperVa(4) >>> 0, 0x008a8310);
  // M5: site helper idx 20 -> 10 (__tostring -> 0x89ff80 instead of
  // 0x89fee0). PE @ 0x00866c72: call 0x89fee0.
  assert.equal(luaEngineInstallSiteHelperIndex(20), 11);
  assert.notEqual(luaEngineInstallSiteHelperIndex(20), 10);
  assert.equal(native.installSiteHelperIndex(20) | 0, 11);
  assert.notEqual(native.installSiteHelperIndex(20) | 0, 10);
  // M6: 0x8a00c0 chain2 name from register [ebp-8] would make the
  // DUAL_IMM name source REGISTER and consume the passed operand. PE @
  // 0x8a012b: push 0xb70298 (imm) — the site operand is DEAD.
  assert.equal(luaEngineInstallHelperNameSource(8), LUA_INSTALL_SOURCE_IMMEDIATE);
  assert.notEqual(luaEngineInstallHelperNameSource(8), LUA_INSTALL_SOURCE_REGISTER);
  assert.equal(luaEngineInstallSiteConsumedNameVa(12, 0xdeadbeef), 0x00b70298);
  assert.notEqual(luaEngineInstallSiteConsumedNameVa(12, 0xdeadbeef), 0xdeadbeef);
  assert.equal(native.installHelperNameSource(8) | 0, LUA_INSTALL_SOURCE_IMMEDIATE);
  assert.equal(native.installSiteConsumedNameVa(12, 0xdeadbeef) >>> 0, 0x00b70298);
  assert.notEqual(native.installSiteConsumedNameVa(12, 0xdeadbeef) >>> 0, 0xdeadbeef);
  // M7: insn count 0x8a0020 74 -> 72 (template fold would also break the
  // site-9 mapping). PE dump: 0x8a0020 .. first_ret 0x008a00b6, 74 insns.
  assert.equal(luaEngineInstallHelperInsnCount(9), 74);
  assert.notEqual(luaEngineInstallHelperInsnCount(9), 72);
  assert.equal(native.installHelperInsnCount(9) | 0, 74);
  assert.notEqual(native.installHelperInsnCount(9) | 0, 72);
  // M8: body bytes 0x89ff80 -> 0x50 (dual->single fold). PE: ret
  // 0x008a0016 - VA 0x0089ff80 = 0x96 (two chains), not 0x50 (one).
  assert.equal(luaEngineInstallHelperBodyBytes(10), 0x96);
  assert.notEqual(luaEngineInstallHelperBodyBytes(10), 0x50);
  assert.equal(native.installHelperBodyBytes(10) >>> 0, 0x96);
  assert.notEqual(native.installHelperBodyBytes(10) >>> 0, 0x50);
});

test("JS oracle: ABI v48 wrapper bodies 0x8a8310..0x8a88f0 (9 closures)", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed branch-by-branch from the fresh
   * cpu-dump/008a8310.txt / 008a8430.txt / 008a8510.txt / 008a8580.txt /
   * 008a8610.txt / 008a8680.txt / 008a8740.txt / 008a8810.txt /
   * 008a88f0.txt + helper 008ba890.txt (lua-v51 notes). NOT derived from
   * the model or the C++.
   *
   * Shared arg conduct: L=[ebp+8]; lua_type(L,1) @0xb18400; FULL-WORD
   * gate (0 -> obj1=0); else push CHKFLAGS; push 0xc82980; edx=1; ecx=L;
   * call 0x85c590; obj1=[eax+4]; lua_touserdata(L, upvalueindex(1)
   * 0xfff0b9d7) @0xb183b0; fn=ud[0]; per-wrapper args -> ud[0](obj1,...);
   * per-wrapper tail. */
  const PE_VA = [0x008a8310, 0x008a8430, 0x008a8510, 0x008a8580,
    0x008a8610, 0x008a8680, 0x008a8740, 0x008a8810, 0x008a88f0];
  const PE_RET = [0x008a8412, 0x008a8508, 0x008a8578, 0x008a8601,
    0x008a867f, 0x008a873b, 0x008a880e, 0x008a88e2, 0x008a8951];
  const PE_INSNS = [87, 82, 50, 60, 51, 75, 78, 85, 42];
  const PE_FLAGS = [0x00, 0x01, 0x01, 0x00, 0x00, 0x01, 0x01, 0x01, 0x01];
  const PE_RETVAL = [1, 1, 1, 0, 0, 1, 1, 1, 1];
  const PE_TAIL = [LUA_WRAPPER_TAIL_BOX8, LUA_WRAPPER_TAIL_BOX10,
    LUA_WRAPPER_TAIL_FLOAT, LUA_WRAPPER_TAIL_VOID, LUA_WRAPPER_TAIL_VOID,
    LUA_WRAPPER_TAIL_BOX10, LUA_WRAPPER_TAIL_BOX10,
    LUA_WRAPPER_TAIL_BOX10, LUA_WRAPPER_TAIL_PUSHSTRING];
  assert.equal(luaEngineWrapperCount(), 9);
  assert.equal(LUA_WRAPPER_COUNT, 9);
  // linkage law: wrapper va(index) == install-helper wrapper literal
  // LUA_INSTALL_HELPER_WRAPPER_VAS[3 + index] (helpers 3..11).
  for (let i = 0; i < 9; i += 1) {
    assert.equal(LUA_WRAPPER_VAS[i], LUA_INSTALL_HELPER_WRAPPER_VAS[3 + i],
      "helper-link " + i);
  }
  for (let i = 0; i < 9; i += 1) {
    assert.equal(luaEngineWrapperVa(i), PE_VA[i], "va " + i);
    assert.equal(luaEngineWrapperRetVa(i), PE_RET[i], "ret " + i);
    assert.equal(luaEngineWrapperBodyBytes(i), PE_RET[i] - PE_VA[i],
      "body " + i);
    assert.equal(luaEngineWrapperInsnCount(i), PE_INSNS[i], "insns " + i);
    assert.equal(luaEngineWrapperCheckFlags(i), PE_FLAGS[i], "flags " + i);
    assert.equal(luaEngineWrapperReturnValue(i), PE_RETVAL[i], "retval " + i);
    assert.equal(luaEngineWrapperTailKind(i), PE_TAIL[i], "tail " + i);
  }
  for (const bad of [-1, 9, 99]) {
    assert.equal(luaEngineWrapperVa(bad), 0);
    assert.equal(luaEngineWrapperRetVa(bad), 0);
    assert.equal(luaEngineWrapperBodyBytes(bad), 0);
    assert.equal(luaEngineWrapperInsnCount(bad), -1);
    assert.equal(luaEngineWrapperCheckFlags(bad), -1);
    assert.equal(luaEngineWrapperReturnValue(bad), -1);
    assert.equal(luaEngineWrapperTailKind(bad), -1);
    assert.equal(luaEngineWrapperArg2Kind(bad), -1);
  }
  // arg2 conduct: 0/6 getArgObject(2) -> {obj2[0],obj2[4]} vec2;
  // 1/3/7 checknumber(2) -> f32; 4/5 getArgVector (2..5); 2/8 none.
  assert.equal(luaEngineWrapperArg2Kind(0), LUA_WRAPPER_ARG2_GET_ARG_OBJECT_VEC2);
  assert.equal(luaEngineWrapperArg2Kind(1), LUA_WRAPPER_ARG2_CHECKNUMBER_F32);
  assert.equal(luaEngineWrapperArg2Kind(2), LUA_WRAPPER_ARG2_NONE);
  assert.equal(luaEngineWrapperArg2Kind(4), LUA_WRAPPER_ARG2_GET_ARG_VECTOR);
  assert.equal(luaEngineWrapperArg2Kind(5), LUA_WRAPPER_ARG2_GET_ARG_VECTOR);
  assert.equal(luaEngineWrapperArg2Kind(6), LUA_WRAPPER_ARG2_GET_ARG_OBJECT_VEC2);
  assert.equal(luaEngineWrapperArg2Kind(7), LUA_WRAPPER_ARG2_CHECKNUMBER_F32);
  assert.equal(luaEngineWrapperArg2Kind(8), LUA_WRAPPER_ARG2_NONE);
  assert.equal(luaEngineWrapperArg2Index(0), 2);
  assert.equal(luaEngineWrapperArg2Index(1), 2);
  assert.equal(luaEngineWrapperArg2Index(2), 0);
  assert.equal(luaEngineWrapperArg2Index(4), 2); // getArgVector reads 2..5
  assert.equal(luaEngineWrapperArg3Kind(0), LUA_WRAPPER_ARG3_CHECKNUMBER_F32);
  assert.equal(luaEngineWrapperArg3Kind(1), LUA_WRAPPER_ARG3_NONE);
  assert.equal(luaEngineWrapperArg3Index(0), 3); // Lerp t
  assert.equal(luaEngineWrapperArg4Index(0), 4); // Lerp toboolean flag
  assert.equal(luaEngineWrapperArg4Index(1), 0);
  // shared arg conduct.
  assert.equal(luaEngineWrapperTypeIndex(), 0x01);
  assert.equal(luaEngineWrapperCheckStackIndex(), 0x01);
  assert.equal(luaEngineWrapperRegistryKey(), 0x00c82980);
  assert.equal(luaEngineWrapperObjectFieldOff(), 0x04);
  assert.equal(luaEngineWrapperTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineWrapperFnOff(), 0x00);
  assert.equal(luaEngineWrapperCheckHelperVa(), 0x0085c590);
  assert.equal(luaEngineWrapperGetArgObjectVa(), 0x008baa50);
  assert.equal(luaEngineWrapperPushNumberVa(), 0x0085c050);
  assert.equal(luaEngineWrapperIatLuaType(), 0x00b18400);
  assert.equal(luaEngineWrapperIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineWrapperIatLuaChecknumber(), 0x00b18324);
  assert.equal(luaEngineWrapperIatLuaToboolean(), 0x00b183e8);
  // FULL-WORD object gate: `test eax,eax; je obj_zero` — only 0
  // short-circuits; 0x100/0x1ff/0xffffffff all resolve to the field.
  assert.equal(luaEngineWrapperObjectResolve(0, 0xdeadbeef), 0);
  assert.equal(luaEngineWrapperObjectResolve(0x100, 0x1234), 0x1234);
  assert.equal(luaEngineWrapperObjectResolve(0x1ff, 0xffffffff), 0xffffffff);
  assert.equal(luaEngineWrapperObjectResolve(0xffffffff, 0x7), 0x7);
  assert.equal(luaEngineWrapperObjectResolve(1, 0), 0);
  // getArgObject two-gate law (v45 same helper): type==0 -> 0; field==0
  // -> 0; else field. FULL-WORD both.
  assert.equal(luaEngineWrapperArg2GetArgObject(0, 0xdeadbeef), 0);
  assert.equal(luaEngineWrapperArg2GetArgObject(0x100, 0), 0);
  assert.equal(luaEngineWrapperArg2GetArgObject(0x100, 0x1234), 0x1234);
  assert.equal(luaEngineWrapperArg2GetArgObject(0xffffffff, 0xffffffff), 0xffffffff);
  // toboolean flag: `test eax,eax; setne byte` FULL-WORD (0x100 -> 1).
  assert.equal(luaEngineWrapperTobooleanFlag(0), 0);
  assert.equal(luaEngineWrapperTobooleanFlag(1), 1);
  assert.equal(luaEngineWrapperTobooleanFlag(0x100), 1);
  assert.equal(luaEngineWrapperTobooleanFlag(0xffffffff), 1);
  // FLOAT tail narrowing: fstp dword [ebp-4] double->float32 RN.
  assert.equal(luaEngineWrapperFloatF32Bits(0x3ff00000, 0x00000000), 0x3f800000);
  assert.equal(luaEngineWrapperFloatF32Bits(0x3fb99999, 0x9999999a), 0x3dcccccd);
  assert.equal(luaEngineWrapperFloatF32Bits(0xc0000000, 0x00000000), 0xc0000000);
  assert.equal(luaEngineWrapperFloatF32Bits(0x7ff00000, 0x00000000), 0x7f800000);
  assert.equal(luaEngineWrapperFloatF32Bits(0x80000000, 0x00000000), 0x80000000);
  // BOX10 tail (Rotated/Clamped/__add/__mul — same as v45 wrapper #2).
  assert.equal(luaEngineWrapperBox10NewuserdataSize(), 0x10);
  assert.equal(luaEngineWrapperBox10VtableTagVa(), 0x00b73574);
  assert.equal(luaEngineWrapperBox10PayloadSelfOff(), 0x04);
  assert.equal(luaEngineWrapperBox10PayloadOff(), 0x08);
  assert.equal(luaEngineWrapperBox10MetatableRawgetpKey(), 0x00c82980);
  assert.equal(luaEngineWrapperBox10RegistryIndex(), 0xfff0b9d8);
  assert.equal(luaEngineWrapperBox10SetmetaIndex(), 0xfffffffe);
  assert.equal(luaEngineWrapperBox10PayloadLoOff(), 0x00);
  assert.equal(luaEngineWrapperBox10PayloadHiOff(), 0x04);
  // BOX8 tail (Lerp) — DIFFERENT vtable + metatable key.
  assert.equal(luaEngineWrapperBox8NewuserdataSize(), 0x08);
  assert.equal(luaEngineWrapperBox8VtableTagVa(), 0x00b753c8);
  assert.equal(luaEngineWrapperBox8PayloadOff(), 0x04);
  assert.equal(luaEngineWrapperBox8MetatableRawgetpKey(), 0x00c8297f);
  assert.equal(luaEngineWrapperBox8RegistryIndex(), 0xfff0b9d8);
  assert.equal(luaEngineWrapperBox8SetmetaIndex(), 0xfffffffe);
  // FLOAT tail slot [ebp-4] + PUSHSTRING IAT pins.
  assert.equal(luaEngineWrapperFloatSlotStackOff(), 0xfffffffc);
  assert.equal(luaEngineWrapperPushstringIatLuaPushstring(), 0x00b18414);
  assert.equal(luaEngineWrapperPushstringIatLuaPushnil(), 0x00b183e0);
  // getArgVector helper 0x8ba890: call order [5,4,3,2], out positions
  // 0..3 read luaL_checknumber(L, pos+2), f32 stride 4, out[16]=L dead.
  assert.equal(luaEngineWrapperGetArgVectorVa(), 0x008ba890);
  assert.equal(luaEngineWrapperGetArgVectorRetVa(), 0x008ba8f6);
  assert.equal(luaEngineWrapperGetArgVectorBodyBytes(), 0x66);
  assert.equal(luaEngineWrapperGetArgVectorInsnCount(), 51);
  assert.deepEqual(LUA_WRAPPER_GET_ARG_VECTOR_CALL_ORDER, [5, 4, 3, 2]);
  for (let p = 0; p < 4; p += 1) {
    assert.equal(luaEngineWrapperGetArgVectorCallOrderAt(p), 5 - p,
      "call order " + p);
    assert.equal(luaEngineWrapperGetArgVectorIndexAt(p), p + 2,
      "out index " + p);
  }
  assert.equal(luaEngineWrapperGetArgVectorCallOrderAt(4), 0);
  assert.equal(luaEngineWrapperGetArgVectorIndexAt(4), 0);
  assert.equal(luaEngineWrapperGetArgVectorIndexAt(-1), 0);
  assert.equal(luaEngineWrapperGetArgVectorOutF32Count(), 4);
  assert.equal(luaEngineWrapperGetArgVectorOutStride(), 4);
  assert.equal(luaEngineWrapperGetArgVectorOutLPtrOff(), 0x10);
  assert.equal(luaEngineWrapperGetArgVectorRetArgs(), 4);
});

test("native/Wasm differential: ABI v48 wrapper bodies + gates WIDE drive", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.abi() | 0, LUA_ENGINE_PURE_ABI_VERSION);
  assert.equal(native.wrapperCount() | 0, 9);
  for (let i = 0; i < 9; i += 1) {
    assert.equal(native.wrapperVa(i) >>> 0, luaEngineWrapperVa(i));
    assert.equal(native.wrapperRetVa(i) >>> 0, luaEngineWrapperRetVa(i));
    assert.equal(native.wrapperBodyBytes(i) >>> 0, luaEngineWrapperBodyBytes(i));
    assert.equal(native.wrapperInsnCount(i) | 0, luaEngineWrapperInsnCount(i));
    assert.equal(native.wrapperCheckFlags(i) | 0, luaEngineWrapperCheckFlags(i));
    assert.equal(native.wrapperReturnValue(i) | 0,
      luaEngineWrapperReturnValue(i));
    assert.equal(native.wrapperArg2Kind(i) | 0, luaEngineWrapperArg2Kind(i));
    assert.equal(native.wrapperArg2Index(i) | 0, luaEngineWrapperArg2Index(i));
    assert.equal(native.wrapperArg3Kind(i) | 0, luaEngineWrapperArg3Kind(i));
    assert.equal(native.wrapperArg3Index(i) | 0, luaEngineWrapperArg3Index(i));
    assert.equal(native.wrapperArg4Index(i) | 0, luaEngineWrapperArg4Index(i));
    assert.equal(native.wrapperTailKind(i) | 0, luaEngineWrapperTailKind(i));
  }
  assert.equal(native.wrapperVa(9) | 0, 0);
  assert.equal(native.wrapperVa(-1) | 0, 0);
  assert.equal(native.wrapperInsnCount(99) | 0, -1);
  assert.equal(native.wrapperTailKind(99) | 0, -1);
  assert.equal(native.wrapperTypeIndex() >>> 0, 0x01);
  assert.equal(native.wrapperCheckStackIndex() >>> 0, 0x01);
  assert.equal(native.wrapperRegistryKey() >>> 0, 0x00c82980);
  assert.equal(native.wrapperObjectFieldOff() >>> 0, 0x04);
  assert.equal(native.wrapperTouserdataIndex() >>> 0, 0xfff0b9d7);
  assert.equal(native.wrapperFnOff() >>> 0, 0x00);
  assert.equal(native.wrapperCheckHelperVa() >>> 0, 0x0085c590);
  assert.equal(native.wrapperGetArgObjectVa() >>> 0, 0x008baa50);
  assert.equal(native.wrapperPushNumberVa() >>> 0, 0x0085c050);
  assert.equal(native.wrapperIatLuaType() >>> 0, 0x00b18400);
  assert.equal(native.wrapperIatLuaTouserdata() >>> 0, 0x00b183b0);
  assert.equal(native.wrapperIatLuaChecknumber() >>> 0, 0x00b18324);
  assert.equal(native.wrapperIatLuaToboolean() >>> 0, 0x00b183e8);
  // FULL-WORD gates: WIDE UNMASKED drive.
  const WIDE = [0x100, 0x1ff, 0xffffffff, 0x7fffffff, 0xff, 0x00];
  for (const typeResult of WIDE) {
    for (const checkField of WIDE) {
      const got = native.wrapperObjectResolve(typeResult, checkField) >>> 0;
      const want = luaEngineWrapperObjectResolve(typeResult, checkField);
      assert.equal(got, want,
        `resolve type=${(typeResult >>> 0).toString(16)} ` +
        `field=${(checkField >>> 0).toString(16)}`);
      const ga = native.wrapperArg2GetArgObject(typeResult, checkField) >>> 0;
      const wa = luaEngineWrapperArg2GetArgObject(typeResult, checkField);
      assert.equal(ga, wa,
        `getArgObject type=${(typeResult >>> 0).toString(16)} ` +
        `field=${(checkField >>> 0).toString(16)}`);
    }
  }
  for (const tobool of WIDE) {
    assert.equal(native.wrapperTobooleanFlag(tobool) >>> 0,
      luaEngineWrapperTobooleanFlag(tobool));
  }
  // FLOAT tail narrowing across the boundary.
  const F64_CASES = [
    [0x3ff00000, 0x00000000, 0x3f800000], // 1.0
    [0x3fb99999, 0x9999999a, 0x3dcccccd], // 0.1
    [0xc0000000, 0x00000000, 0xc0000000], // -2.0
    [0x7ff00000, 0x00000000, 0x7f800000], // +inf
    [0x80000000, 0x00000000, 0x80000000], // -0.0
    [0x400921fb, 0x54442d18, 0x40490fdb], // pi
  ];
  for (const [hi, lo, want] of F64_CASES) {
    assert.equal(native.wrapperFloatF32Bits(hi, lo) >>> 0, want,
      "fstp f32 " + hi.toString(16) + "_" + lo.toString(16));
    assert.equal(native.wrapperFloatF32Bits(hi, lo) >>> 0,
      luaEngineWrapperFloatF32Bits(hi, lo), "model fstp f32");
  }
  // Box/pushnumber/pushstring constants across the boundary.
  assert.equal(native.wrapperBox10NewuserdataSize() >>> 0, 0x10);
  assert.equal(native.wrapperBox10VtableTagVa() >>> 0, 0x00b73574);
  assert.equal(native.wrapperBox10PayloadSelfOff() >>> 0, 0x04);
  assert.equal(native.wrapperBox10PayloadOff() >>> 0, 0x08);
  assert.equal(native.wrapperBox10MetatableRawgetpKey() >>> 0, 0x00c82980);
  assert.equal(native.wrapperBox10RegistryIndex() >>> 0, 0xfff0b9d8);
  assert.equal(native.wrapperBox10SetmetaIndex() >>> 0, 0xfffffffe);
  assert.equal(native.wrapperBox10PayloadLoOff() >>> 0, 0x00);
  assert.equal(native.wrapperBox10PayloadHiOff() >>> 0, 0x04);
  assert.equal(native.wrapperBox8NewuserdataSize() >>> 0, 0x08);
  assert.equal(native.wrapperBox8VtableTagVa() >>> 0, 0x00b753c8);
  assert.equal(native.wrapperBox8PayloadOff() >>> 0, 0x04);
  assert.equal(native.wrapperBox8MetatableRawgetpKey() >>> 0, 0x00c8297f);
  assert.equal(native.wrapperBox8RegistryIndex() >>> 0, 0xfff0b9d8);
  assert.equal(native.wrapperBox8SetmetaIndex() >>> 0, 0xfffffffe);
  assert.equal(native.wrapperFloatSlotStackOff() >>> 0, 0xfffffffc);
  assert.equal(native.wrapperPushstringIatLuaPushstring() >>> 0, 0x00b18414);
  assert.equal(native.wrapperPushstringIatLuaPushnil() >>> 0, 0x00b183e0);
  // getArgVector helper across the boundary.
  assert.equal(native.wrapperGetArgVectorVa() >>> 0, 0x008ba890);
  assert.equal(native.wrapperGetArgVectorRetVa() >>> 0, 0x008ba8f6);
  assert.equal(native.wrapperGetArgVectorBodyBytes() >>> 0, 0x66);
  assert.equal(native.wrapperGetArgVectorInsnCount() | 0, 51);
  for (let p = 0; p < 4; p += 1) {
    assert.equal(native.wrapperGetArgVectorCallOrderAt(p) | 0,
      luaEngineWrapperGetArgVectorCallOrderAt(p));
    assert.equal(native.wrapperGetArgVectorIndexAt(p) | 0,
      luaEngineWrapperGetArgVectorIndexAt(p));
  }
  assert.equal(native.wrapperGetArgVectorCallOrderAt(4) | 0, 0);
  assert.equal(native.wrapperGetArgVectorOutF32Count() | 0, 4);
  assert.equal(native.wrapperGetArgVectorOutStride() | 0, 4);
  assert.equal(native.wrapperGetArgVectorOutLPtrOff() | 0, 0x10);
  assert.equal(native.wrapperGetArgVectorRetArgs() | 0, 4);
});

