test("ABI v49 FontRenderSettings wrapper mutants: five translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce;
   * every one was applied to the native source, the v49 differential
   * FAILED, and the file was restored byte-identical (sha256-verified).
   * The permanent tripwire is assert.notEqual + the explicit PE truth. */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: registry key 0xc82986 -> 0xc82980 (fold to the v48 Vector key).
  // PE @ 0x8a89fe / 0x8a8a5f: push 0xc82986 — the FontRenderSettings
  // identity key, +6 vs 0xc82980.
  assert.equal(luaEngineFontsettingsWrapperRegistryKey(), 0x00c82986);
  assert.notEqual(luaEngineFontsettingsWrapperRegistryKey(), 0x00c82980);
  assert.equal(native.fontsettingsWrapperRegistryKey() >>> 0, 0x00c82986);
  assert.notEqual(native.fontsettingsWrapperRegistryKey() >>> 0, 0x00c82980);
  // M2: setter arg2 LOW-WORD mask -> byte mask (0xff). PE @ 0x8a8a90:
  // movzx edx, ax — 0x100 must SURVIVE the mask (a byte mask kills it).
  assert.equal(luaEngineFontsettingsWrapperArg2LowWord(0x100), 0x100);
  assert.notEqual(luaEngineFontsettingsWrapperArg2LowWord(0x100), 0x00);
  assert.equal(native.fontsettingsWrapperArg2LowWord(0x100) >>> 0, 0x100);
  assert.notEqual(native.fontsettingsWrapperArg2LowWord(0x100) >>> 0, 0x00);
  assert.equal(luaEngineFontsettingsWrapperArg2LowWord(0x10000), 0x00);
  assert.notEqual(luaEngineFontsettingsWrapperArg2LowWord(0x10000), 0x10000);
  assert.equal(native.fontsettingsWrapperArg2LowWord(0x10000) >>> 0, 0x00);
  assert.notEqual(native.fontsettingsWrapperArg2LowWord(0x10000) >>> 0, 0x10000);
  // M3: getter cdq hi -> always 0 (unsigned pushinteger). PE @ 0x8a8a2a:
  // cdq — negative fn return must sign-extend into the hi dword.
  assert.equal(luaEngineFontsettingsWrapperGetterLuaIntegerHi(0x80000000), 0xffffffff);
  assert.notEqual(luaEngineFontsettingsWrapperGetterLuaIntegerHi(0x80000000), 0x00);
  assert.equal(luaEngineFontsettingsWrapperGetterLuaIntegerHi(0x7fffffff), 0x00);
  assert.notEqual(luaEngineFontsettingsWrapperGetterLuaIntegerHi(0x7fffffff), 0xffffffff);
  assert.equal(native.fontsettingsWrapperGetterLuaIntegerHi(0x80000000) >>> 0, 0xffffffff);
  assert.notEqual(native.fontsettingsWrapperGetterLuaIntegerHi(0x80000000) >>> 0, 0x00);
  assert.equal(native.fontsettingsWrapperGetterLuaIntegerHi(0x7fffffff) >>> 0, 0x00);
  assert.notEqual(native.fontsettingsWrapperGetterLuaIntegerHi(0x7fffffff) >>> 0, 0xffffffff);
  // M4: object_resolve byte-masked would return 0 for 0x100. FULL-WORD
  // gate (PE `test eax,eax` — the low byte of 0x100 is 0).
  assert.equal(luaEngineFontsettingsWrapperObjectResolve(0x100, 0x1234), 0x1234);
  assert.notEqual(luaEngineFontsettingsWrapperObjectResolve(0x100, 0x1234), 0x00);
  assert.equal(native.fontsettingsWrapperObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.notEqual(native.fontsettingsWrapperObjectResolve(0x100, 0x1234) >>> 0, 0x00);
  // M5: GetAlignment check_flags 1 -> 0 (arg1 gate flip). PE @ 0x8a89fc:
  // push 1 (flags 1) before key 0xc82986; the setter pushes 0 @ 0x8a8a5d.
  assert.equal(luaEngineFontsettingsWrapperCheckFlags(0), 0x01);
  assert.notEqual(luaEngineFontsettingsWrapperCheckFlags(0), 0x00);
  assert.equal(native.fontsettingsWrapperCheckFlags(0) | 0, 0x01);
  assert.notEqual(native.fontsettingsWrapperCheckFlags(0) | 0, 0x00);
  assert.equal(luaEngineFontsettingsWrapperCheckFlags(1), 0x00);
  assert.notEqual(luaEngineFontsettingsWrapperCheckFlags(1), 0x01);
  assert.equal(native.fontsettingsWrapperCheckFlags(1) | 0, 0x00);
  assert.notEqual(native.fontsettingsWrapperCheckFlags(1) | 0, 0x01);
});
test("JS oracle: ABI v51 FontRenderSettings Load wrapper 0x8a8ce0 + band bodies 0x8a8970..0x8a9180", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed branch-by-branch from the fresh
   * cpu-dump/008a8970.txt / 008a8ab0.txt / 008a8b10.txt / 008a8b80.txt /
   * 008a8c10.txt / 008a8c80.txt / 008a8ce0.txt + 008a8d54.txt (Load full
   * true body) / 008a8d80.txt / 008a8dd0.txt / 008a8e40.txt / 008a8ec0.txt /
   * 008a8f60.txt / 008a9180.txt (lua-v54 notes) — NOT derived from the
   * model or the C++.
   *
   * Load 0x8a8ce0 (62 insns, TRUE tail ret 0x8a8d75; MID-BODY RET TRAP
   * 0x8a8d53 reachable only from the nil path — `jne 0x8a8d54` @0x8a8d3e
   * branches past it):
   *   L=[ebp+8]; lua_type(L,1) @0xb18400; FULL-WORD gate; je obj=0 else
   *   push 0 (CHKFLAGS); push 0xc82989 (BETA key); mov edx,1; ecx=L;
   *   call 0x85c590; obj=[eax+4]; push 0xfff0b9d7; push L;
   *   call [0xb183b0] touserdata; push 2; push L; call [0xb18400]
   *   lua_type(L,2); add esp,0x10; FULL-WORD gate: je -> push 0 (NULL);
   *   jne -> push 0; push 2; push L; call [0xb183e4] luaL_checklstring
   *   (L,2,NULL); add esp,0xc -> push eax (str); fn=ud[0]; ecx=obj;
   *   call fn(obj, str); xor eax,eax; ret 0. Both paths void, ret 0. */
  const PE_WRAP = [ /* index 2..14 (0..1 landed in v49) */
    [0x008a8970, 0x008a89db, 52, 0, 0, LUA_FONTSETTINGS_WRAPPER_ARG2_CHECKINTEGER_FULLWORD, 2, LUA_FONTSETTINGS_WRAPPER_TAIL_VOID, 0, 0x00c82986],
    [0x008a8ab0, 0x008a8b0b, 46, 1, 1, LUA_FONTSETTINGS_WRAPPER_ARG2_NONE, 0, LUA_FONTSETTINGS_WRAPPER_TAIL_PUSHINT_HELPER, 0x0085c010, 0x00c82986],
    [0x008a8b10, 0x008a8b74, 53, 1, 1, LUA_FONTSETTINGS_WRAPPER_ARG2_NONE, 0, LUA_FONTSETTINGS_WRAPPER_TAIL_PUSHBOOLEAN, 0x00b183ec, 0x00c82986],
    [0x008a8b80, 0x008a8c01, 60, 0, 0, LUA_FONTSETTINGS_WRAPPER_ARG2_CHECKNUMBER_F32, 2, LUA_FONTSETTINGS_WRAPPER_TAIL_VOID, 0, 0x00c82986],
    [0x008a8c10, 0x008a8c78, 51, 1, 1, LUA_FONTSETTINGS_WRAPPER_ARG2_NONE, 0, LUA_FONTSETTINGS_WRAPPER_TAIL_PUSHNUMBER_F32, 0x0085c050, 0x00c82986],
    [0x008a8c80, 0x008a8cdb, 45, 1, 1, LUA_FONTSETTINGS_WRAPPER_ARG2_NONE, 0, LUA_FONTSETTINGS_WRAPPER_TAIL_PUSHINT_HELPER, 0x0085bff0, 0x00c82986],
    [0x008a8ce0, 0x008a8d75, 62, 0, 0, LUA_FONTSETTINGS_WRAPPER_ARG2_CHECKLSTRING_GATED, 2, LUA_FONTSETTINGS_WRAPPER_TAIL_VOID, 0, 0x00c82989],
    [0x008a8d80, 0x008a8dcf, 40, 0, 0, LUA_FONTSETTINGS_WRAPPER_ARG2_NONE, 0, LUA_FONTSETTINGS_WRAPPER_TAIL_VOID, 0, 0x00c82989],
    [0x008a8dd0, 0x008a8e34, 53, 1, 1, LUA_FONTSETTINGS_WRAPPER_ARG2_NONE, 0, LUA_FONTSETTINGS_WRAPPER_TAIL_PUSHBOOLEAN, 0x00b183ec, 0x00c82989],
    [0x008a8e40, 0x008a8eb5, 60, 1, 1, LUA_FONTSETTINGS_WRAPPER_ARG2_CHECKLSTRING_BYTE, 2, LUA_FONTSETTINGS_WRAPPER_TAIL_PUSHINT_HELPER, 0x0085bff0, 0x00c82989],
    [0x008a8ec0, 0x008a8f51, 67, 1, 1, LUA_FONTSETTINGS_WRAPPER_ARG2_CHECKLSTRING_GATED, 2, LUA_FONTSETTINGS_WRAPPER_TAIL_PUSHINTEGER_HI0, 0x00b183f8, 0x00c82989],
    [0x008a8f60, 0x008a8fbb, 44, 1, 1, LUA_FONTSETTINGS_WRAPPER_ARG2_NONE, 0, LUA_FONTSETTINGS_WRAPPER_TAIL_PUSHINT_HELPER, 0x0085bff0, 0x00c82989],
    [0x008a9180, 0x008a91eb, 52, 0, 0, LUA_FONTSETTINGS_WRAPPER_ARG2_CHECKINTEGER_FULLWORD, 2, LUA_FONTSETTINGS_WRAPPER_TAIL_VOID, 0, 0x00c82989],
  ];
  assert.equal(luaEngineFontsettingsWrapperCount(), 15);
  assert.equal(LUA_FONTSETTINGS_WRAPPER_COUNT, 15);
  for (let i = 0; i < PE_WRAP.length; i += 1) {
    const idx = i + 2;
    const [va, ret, insns, flags, retval, arg2k, arg2i, tail, helper, key] = PE_WRAP[i];
    assert.equal(luaEngineFontsettingsWrapperVa(idx), va, "va " + idx);
    assert.equal(luaEngineFontsettingsWrapperRetVa(idx), ret, "ret " + idx);
    assert.equal(luaEngineFontsettingsWrapperBodyBytes(idx), ret - va, "body " + idx);
    assert.equal(luaEngineFontsettingsWrapperInsnCount(idx), insns, "insns " + idx);
    assert.equal(luaEngineFontsettingsWrapperCheckFlags(idx), flags, "flags " + idx);
    assert.equal(luaEngineFontsettingsWrapperReturnValue(idx), retval, "retval " + idx);
    assert.equal(luaEngineFontsettingsWrapperArg2Kind(idx), arg2k, "arg2kind " + idx);
    assert.equal(luaEngineFontsettingsWrapperArg2Index(idx), arg2i, "arg2idx " + idx);
    assert.equal(luaEngineFontsettingsWrapperTailKind(idx), tail, "tail " + idx);
    assert.equal(luaEngineFontsettingsWrapperTailHelperVa(idx), helper, "tailhelp " + idx);
    assert.equal(luaEngineFontsettingsWrapperRegistryKeyAt(idx), key, "key " + idx);
  }
  // LOAD-specific geometry: trap ret vs TRUE tail ret; body bytes use the
  // true ret (0x8a8d75 - 0x8a8ce0 = 0x95), and the mid-body trap is
  // exposed separately.
  assert.equal(luaEngineFontsettingsWrapperVa(8), 0x008a8ce0);
  assert.equal(luaEngineFontsettingsWrapperRetVa(8), 0x008a8d75);
  assert.equal(luaEngineFontsettingsWrapperFirstRetVa(8), 0x008a8d53);
  assert.notEqual(luaEngineFontsettingsWrapperFirstRetVa(8),
    luaEngineFontsettingsWrapperRetVa(8));
  assert.equal(luaEngineFontsettingsWrapperBodyBytes(8), 0x95);
  assert.equal(luaEngineFontsettingsWrapperFirstRetVa(0), 0x008a8a3f);
  assert.equal(luaEngineFontsettingsWrapperFirstRetVa(14), 0x008a91eb);
  assert.equal(luaEngineFontsettingsWrapperFirstRetVa(15), 0);
  // registry keys: alpha band 0..7, beta band 8..14 (Load install run).
  assert.equal(LUA_FONTSETTINGS_WRAPPER_REGISTRY_KEY_ALPHA, 0x00c82986);
  assert.equal(LUA_FONTSETTINGS_WRAPPER_REGISTRY_KEY_BETA, 0x00c82989);
  assert.equal(luaEngineFontsettingsWrapperRegistryKeyAt(0), 0x00c82986);
  assert.equal(luaEngineFontsettingsWrapperRegistryKeyAt(7), 0x00c82986);
  assert.equal(luaEngineFontsettingsWrapperRegistryKeyAt(8), 0x00c82989);
  assert.equal(luaEngineFontsettingsWrapperRegistryKeyAt(14), 0x00c82989);
  assert.equal(luaEngineFontsettingsWrapperRegistryKeyAt(15), 0);
  assert.equal(luaEngineFontsettingsWrapperRegistryKeyAt(-1), 0);
  // tail helpers: GetMaxCharacters push-u16-zext 0x85c010, bool wrappers
  // pushboolean IAT 0xb183ec, GetLineHeightModifier pushNumber 0x85c050,
  // u32-zext pushers 0x85bff0, GetStringWidth pushinteger IAT 0xb183f8.
  assert.equal(luaEngineFontsettingsWrapperTailHelperVa(3), 0x0085c010);
  assert.equal(luaEngineFontsettingsWrapperTailHelperVa(4), 0x00b183ec);
  assert.equal(luaEngineFontsettingsWrapperTailHelperVa(6), 0x0085c050);
  assert.equal(luaEngineFontsettingsWrapperTailHelperVa(7), 0x0085bff0);
  assert.equal(luaEngineFontsettingsWrapperTailHelperVa(8), 0);
  assert.equal(luaEngineFontsettingsWrapperTailHelperVa(11), 0x0085bff0);
  assert.equal(luaEngineFontsettingsWrapperTailHelperVa(12), 0x00b183f8);
  assert.equal(luaEngineFontsettingsWrapperTailHelperVa(15), 0);
  // new IAT pins: luaL_checklstring(L,idx,&len) 0xb183e4 (stub 0x7f4d72,
  // between pushnil 0x7f4d86 and toboolean 0x7f4d62) and lua_pushboolean
  // 0xb183ec (stub 0x7f4d50).
  assert.equal(luaEngineFontsettingsWrapperIatLuaChecklstring(), 0x00b183e4);
  assert.equal(luaEngineFontsettingsWrapperIatLuaPushboolean(), 0x00b183ec);
  // cleanups.
  assert.equal(luaEngineFontsettingsWrapperSecondTypeClean(), 0x10);
  assert.equal(luaEngineFontsettingsWrapperChecklstringClean(), 0x0c);
  assert.equal(luaEngineFontsettingsWrapperCharbyteStackClean(), 0x14);
  assert.equal(luaEngineFontsettingsWrapperPushintegerHi0(), 0);
  assert.equal(luaEngineFontsettingsWrapperPushintegerHi0Clean(), 0x0c);

  // ---- gate laws, driven WIDE UNMASKED (byte/full-word folds fail) ----
  // CHECKINTEGER_FULLWORD (0x8a8970/0x8a9180): `push eax` — NO movzx.
  assert.equal(luaEngineFontsettingsWrapperArg2FullWord(0x100), 0x100);
  assert.equal(luaEngineFontsettingsWrapperArg2FullWord(0x10000), 0x10000);
  assert.equal(luaEngineFontsettingsWrapperArg2FullWord(0xffffffff), 0xffffffff);
  assert.equal(luaEngineFontsettingsWrapperArg2FullWord(0x12345678), 0x12345678);
  // CHECKLSTRING_BYTE (0x8a8e40): `mov dl,[eax]` byte0.
  assert.equal(luaEngineFontsettingsWrapperArg2Byte0(0x1ff), 0xff);
  assert.equal(luaEngineFontsettingsWrapperArg2Byte0(0x100), 0x00);
  assert.equal(luaEngineFontsettingsWrapperArg2Byte0(0xff), 0xff);
  assert.equal(luaEngineFontsettingsWrapperArg2Byte0(0xffffffff), 0xff);
  // CHECKLSTRING_GATED (Load/GetStringWidth): second lua_type FULL-WORD.
  assert.equal(luaEngineFontsettingsWrapperChecklstringGate(0, 0xdeadbeef), 0);
  assert.equal(luaEngineFontsettingsWrapperChecklstringGate(0x100, 0x1234), 0x1234);
  assert.equal(luaEngineFontsettingsWrapperChecklstringGate(0xffffffff, 0x7), 0x7);
  assert.equal(luaEngineFontsettingsWrapperChecklstringGate(0x1ff, 0xffffffff), 0xffffffff);
  // PUSHBOOLEAN (0x8a8b10/0x8a8dd0): `test al,al; setne cl` — LOW-BYTE.
  assert.equal(luaEngineFontsettingsWrapperBoolLowByte(0), 0);
  assert.equal(luaEngineFontsettingsWrapperBoolLowByte(1), 1);
  assert.equal(luaEngineFontsettingsWrapperBoolLowByte(0x100), 0);
  assert.equal(luaEngineFontsettingsWrapperBoolLowByte(0x1ff), 1);
  assert.equal(luaEngineFontsettingsWrapperBoolLowByte(0xffffffff), 1);
});test("native/Wasm differential: ABI v51 Load-band wrappers + gates WIDE drive", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.abi() | 0, LUA_ENGINE_PURE_ABI_VERSION);
  assert.equal(native.fontsettingsWrapperCount() | 0, 15);
  for (let i = 0; i < 15; i += 1) {
    assert.equal(native.fontsettingsWrapperVa(i) >>> 0, luaEngineFontsettingsWrapperVa(i));
    assert.equal(native.fontsettingsWrapperRetVa(i) >>> 0, luaEngineFontsettingsWrapperRetVa(i));
    assert.equal(native.fontsettingsWrapperBodyBytes(i) >>> 0, luaEngineFontsettingsWrapperBodyBytes(i));
    assert.equal(native.fontsettingsWrapperInsnCount(i) | 0, luaEngineFontsettingsWrapperInsnCount(i));
    assert.equal(native.fontsettingsWrapperCheckFlags(i) | 0, luaEngineFontsettingsWrapperCheckFlags(i));
    assert.equal(native.fontsettingsWrapperReturnValue(i) | 0, luaEngineFontsettingsWrapperReturnValue(i));
    assert.equal(native.fontsettingsWrapperArg2Kind(i) | 0, luaEngineFontsettingsWrapperArg2Kind(i));
    assert.equal(native.fontsettingsWrapperArg2Index(i) | 0, luaEngineFontsettingsWrapperArg2Index(i));
    assert.equal(native.fontsettingsWrapperTailKind(i) | 0, luaEngineFontsettingsWrapperTailKind(i));
    assert.equal(native.fontsettingsWrapperRegistryKeyI(i) >>> 0, luaEngineFontsettingsWrapperRegistryKeyAt(i));
    assert.equal(native.fontsettingsWrapperFirstRetVa(i) >>> 0, luaEngineFontsettingsWrapperFirstRetVa(i));
    assert.equal(native.fontsettingsWrapperTailHelperVa(i) >>> 0, luaEngineFontsettingsWrapperTailHelperVa(i));
    assert.equal(native.fontsettingsWrapperInstallVa(i) >>> 0, luaEngineFontsettingsWrapperInstallVa(i));
    assert.equal(native.fontsettingsWrapperInstallLiteralVa(i) >>> 0, luaEngineFontsettingsWrapperInstallLiteralVa(i));
  }
  assert.equal(native.fontsettingsWrapperRegistryKeyI(15) | 0, 0);
  assert.equal(native.fontsettingsWrapperFirstRetVa(15) | 0, 0);
  assert.equal(native.fontsettingsWrapperTailHelperVa(15) | 0, 0);
  assert.equal(native.fontsettingsWrapperVa(15) | 0, 0);
  // Load trap-ret discriminator across the boundary.
  assert.equal(native.fontsettingsWrapperFirstRetVa(8) >>> 0, 0x008a8d53);
  assert.equal(native.fontsettingsWrapperRetVa(8) >>> 0, 0x008a8d75);
  assert.equal(native.fontsettingsWrapperBodyBytes(8) >>> 0, 0x95);
  // IAT pins.
  assert.equal(native.fontsettingsWrapperIatLuaChecklstring() >>> 0, 0x00b183e4);
  assert.equal(native.fontsettingsWrapperIatLuaPushboolean() >>> 0, 0x00b183ec);
  assert.equal(native.fontsettingsWrapperSecondTypeClean() >>> 0, 0x10);
  assert.equal(native.fontsettingsWrapperChecklstringClean() >>> 0, 0x0c);
  assert.equal(native.fontsettingsWrapperCharbyteStackClean() >>> 0, 0x14);
  assert.equal(native.fontsettingsWrapperPushintegerHi0() >>> 0, 0);
  assert.equal(native.fontsettingsWrapperPushintegerHi0Clean() >>> 0, 0x0c);
  // WIDE UNMASKED gate drive: byte masks / sign folds / low-word folds
  // must NOT cross the boundary pre-masked.
  const WIDE = [0x100, 0x1ff, 0x10000, 0xffffffff, 0x7fffffff, 0x80000000, 0xff, 0x00];
  for (const value of WIDE) {
    assert.equal(native.fontsettingsWrapperArg2FullWord(value) >>> 0,
      luaEngineFontsettingsWrapperArg2FullWord(value),
      "fullword " + (value >>> 0).toString(16));
    assert.equal(native.fontsettingsWrapperArg2Byte0(value) >>> 0,
      luaEngineFontsettingsWrapperArg2Byte0(value),
      "byte0 " + (value >>> 0).toString(16));
    assert.equal(native.fontsettingsWrapperBoolLowByte(value) >>> 0,
      luaEngineFontsettingsWrapperBoolLowByte(value),
      "boollow " + (value >>> 0).toString(16));
    for (const str of WIDE) {
      assert.equal(native.fontsettingsWrapperChecklstringGate(value, str) >>> 0,
        luaEngineFontsettingsWrapperChecklstringGate(value, str),
        `gate type=${(value >>> 0).toString(16)} str=${(str >>> 0).toString(16)}`);
    }
  }
  // Explicit WIDE discriminators (byte/word/full folds all fail here).
  assert.equal(native.fontsettingsWrapperArg2FullWord(0x10000) >>> 0, 0x10000);
  assert.equal(native.fontsettingsWrapperArg2Byte0(0x1ff) >>> 0, 0xff);
  assert.equal(native.fontsettingsWrapperArg2Byte0(0x100) >>> 0, 0);
  assert.equal(native.fontsettingsWrapperBoolLowByte(0x100) >>> 0, 0);
  assert.equal(native.fontsettingsWrapperBoolLowByte(0x1ff) >>> 0, 1);
  assert.equal(native.fontsettingsWrapperChecklstringGate(0x100, 0x1234) >>> 0, 0x1234);
  assert.equal(native.fontsettingsWrapperChecklstringGate(0, 0x1234) >>> 0, 0);
  // Load 62-insn true body + trap, GetMissingCharacterOverride u32-zext
  // tail helper, GetMaxCharacters u16-zext tail helper.
  assert.equal(native.fontsettingsWrapperInsnCount(8) | 0, 62);
  assert.equal(native.fontsettingsWrapperTailHelperVa(7) >>> 0, 0x0085bff0);
  assert.equal(native.fontsettingsWrapperTailHelperVa(3) >>> 0, 0x0085c010);
});

