test("ABI v51 Load-band mutants: seven translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce;
   * every one was applied to the native source, the v51 differential
   * FAILED, and the file was restored byte-identical (sha256-verified).
   * The permanent tripwire is assert.notEqual + the explicit PE truth. */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: Load registry key 0xc82989 -> 0xc82986 (fold to the alpha band).
  // PE push 0xc82989 @ 0x8a8d05 — the Load install run uses the BETA key.
  assert.equal(luaEngineFontsettingsWrapperRegistryKeyAt(8), 0x00c82989);
  assert.notEqual(luaEngineFontsettingsWrapperRegistryKeyAt(8), 0x00c82986);
  assert.equal(native.fontsettingsWrapperRegistryKeyI(8) >>> 0, 0x00c82989);
  assert.notEqual(native.fontsettingsWrapperRegistryKeyI(8) >>> 0, 0x00c82986);
  // M2: Load body_bytes folded to the TRAP ret (0x8a8d53 - 0x8a8ce0 =
  // 0x73). PE `ret` @ 0x8a8d75 is the true tail; 0x8a8d53 is only the
  // nil-path trap the jne @0x8a8d3e jumps past.
  assert.equal(native.fontsettingsWrapperBodyBytes(8) >>> 0, 0x95);
  assert.notEqual(native.fontsettingsWrapperBodyBytes(8) >>> 0, 0x73);
  assert.equal(native.fontsettingsWrapperFirstRetVa(8) >>> 0, 0x008a8d53);
  assert.notEqual(native.fontsettingsWrapperFirstRetVa(8) >>> 0,
    native.fontsettingsWrapperRetVa(8));
  // M3: checklstring gate -> LOW-BYTE test (0x100 -> 0). PE `test eax,eax`
  // @ 0x8a8d3c is FULL-WORD — 0x100 still routes to the string path.
  assert.equal(native.fontsettingsWrapperChecklstringGate(0x100, 0x1234) >>> 0, 0x1234);
  assert.notEqual(native.fontsettingsWrapperChecklstringGate(0x100, 0x1234) >>> 0, 0x00);
  assert.equal(luaEngineFontsettingsWrapperChecklstringGate(0x100, 0x1234), 0x1234);
  assert.notEqual(luaEngineFontsettingsWrapperChecklstringGate(0x100, 0x1234), 0x00);
  // M4: bool tail -> FULL-WORD test (0x100 -> 1). PE `test al,al; setne cl`
  // @ 0x8a8b5a tests the LOW BYTE only.
  assert.equal(native.fontsettingsWrapperBoolLowByte(0x100) >>> 0, 0x00);
  assert.notEqual(native.fontsettingsWrapperBoolLowByte(0x100) >>> 0, 0x01);
  assert.equal(native.fontsettingsWrapperBoolLowByte(0x1ff) >>> 0, 0x01);
  assert.equal(luaEngineFontsettingsWrapperBoolLowByte(0x100), 0x00);
  assert.notEqual(luaEngineFontsettingsWrapperBoolLowByte(0x100), 0x01);
  // M5: GetCharacterWidth byte0 -> full word (0x1ff -> 0x1ff). PE
  // `mov dl,[eax]` @ 0x8a8e95 loads byte0 of the checklstring.
  assert.equal(native.fontsettingsWrapperArg2Byte0(0x1ff) >>> 0, 0xff);
  assert.notEqual(native.fontsettingsWrapperArg2Byte0(0x1ff) >>> 0, 0x1ff);
  assert.equal(native.fontsettingsWrapperArg2Byte0(0x100) >>> 0, 0x00);
  assert.equal(luaEngineFontsettingsWrapperArg2Byte0(0x1ff), 0xff);
  assert.notEqual(luaEngineFontsettingsWrapperArg2Byte0(0x1ff), 0x1ff);
  // M6: GetMaxCharacters tail helper 0x85c010 (push-u16-zext) -> 0x85bff0
  // (u32 fold). PE `call 0x85c010` @ 0x8a8afe — the max-characters field
  // is the 16-bit setter's word (movzx edx,ax on 0x8a8a90).
  assert.equal(native.fontsettingsWrapperTailHelperVa(3) >>> 0, 0x0085c010);
  assert.notEqual(native.fontsettingsWrapperTailHelperVa(3) >>> 0, 0x0085bff0);
  assert.equal(luaEngineFontsettingsWrapperTailHelperVa(3), 0x0085c010);
  assert.notEqual(luaEngineFontsettingsWrapperTailHelperVa(3), 0x0085bff0);
  // M7: CHECKINTEGER_FULLWORD -> LOW-WORD mask (0x10000 -> 0). PE
  // `push eax` @ 0x8a89cf — no movzx on the 0x8a8970/0x8a9180 wrappers.
  assert.equal(native.fontsettingsWrapperArg2FullWord(0x10000) >>> 0, 0x10000);
  assert.notEqual(native.fontsettingsWrapperArg2FullWord(0x10000) >>> 0, 0x00);
  assert.equal(luaEngineFontsettingsWrapperArg2FullWord(0x10000), 0x10000);
  assert.notEqual(luaEngineFontsettingsWrapperArg2FullWord(0x10000), 0x00);
});

test("JS oracle: ABI v51 install-run helpers 14..28 + sites 25..41", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth from cpu-dump/0089fe80.txt + 0089fce0.txt +
   * 0089fc40.txt + 0089fbe0.txt + 0089fb40.txt + 0089fae0.txt +
   * 0089fa40.txt + 0089f9e0.txt + 0089f980.txt + 0089f8e0.txt +
   * 0089f840.txt + 0089f7a0.txt + 0089f700.txt + 0089f660.txt +
   * 0089f600.txt (lua-v54 notes). Wrapper VAs cross-checked by the
   * whole-image abs scan (sole 32-bit LE fn literals at the push-imms
   * below). */
  const PE_HELP = [
    [14, 0x0089fe80, 0x0089fed0, 44, 0x008a8970, LUA_INSTALL_SHAPE_SINGLE, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b702d8, 0x00a1a5c0], /* SetAlignment */
    [15, 0x0089fce0, 0x0089fd76, 68, 0x008a8ab0, LUA_INSTALL_SHAPE_DUAL_IMM, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b70394, 0x00a1a5e0],
    [16, 0x0089fc40, 0x0089fcd6, 74, 0x008a8b10, LUA_INSTALL_SHAPE_DUAL, LUA_INSTALL_SOURCE_REGISTER, LUA_INSTALL_SOURCE_REGISTER, 0, 0],
    [17, 0x0089fbe0, 0x0089fc30, 44, 0x008a8b80, LUA_INSTALL_SHAPE_SINGLE, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b70354, 0x00407280],
    [18, 0x0089fb40, 0x0089fbd6, 67, 0x008a8c10, LUA_INSTALL_SHAPE_DUAL_IMM, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b7030c, 0x00407270],
    [19, 0x0089fae0, 0x0089fb30, 44, 0x008a8970, LUA_INSTALL_SHAPE_SINGLE, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b70324, 0x00a1a630],
    [20, 0x0089fa40, 0x0089fad6, 67, 0x008a8c80, LUA_INSTALL_SHAPE_DUAL_IMM, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b70408, 0x0040c2e0],
    [21, 0x0089f9e0, 0x0089fa30, 44, 0x008a8ce0, LUA_INSTALL_SHAPE_SINGLE, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b703f8, 0x0085e470], /* Load */
    [22, 0x0089f980, 0x0089f9d0, 44, 0x008a8d80, LUA_INSTALL_SHAPE_SINGLE, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b70400, 0x00a1ad90],
    [23, 0x0089f8e0, 0x0089f976, 67, 0x008a8dd0, LUA_INSTALL_SHAPE_DUAL_IMM, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b703d8, 0x006b83d0],
    [24, 0x0089f840, 0x0089f8d6, 68, 0x008a8e40, LUA_INSTALL_SHAPE_DUAL_IMM, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b703e4, 0x00a1ae70],
    [25, 0x0089f7a0, 0x0089f836, 68, 0x008a8ec0, LUA_INSTALL_SHAPE_DUAL_IMM, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b703b8, 0x00a1ae80],
    [26, 0x0089f700, 0x0089f796, 74, 0x008a8f60, LUA_INSTALL_SHAPE_DUAL, LUA_INSTALL_SOURCE_REGISTER, LUA_INSTALL_SOURCE_REGISTER, 0, 0],
    [27, 0x0089f660, 0x0089f6f6, 66, 0x008a8fc0, LUA_INSTALL_SHAPE_DUAL_IMM, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b70468, 0x00a1b140], /* DrawString */
    [28, 0x0089f600, 0x0089f650, 44, 0x008a9180, LUA_INSTALL_SHAPE_SINGLE, LUA_INSTALL_SOURCE_IMMEDIATE, LUA_INSTALL_SOURCE_IMMEDIATE, 0x00b7043c, 0x00a1b3b0],
  ];
  for (const [idx, va, ret, insns, wrapper, shape, nsrc, fnsrc, nimm, fnimm] of PE_HELP) {
    assert.equal(luaEngineInstallHelperVa(idx), va, "va " + idx);
    assert.equal(luaEngineInstallHelperRetVa(idx), ret, "ret " + idx);
    assert.equal(luaEngineInstallHelperBodyBytes(idx), ret - va, "body " + idx);
    assert.equal(luaEngineInstallHelperInsnCount(idx), insns, "insns " + idx);
    assert.equal(luaEngineInstallHelperWrapperVa(idx), wrapper, "wrapper " + idx);
    assert.equal(luaEngineInstallHelperShape(idx), shape, "shape " + idx);
    assert.equal(luaEngineInstallHelperNameSource(idx), nsrc, "nsrc " + idx);
    assert.equal(luaEngineInstallHelperRealFnSource(idx), fnsrc, "fnsrc " + idx);
    assert.equal(luaEngineInstallHelperNameImmVa(idx), nimm, "nimm " + idx);
    assert.equal(luaEngineInstallHelperRealFnImmVa(idx), fnimm, "fnimm " + idx);
  }
  // shared wrapper 0x8a8970 is pushed by helpers 14 AND 19 (different
  // name/real_fn per method).
  assert.equal(luaEngineInstallHelperWrapperVa(14), 0x008a8970);
  assert.equal(luaEngineInstallHelperWrapperVa(19), 0x008a8970);
  assert.notEqual(luaEngineInstallHelperNameImmVa(14), luaEngineInstallHelperNameImmVa(19));
  // Load installer rows.
  assert.equal(luaEngineInstallHelperWrapperVa(21), 0x008a8ce0);
  assert.equal(luaEngineInstallHelperNameImmVa(21), 0x00b703f8);
  assert.equal(luaEngineInstallHelperRealFnImmVa(21), 0x0085e470);
  // sites 25..41.
  assert.equal(LUA_INSTALL_SITE_COUNT, 42);
  const SITE_25 = [
    [25, 0x00866db7, 14, 0x00b702d8, 0x00a1a5c0], /* SetAlignment */
    [33, 0x00866efc, 21, 0x00b703f8, 0x0085e470], /* Load */
    [40, 0x00866f8f, 27, 0x00b70468, 0x00a1b140], /* DrawString */
    [41, 0x00866fa4, 28, 0x00b7043c, 0x00a1b3b0], /* SetMissingCharacter */
  ];
  for (const [idx, call, helper, name, realFn] of SITE_25) {
    assert.equal(luaEngineInstallSiteCallVa(idx), call, "call " + idx);
    assert.equal(luaEngineInstallSiteHelperIndex(idx), helper, "helper " + idx);
    assert.equal(luaEngineInstallSiteNameVa(idx), name, "name " + idx);
    assert.equal(luaEngineInstallSiteRealFnVa(idx), realFn, "fn " + idx);
  }
});

