  assert.equal(native.drawstringIatLuaType() >>> 0, luaEngineDrawstringIatLuaType());
  assert.equal(native.drawstringIatLuaTouserdata() >>> 0, luaEngineDrawstringIatLuaTouserdata());
  assert.equal(native.drawstringIatLuaChecklstring() >>> 0, luaEngineDrawstringIatLuaChecklstring());
  assert.equal(native.drawstringChecklstringClean() >>> 0, luaEngineDrawstringChecklstringClean());
  assert.equal(native.drawstringVecHelperVa() >>> 0, luaEngineDrawstringVecHelperVa());
