  assert.equal(native.drawstringCallArgs() | 0, luaEngineDrawstringCallArgs());
  assert.equal(native.drawstringCallF32Count() | 0, luaEngineDrawstringCallF32Count());
  assert.equal(native.drawstringCallStructCount() | 0, luaEngineDrawstringCallStructCount());
