test("ABI v52 DrawString mutants: six translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce;
   * every one was applied to the native source, the v52 differential
   * FAILED, and the file was restored byte-identical (sha256-verified).
   * The permanent tripwire is assert.notEqual + the explicit PE truth. */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: DrawString registry key 0xc82989 -> 0xc82986 (fold to the alpha
  // band). PE push 0xc82989 @ 0x8a9003 — DrawString uses the BETA key
  // (same as the Load band 0x8a8d05), NOT the vec helper's alpha.
  assert.equal(luaEngineDrawstringRegistryKey(), 0x00c82989);
  assert.notEqual(luaEngineDrawstringRegistryKey(), 0x00c82986);
  assert.equal(native.drawstringRegistryKey() >>> 0, 0x00c82989);
  assert.notEqual(native.drawstringRegistryKey() >>> 0, 0x00c82986);
  // M2: DrawString arg1 type gate -> LOW-BYTE test (0x100 -> 0). PE
  // `test eax,eax` @ 0x8a8ff8 is FULL-WORD.
  assert.equal(native.drawstringObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.notEqual(native.drawstringObjectResolve(0x100, 0x1234) >>> 0, 0x00);
  assert.equal(luaEngineDrawstringObjectResolve(0x100, 0x1234), 0x1234);
  assert.notEqual(luaEngineDrawstringObjectResolve(0x100, 0x1234), 0x00);
  // M3: vec gate -> LOW-BYTE test (0x100 -> 0). PE `test eax,eax` @
  // 0x8baace and `test esi,esi` @ 0x8baaef are both FULL-WORD.
  assert.equal(native.drawstringVecGate(0x100, 0x1234) >>> 0, 0x1234);
  assert.notEqual(native.drawstringVecGate(0x100, 0x1234) >>> 0, 0x00);
  assert.equal(luaEngineDrawstringVecGate(0x100, 0x1234), 0x1234);
  assert.notEqual(luaEngineDrawstringVecGate(0x100, 0x1234), 0x00);
  // M4: getRef edx passthrough -> byte mask (0x100 -> 0). PE `mov
  // esi,edx; mov edx,esi` carries the idx REGISTER FULL-WORD.
  assert.equal(native.drawstringGetrefEdxIndex(0x100) >>> 0, 0x100);
  assert.notEqual(native.drawstringGetrefEdxIndex(0x100) >>> 0, 0x00);
  assert.equal(native.drawstringGetrefEdxIndex(0x10000) >>> 0, 0x10000);
  assert.equal(luaEngineDrawstringGetrefEdxIndex(0x100), 0x100);
  assert.notEqual(luaEngineDrawstringGetrefEdxIndex(0x100), 0x00);
  // M5: vec checknumber OUT offsets reversed (CN6 -> OUT+0x00). PE
  // `fstp dword [eax]` tail stores the LAST call (L,3) at OUT+0x00 and
  // (L,6) at OUT+0x0c.
  assert.equal(native.drawstringVecOutF32OffAt(6) >>> 0, 0x0c);
  assert.notEqual(native.drawstringVecOutF32OffAt(6) >>> 0, 0x00);
  assert.equal(native.drawstringVecOutF32OffAt(3) >>> 0, 0x00);
  assert.equal(luaEngineDrawstringVecOutF32OffAt(6), 0x0c);
  assert.notEqual(luaEngineDrawstringVecOutF32OffAt(6), 0x00);
  // M6: DrawString vec slot frame offset 0xec -> 0xe0 (fold). PE
  // `lea ecx,[ebp-0xec]` @ 0x8a902f — the OUT struct starts at -0xec.
  assert.equal(native.drawstringVecOutFrameOff() >>> 0, 0xec);
  assert.notEqual(native.drawstringVecOutFrameOff() >>> 0, 0xe0);
  assert.equal(luaEngineDrawstringVecOutFrameOff(), 0xec);
  assert.notEqual(luaEngineDrawstringVecOutFrameOff(), 0xe0);
});

test("JS oracle: ABI v53 pusher leaf stubs 0x85c050/0x85bff0/0x85c010 + 0x85c590 body bounds", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed branch-by-branch from the fresh
   * cpu-dump/0085c050.txt (13 insns, ret 0x85c072) + 0085bff0.txt (11
   * insns, ret 0x85c006) + 0085c010.txt (13 insns, ret 0x85c029) +
   * 0085c590.txt (re-dump) + 0085c70f.txt (aligned tail) — NOT derived
   * from the model or the C++. Notes: lua-v53-pushers.
   *
   * 0x85c050 PUSHNUMBER_F32 (ecx=L, xmm1 = f32 BITS via SSE reg):
   *   push ebp; mov ebp,esp; and esp,0xffffffc0; xorps xmm0,xmm0;
   *   sub esp,8; cvtss2sd xmm0,xmm1 (EXACT f32->f64, RN); movsd
   *   [esp],xmm0 (LE: lo@[esp], hi@[esp+4]); push ecx; call
   *   [0xb183f0] lua_pushnumber; add esp,0xc; mov esp,ebp; pop ebp;
   *   ret @0x85c072.
   * 0x85bff0 PUSHINT_U32 (ecx=L, edx=value): push ebp; mov ebp,esp;
   *   and esp,0xfffffff8; push 0 (hi); push edx (lo FULL word); push
   *   ecx; call [0xb183f8] lua_pushinteger; add esp,0xc; ret @0x85c006.
   * 0x85c010 PUSHINT_U16: ...; and esp,0xfffffff8; movzx eax,dx; cdq;
   *   push edx (hi=0 always); push eax (lo=u16); push ecx; call
   *   [0xb183f8]; add esp,0xc; ret @0x85c029.
   * 0x85c590: census "first_ret 0x85c700" is the IDENTITY-SUCCESS ret
   *   (lua_touserdata tail); TRUE body ends ret @0x85c7d0 (argerror
   *   tail, xor eax,eax @0x85c7c8). Decision islands landed v11/v12;
   *   BODY BOUNDS are this unit's laws. */
  // ---- pusher band records (v55: row 3 = PUSHINT_I32_SEXT 0x85bfd0) ----
  assert.equal(LUA_PUSHER_COUNT, 4);
  assert.deepEqual(LUA_PUSHER_VAS, [0x0085c050, 0x0085bff0, 0x0085c010, 0x0085bfd0]);
  assert.deepEqual(LUA_PUSHER_RET_VAS, [0x0085c072, 0x0085c006, 0x0085c029, 0x0085bfe8]);
  assert.deepEqual(LUA_PUSHER_INSN_COUNTS, [13, 11, 13, 13]);
  assert.deepEqual(LUA_PUSHER_STACK_ALIGN_MASKS,
    [0xffffffc0, 0xfffffff8, 0xfffffff8, 0xfffffff8]);
  assert.deepEqual(LUA_PUSHER_F64_SLOT_BYTES, [8, 0, 0, 0]);
  assert.deepEqual(LUA_PUSHER_IAT_VAS, [0x00b183f0, 0x00b183f8, 0x00b183f8, 0x00b183f8]);
  assert.deepEqual(LUA_PUSHER_CALL_CLEANUPS, [0x0c, 0x0c, 0x0c, 0x0c]);
  assert.deepEqual(LUA_PUSHER_KINDS,
    [LUA_PUSHER_KIND_PUSHNUMBER_F32, LUA_PUSHER_KIND_PUSHINT_U32,
     LUA_PUSHER_KIND_PUSHINT_U16, LUA_PUSHER_KIND_PUSHINT_I32_SEXT]);
  assert.equal(luaEnginePusherCount(), 4);
  assert.equal(luaEnginePusherVa(0), 0x0085c050);
  assert.equal(luaEnginePusherVa(1), 0x0085bff0);
  assert.equal(luaEnginePusherVa(2), 0x0085c010);
  assert.equal(luaEnginePusherVa(3), 0x0085bfd0);
  assert.equal(luaEnginePusherRetVa(0), 0x0085c072);
  assert.equal(luaEnginePusherRetVa(1), 0x0085c006);
  assert.equal(luaEnginePusherRetVa(2), 0x0085c029);
  assert.equal(luaEnginePusherRetVa(3), 0x0085bfe8);
  assert.equal(luaEnginePusherBodyBytes(0), 0x22);
  assert.equal(luaEnginePusherBodyBytes(1), 0x16);
  assert.equal(luaEnginePusherBodyBytes(2), 0x19);
  assert.equal(luaEnginePusherBodyBytes(3), 0x18);
  assert.equal(luaEnginePusherInsnCount(0), 13);
  assert.equal(luaEnginePusherInsnCount(1), 11);
  assert.equal(luaEnginePusherInsnCount(2), 13);
  assert.equal(luaEnginePusherInsnCount(3), 13);
  assert.equal(luaEnginePusherStackAlignMask(0), 0xffffffc0);
  assert.equal(luaEnginePusherStackAlignMask(1), 0xfffffff8);
  assert.equal(luaEnginePusherStackAlignMask(2), 0xfffffff8);
  assert.equal(luaEnginePusherStackAlignMask(3), 0xfffffff8);
  assert.equal(luaEnginePusherF64SlotBytes(0), 8);
  assert.equal(luaEnginePusherF64SlotBytes(1), 0);
  assert.equal(luaEnginePusherF64SlotBytes(2), 0);
  assert.equal(luaEnginePusherF64SlotBytes(3), 0);
  assert.equal(luaEnginePusherIatVa(0), 0x00b183f0);
  assert.equal(luaEnginePusherIatVa(1), 0x00b183f8);
  assert.equal(luaEnginePusherIatVa(2), 0x00b183f8);
  assert.equal(luaEnginePusherIatVa(3), 0x00b183f8);
  assert.equal(luaEnginePusherCallCleanup(0), 0x0c);
  assert.equal(luaEnginePusherCallCleanup(1), 0x0c);
  assert.equal(luaEnginePusherCallCleanup(2), 0x0c);
  assert.equal(luaEnginePusherCallCleanup(3), 0x0c);
  assert.equal(luaEnginePusherKind(0), LUA_PUSHER_KIND_PUSHNUMBER_F32);
  assert.equal(luaEnginePusherKind(1), LUA_PUSHER_KIND_PUSHINT_U32);
  assert.equal(luaEnginePusherKind(2), LUA_PUSHER_KIND_PUSHINT_U16);
  assert.equal(luaEnginePusherKind(3), LUA_PUSHER_KIND_PUSHINT_I32_SEXT);
  // out-of-range guards (row 3 is now a REAL row; OOR is index 4).
  assert.equal(luaEnginePusherVa(-1), 0);
  assert.equal(luaEnginePusherVa(4), 0);
  assert.equal(luaEnginePusherInsnCount(4), -1);

  // ---- PUSHNUMBER_F32 widen law (cvtss2sd bit-exact) ----
  // 1.0f  (0x3f800000) -> 0x3ff0000000000000
  assert.equal(luaEnginePusherPushnumberF32WidenHi(0x3f800000 >>> 0),
    0x3ff00000);
  assert.equal(luaEnginePusherPushnumberF32WidenLo(0x3f800000 >>> 0),
    0x00000000);
  // -1.5f (0xbfc00000) -> 0xbff8000000000000
  assert.equal(luaEnginePusherPushnumberF32WidenHi(0xbfc00000 >>> 0),
    0xbff80000);
  assert.equal(luaEnginePusherPushnumberF32WidenLo(0xbfc00000 >>> 0),
    0x00000000);
  // 0.33333334f (0x3eaaaaab) -> 0x3fd5555560000000 (exact widening)
  assert.equal(luaEnginePusherPushnumberF32WidenHi(0x3eaaaaab >>> 0),
    0x3fd55555);
  assert.equal(luaEnginePusherPushnumberF32WidenLo(0x3eaaaaab >>> 0),
    0x60000000);
  // +inf (0x7f800000) -> 0x7ff0000000000000; -inf -> 0xfff0...
  assert.equal(luaEnginePusherPushnumberF32WidenHi(0x7f800000 >>> 0),
    0x7ff00000);
  assert.equal(luaEnginePusherPushnumberF32WidenLo(0x7f800000 >>> 0),
    0x00000000);
  assert.equal(luaEnginePusherPushnumberF32WidenHi(0xff800000 >>> 0),
    0xfff00000);
  // qNaN 0x7fc00000 -> 0x7ff8000000000000 (widening preserves the sign
  // + exponent + quiet payload — cvtss2sd semantics).
  assert.equal(luaEnginePusherPushnumberF32WidenHi(0x7fc00000 >>> 0),
    0x7ff80000);
  assert.equal(luaEnginePusherPushnumberF32WidenLo(0x7fc00000 >>> 0),
    0x00000000);
  // denormal 0x1 -> 2^-149 exact
  assert.equal(luaEnginePusherPushnumberF32WidenHi(0x00000001 >>> 0),
    0x36a00000);
  // -0f (0x80000000) keeps the sign bit.
  assert.equal(luaEnginePusherPushnumberF32WidenHi(0x80000000 >>> 0),
    0x80000000);

  // ---- PUSHINT_U32 width law (lo full word, hi literal 0) ----
  assert.equal(luaEnginePusherPushintU32Lo(0x00000100), 0x00000100);
  assert.equal(luaEnginePusherPushintU32Lo(0x00010000), 0x00010000);
  assert.equal(luaEnginePusherPushintU32Lo(0xffffffff), 0xffffffff);
  assert.equal(luaEnginePusherPushintU32Lo(0x00000007), 0x00000007);
  assert.equal(luaEnginePusherPushintU32Hi(0xffffffff), 0);
  assert.equal(luaEnginePusherPushintU32Hi(0x80000000), 0);
  assert.equal(luaEnginePusherPushintU32Hi(0x00000000), 0);

  // ---- PUSHINT_U16 width law (lo u16 low word, hi 0 via movzx+cdq) ----
  assert.equal(luaEnginePusherPushintU16Lo(0x00000100), 0x00000100);
  assert.equal(luaEnginePusherPushintU16Lo(0x00010000), 0x00000000);
  assert.equal(luaEnginePusherPushintU16Lo(0xffffffff), 0x0000ffff);
  assert.equal(luaEnginePusherPushintU16Lo(0x00008000), 0x00008000);
  assert.equal(luaEnginePusherPushintU16Hi(0x00008000), 0);
  assert.equal(luaEnginePusherPushintU16Hi(0xffffffff), 0);
  assert.equal(luaEnginePusherPushintU16Hi(0x00000000), 0);

  // ---- 0x85c590 body bounds (dual ret) ----
  assert.equal(LUA_CHECK_GET_BODY_VA, 0x0085c590);
  assert.equal(LUA_CHECK_GET_SUCCESS_RET_VA, 0x0085c700);
  assert.equal(LUA_CHECK_GET_TRUE_RET_VA, 0x0085c7d0);
  assert.equal(LUA_CHECK_GET_BODY_INSNS, 215);
  assert.equal(LUA_CHECK_GET_SUCCESS_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(LUA_CHECK_GET_SUCCESS_CLEANUP, 0x08);
  assert.equal(luaEngineCheckGetBodyVa(), 0x0085c590);
  assert.equal(luaEngineCheckGetSuccessRetVa(), 0x0085c700);
  assert.equal(luaEngineCheckGetTrueRetVa(), 0x0085c7d0);
  assert.equal(luaEngineCheckGetBodyBytes(), 0x240);
  assert.equal(luaEngineCheckGetInsnCount(), 215);
  assert.equal(luaEngineCheckGetDualRet(), 1);
  assert.notEqual(luaEngineCheckGetSuccessRetVa(), luaEngineCheckGetTrueRetVa());
  assert.equal(luaEngineCheckGetSuccessIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineCheckGetSuccessCleanup(), 8);
});

test("native/Wasm differential: ABI v53 pusher band WIDE drive", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.abi() | 0, LUA_ENGINE_PURE_ABI_VERSION);
  // Band records cross-check model vs wasm.
  assert.equal(native.pusherCount() | 0, luaEnginePusherCount());
  for (let i = 0; i < 4; i++) {
    assert.equal(native.pusherVa(i) >>> 0, luaEnginePusherVa(i));
    assert.equal(native.pusherRetVa(i) >>> 0, luaEnginePusherRetVa(i));
    assert.equal(native.pusherBodyBytes(i) >>> 0, luaEnginePusherBodyBytes(i));
    assert.equal(native.pusherInsnCount(i) | 0, luaEnginePusherInsnCount(i));
    assert.equal(native.pusherStackAlignMask(i) >>> 0,
      luaEnginePusherStackAlignMask(i));
    assert.equal(native.pusherF64SlotBytes(i) | 0,
      luaEnginePusherF64SlotBytes(i));
    assert.equal(native.pusherIatVa(i) >>> 0, luaEnginePusherIatVa(i));
    assert.equal(native.pusherCallCleanup(i) | 0,
      luaEnginePusherCallCleanup(i));
    assert.equal(native.pusherKind(i) | 0, luaEnginePusherKind(i));
  }
  // Widen law differential — WIDE bit patterns, both sides bit-equal.
  const bits = [0x00000000, 0x80000000, 0x00000001, 0x3f800000, 0xbfc00000,
                0x3eaaaaab, 0x7f800000, 0xff800000, 0x7fc00000, 0x7f7fffff];
  for (const b of bits) {
    assert.equal(native.pusherWidenHi(b) >>> 0, luaEnginePusherPushnumberF32WidenHi(b));
    assert.equal(native.pusherWidenLo(b) >>> 0, luaEnginePusherPushnumberF32WidenLo(b));
  }
  // Pushint width laws — WIDE UNMASKED drive (0x100/0x10000/0xffffffff).
  const ints = [0x00000000, 0x00000001, 0x000000ff, 0x00000100, 0x00001fff,
                0x00010000, 0x00008000, 0xffffffff, 0x80000000, 0x7fffffff];
  for (const v of ints) {
    assert.equal(native.pusherU32Lo(v) >>> 0, luaEnginePusherPushintU32Lo(v));
    assert.equal(native.pusherU32Hi(v) >>> 0, luaEnginePusherPushintU32Hi(v));
    assert.equal(native.pusherU16Lo(v) >>> 0, luaEnginePusherPushintU16Lo(v));
    assert.equal(native.pusherU16Hi(v) >>> 0, luaEnginePusherPushintU16Hi(v));
    // v55 PUSHINT_I32_SEXT — WIDE UNMASKED drive.
    assert.equal(native.pusherSextLo(v) >>> 0, luaEnginePusherPushintI32SextLo(v));
    assert.equal(native.pusherSextHi(v) >>> 0, luaEnginePusherPushintI32SextHi(v));
  }
  // 0x85c590 body bounds differential.
  assert.equal(native.checkGetBodyVa() >>> 0, luaEngineCheckGetBodyVa());
  assert.equal(native.checkGetSuccessRetVa() >>> 0,
    luaEngineCheckGetSuccessRetVa());
  assert.equal(native.checkGetTrueRetVa() >>> 0, luaEngineCheckGetTrueRetVa());
  assert.equal(native.checkGetBodyBytes() >>> 0, luaEngineCheckGetBodyBytes());
  assert.equal(native.checkGetInsnCount() | 0, luaEngineCheckGetInsnCount());
  assert.equal(native.checkGetDualRet() | 0, luaEngineCheckGetDualRet());
  assert.equal(native.checkGetSuccessIatTouserdata() >>> 0,
    luaEngineCheckGetSuccessIatLuaTouserdata());
  assert.equal(native.checkGetSuccessCleanup() | 0,
    luaEngineCheckGetSuccessCleanup());
});

