test("ABI v53/v55 pusher/check-get mutants: nine translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce;
   * every one was applied to the native source, the v53 differential
   * FAILED, and the file was restored byte-identical (sha256-verified).
   * The permanent tripwire is assert.notEqual + the explicit PE truth. */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: PUSHINT_U16 lo -> FULL 32-bit word (fold u16 onto u32; PE
  // `movzx eax,dx` @ 0x85c016 truncates to the LOW WORD: 0x10000 -> 0).
  assert.equal(native.pusherU16Lo(0x00010000) >>> 0, 0x00000000);
  assert.notEqual(native.pusherU16Lo(0x00010000) >>> 0, 0x00010000);
  assert.equal(luaEnginePusherPushintU16Lo(0x00010000), 0x00000000);
  assert.notEqual(luaEnginePusherPushintU16Lo(0x00010000), 0x00010000);
  // M2: PUSHINT_U16 hi -> sign-extend of the 16-bit word (a movsx
  // fold; PE movzx + cdq keeps hi 0: dx=0x8000 -> hi MUST be 0).
  assert.equal(native.pusherU16Hi(0x00008000) >>> 0, 0x00000000);
  assert.notEqual(native.pusherU16Hi(0x00008000) >>> 0, 0xffffffff);
  assert.equal(native.pusherU16Hi(0xffffffff) >>> 0, 0x00000000);
  assert.notEqual(native.pusherU16Hi(0xffffffff) >>> 0, 0xffffffff);
  assert.equal(luaEnginePusherPushintU16Hi(0x00008000), 0x00000000);
  assert.notEqual(luaEnginePusherPushintU16Hi(0x00008000), 0xffffffff);
  // M3: PUSHINT_U32 lo -> u16 fold (PE `push edx` @ 0x85bff8 pushes the
  // FULL word: 0xffffffff must survive).
  assert.equal(native.pusherU32Lo(0xffffffff) >>> 0, 0xffffffff);
  assert.notEqual(native.pusherU32Lo(0xffffffff) >>> 0, 0x0000ffff);
  assert.equal(native.pusherU32Lo(0x00010000) >>> 0, 0x00010000);
  assert.notEqual(native.pusherU32Lo(0x00010000) >>> 0, 0x00000000);
  assert.equal(luaEnginePusherPushintU32Lo(0xffffffff), 0xffffffff);
  assert.notEqual(luaEnginePusherPushintU32Lo(0xffffffff), 0x0000ffff);
  // M4: PUSHNUMBER_F32 widen -> bit-reinterpret fold (skips cvtss2sd;
  // PE `cvtss2sd xmm0,xmm1` @0x85c05c widens exactly — 0x3eaaaaab ->
  // 0x3fd5555560000000, a reinterpret of the f32 bits would give a
  // ~1e-315 denormal).
  assert.equal(native.pusherWidenHi(0x3eaaaaab >>> 0) >>> 0, 0x3fd55555);
  assert.notEqual(native.pusherWidenHi(0x3eaaaaab >>> 0) >>> 0, 0x3fe00000);
  assert.equal(native.pusherWidenLo(0x3eaaaaab >>> 0) >>> 0, 0x60000000);
  assert.notEqual(native.pusherWidenLo(0x3eaaaaab >>> 0) >>> 0, 0x55556000);
  assert.equal(luaEnginePusherPushnumberF32WidenHi(0x3eaaaaab >>> 0), 0x3fd55555);
  assert.notEqual(luaEnginePusherPushnumberF32WidenHi(0x3eaaaaab >>> 0), 0x3fe00000);
  // M5: 0x85c590 ret folded to the census trap 0x85c700 (body 0x170
  // instead of 0x240; PE true body ends ret @0x85c7d0, `je 0x85c701`
  // @0x85c6d7 jumps PAST the mid-body success ret).
  assert.equal(native.checkGetTrueRetVa() >>> 0, 0x0085c7d0);
  assert.notEqual(native.checkGetTrueRetVa() >>> 0, 0x0085c700);
  assert.equal(native.checkGetBodyBytes() >>> 0, 0x240);
  assert.notEqual(native.checkGetBodyBytes() >>> 0, 0x170);
  assert.equal(native.checkGetDualRet() | 0, 1);
  assert.equal(native.checkGetInsnCount() | 0, 215);
  assert.equal(luaEngineCheckGetTrueRetVa(), 0x0085c7d0);
  assert.notEqual(luaEngineCheckGetTrueRetVa(), 0x0085c700);
  assert.equal(luaEngineCheckGetBodyBytes(), 0x240);
  assert.notEqual(luaEngineCheckGetBodyBytes(), 0x170);
  // M6 (v55): PUSHINT_I32_SEXT hi -> literal 0 (the PUSHINT_U32 `push 0`
  // fold; PE `cdq` @0x85bfd8 replicates the sign: 0x80000000 -> 0xffffffff).
  assert.equal(native.pusherSextHi(0x80000000) >>> 0, 0xffffffff);
  assert.notEqual(native.pusherSextHi(0x80000000) >>> 0, 0x00000000);
  assert.equal(native.pusherSextHi(0xffffffff) >>> 0, 0xffffffff);
  assert.equal(luaEnginePusherPushintI32SextHi(0x80000000), 0xffffffff);
  assert.notEqual(luaEnginePusherPushintI32SextHi(0x80000000), 0x00000000);
  // M7 (v55): PUSHINT_I32_SEXT lo -> u16 LOW WORD fold (PE `mov eax,edx`
  // @0x85bfd6 keeps the FULL word: 0xffffffff must survive).
  assert.equal(native.pusherSextLo(0xffffffff) >>> 0, 0xffffffff);
  assert.notEqual(native.pusherSextLo(0xffffffff) >>> 0, 0x0000ffff);
  assert.equal(native.pusherSextLo(0x00010000) >>> 0, 0x00010000);
  assert.notEqual(native.pusherSextLo(0x00010000) >>> 0, 0x00000000);
  assert.equal(luaEnginePusherPushintI32SextLo(0xffffffff), 0xffffffff);
  assert.notEqual(luaEnginePusherPushintI32SextLo(0xffffffff), 0x0000ffff);
  // M8 (v55): sext hi driven by bit 15 instead of bit 31 (a movsx/sign16
  // fold; PE cdq reads the FULL dword sign: 0xffff8000 -> 0xffffffff via
  // bit31, 0x00008000 -> 0).
  assert.equal(native.pusherSextHi(0xffff8000) >>> 0, 0xffffffff);
  assert.notEqual(native.pusherSextHi(0xffff8000) >>> 0, 0x00000000);
  assert.equal(native.pusherSextHi(0x00008000) >>> 0, 0x00000000);
  assert.notEqual(native.pusherSextHi(0x00008000) >>> 0, 0xffffffff);
  assert.equal(luaEnginePusherPushintI32SextHi(0x00008000), 0);
  assert.notEqual(luaEnginePusherPushintI32SextHi(0x00008000), 0xffffffff);
  // M9 (v55): row-3 body-bytes fold to the 0x16/0x08 shapes (PE ret
  // @0x85bfe8 - VA 0x85bfd0 = 0x18; a census fold is WRONG).
  assert.equal(native.pusherBodyBytes(3) >>> 0, 0x18);
  assert.notEqual(native.pusherBodyBytes(3) >>> 0, 0x16);
  assert.notEqual(native.pusherBodyBytes(3) >>> 0, 0x08);
  assert.equal(native.pusherInsnCount(3) | 0, 13);
  assert.notEqual(native.pusherInsnCount(3) | 0, 11);
  assert.equal(luaEnginePusherBodyBytes(3), 0x18);
  assert.notEqual(luaEnginePusherBodyBytes(3), 0x16);
});

/* ===========================================================================
 * wave-16 · ABI v25h — getArgObject BODY 0x008baa50
 * (ecx=L, edx=idx -> obj; 86 E8 callers).
 *
 * PE-truth reference transcribed branch-by-branch from
 * cpu-dump/008baa50.txt + 008baa7b.txt (lua-v25h-8baa50 notes):
 *   ecx=L; edx=idx; lua_type(L,idx) @0xb18400; FULL-WORD test @0x8baa61;
 *   nil -> luaL_error(0xb7539c) @0xb18390, ret 0 @0x8baa7a; else
 *   push 1; push 0xc82980; edx=idx (register, unmasked); call 0x85c590;
 *   obj=[eax+4]; FULL-WORD test @0x8baa91; 0 -> luaL_error again;
 *   ret obj (or 0) @0x8baaa8. 36 insns, body 0x58, dual rets.
 * ===========================================================================
 */

test("JS oracle: ABI v25h getArgObject body bounds + gates + resolve", () => {
  assert.equal(LUA_GET_ARG_OBJECT_BODY_VA, 0x008baa50);
  assert.equal(LUA_GET_ARG_OBJECT_NIL_RET_VA, 0x008baa7a);
  assert.equal(LUA_GET_ARG_OBJECT_MAIN_RET_VA, 0x008baaa8);
  assert.equal(LUA_GET_ARG_OBJECT_BODY_INSNS, 36);
  assert.equal(luaEngineGetArgObjectBodyVa(), 0x008baa50);
  assert.equal(luaEngineGetArgObjectNilRetVa(), 0x008baa7a);
  assert.equal(luaEngineGetArgObjectMainRetVa(), 0x008baaa8);
  // body bytes = main ret - body VA (ret excluded, family convention).
  assert.equal(luaEngineGetArgObjectBodyBytes(), 0x8baaa8 - 0x8baa50);
  assert.equal(luaEngineGetArgObjectBodyBytes(), 0x58);
  assert.equal(luaEngineGetArgObjectInsnCount(), 36);
  assert.equal(luaEngineGetArgObjectDualRet(), 1);
  // idx register passthrough: FULL 32-bit (mov esi,edx / mov edx,esi).
  assert.equal(luaEngineGetArgObjectIdxPassthrough(0), 0);
  assert.equal(luaEngineGetArgObjectIdxPassthrough(1), 1);
  assert.equal(luaEngineGetArgObjectIdxPassthrough(0x100), 0x100);
  assert.equal(luaEngineGetArgObjectIdxPassthrough(0x1ff), 0x1ff);
  assert.equal(luaEngineGetArgObjectIdxPassthrough(0xffffffff), 0xffffffff);
  // PE `test eax,eax` FULL-WORD — only exact 0 takes the error path.
  assert.equal(luaEngineGetArgObjectTypeGateTaken(0), 1);
  assert.equal(luaEngineGetArgObjectTypeGateTaken(0x100), 0);
  assert.equal(luaEngineGetArgObjectTypeGateTaken(0x1ff), 0);
  assert.equal(luaEngineGetArgObjectTypeGateTaken(0xffffffff), 0);
  assert.equal(luaEngineGetArgObjectObjGateTaken(0), 1);
  assert.equal(luaEngineGetArgObjectObjGateTaken(0x100), 0);
  assert.equal(luaEngineGetArgObjectObjGateTaken(0x1ff), 0);
  assert.equal(luaEngineGetArgObjectObjGateTaken(0xffffffff), 0);
  // resolve: type==0 -> 0; obj==0 -> 0; else obj.
  assert.equal(luaEngineGetArgObjectResolve(0, 0x1234), 0);
  assert.equal(luaEngineGetArgObjectResolve(0x100, 0), 0);
  assert.equal(luaEngineGetArgObjectResolve(0x100, 0x1234), 0x1234);
  assert.equal(luaEngineGetArgObjectResolve(0xffffffff, 0xffffffff),
    0xffffffff);
});

