  assert.equal(native.getArgObjectIatLuaLError() >>> 0, luaEngineGetArgObjectIatLuaLError());
  assert.equal(native.getArgObjectTypeCallCleanup() | 0, luaEngineGetArgObjectTypeCallCleanup());
  assert.equal(native.getArgObjectLaneCount() | 0, luaEngineGetArgObjectLaneCount());
