test("ABI v25h getArgObject mutants: five translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce;
   * every one was applied to the native source, the v25h differential
   * FAILED, and the file was restored byte-identical (sha256-verified,
   * see section-notes/lua-v25h-8baa50/NOTES.md RESULTS). The permanent
   * tripwire is assert.notEqual + the explicit PE truth. */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: registry key 0xc82980 -> 0xc82986 (fold to the alpha band key;
  // PE `push 0xc82980` @0x8baa7d).
  assert.equal(native.getArgObjectRegistryKey() >>> 0, 0x00c82980);
  assert.notEqual(native.getArgObjectRegistryKey() >>> 0, 0x00c82986);
  assert.equal(luaEngineGetArgObjectRegistryKey(), 0x00c82980);
  // M2: idx passthrough -> low-byte mask (edx reg round-trips FULL
  // 32-bit: mov esi,edx @0x8baa52; mov edx,esi @0x8baa82).
  assert.equal(native.getArgObjectIdxPassthrough(0x00000100) >>> 0, 0x00000100);
  assert.notEqual(native.getArgObjectIdxPassthrough(0x00000100) >>> 0, 0x00000000);
  assert.equal(native.getArgObjectIdxPassthrough(0xffffffff) >>> 0, 0xffffffff);
  assert.notEqual(native.getArgObjectIdxPassthrough(0xffffffff) >>> 0, 0x000000ff);
  assert.equal(luaEngineGetArgObjectIdxPassthrough(0x00000100), 0x00000100);
  // M3: type/obj gates -> low-byte test (PE `test eax,eax` @0x8baa61 /
  // `test esi,esi` @0x8baa91 are FULL-WORD; 0x100 must NOT trip).
  assert.equal(native.getArgObjectTypeGateTaken(0x00000100) | 0, 0);
  assert.notEqual(native.getArgObjectTypeGateTaken(0x00000100) | 0, 1);
  assert.equal(native.getArgObjectObjGateTaken(0x00000100) | 0, 0);
  assert.notEqual(native.getArgObjectObjGateTaken(0x00000100) | 0, 1);
  assert.equal(native.getArgObjectTypeGateTaken(0x00000000) | 0, 1);
  assert.equal(native.getArgObjectObjGateTaken(0x00000000) | 0, 1);
  assert.equal(luaEngineGetArgObjectTypeGateTaken(0x00000100), 0);
  // M4: dual ret folded to a single ret (PE rets @0x8baa7a AND @0x8baaa8;
  // body 0x58 = main_ret 0x8baaa8 - body 0x8baa50; folding to the nil
  // ret would give 0x2a).
  assert.equal(native.getArgObjectDualRet() | 0, 1);
  assert.notEqual(native.getArgObjectBodyBytes() >>> 0, 0x2a);
  assert.equal(native.getArgObjectBodyBytes() >>> 0, 0x58);
  assert.equal(native.getArgObjectMainRetVa() >>> 0, 0x008baaa8);
  assert.notEqual(native.getArgObjectMainRetVa() >>> 0, 0x008baa7a);
  assert.equal(native.getArgObjectNilRetVa() >>> 0, 0x008baa7a);
  assert.notEqual(native.getArgObjectNilRetVa() >>> 0, 0x008baaa8);
  assert.equal(luaEngineGetArgObjectBodyBytes(), 0x58);
  // M5: caller count 86 -> census trap (whole-image E8 scan found 86
  // sites; folding to a stale 80 drops 6 real sites).
  assert.equal(native.getArgObjectCallerCount() | 0, 86);
  assert.notEqual(native.getArgObjectCallerCount() | 0, 80);
  assert.equal(native.getArgObjectCallerVaAt(0) >>> 0, 0x00897990);
  assert.equal(native.getArgObjectCallerVaAt(85) >>> 0, 0x008baca2);
  assert.equal(luaEngineGetArgObjectCallerCount(), 86);
});

test("JS oracle: v25g PUSH_I64_PAIR 0x85c030 hi/lo pair laws", () => {
  /* Independent PE-truth, transcribed branch-by-branch from the fresh
   * cpu-dump/0085c030.txt + the caller dumps 0089b690.txt / 008ae860.txt
   * — NOT derived from the model or the C++. Notes: lua-v25g-85c030.
   *
   * 0x85c030: push ebp; mov ebp,esp; and esp,0xfffffff8; push [ebp+0xc]
   * (HI); push [ebp+8] (LO); push ecx (L); call [0xb183f8]
   * lua_pushinteger; add esp,0xc; mov esp,ebp; pop ebp; ret @0x85c049.
   * The 8-byte arg reaches lua_pushinteger as lo@[esp+4], hi@[esp+8]
   * (little-endian int64). Marshal is IDENTITY on both lanes — no mask,
   * no sign-extension; the int64 sign lives in hi bit 31 (lo bit 31 is
   * irrelevant). 5 true E8 callers (4 closure-band rows + out-of-band
   * clone 0x8ae89e); the v21/v53 census pins the 4 band rows. */
  // ---- bounds ----
  assert.equal(LUA_PROPERTY_CLOSURE_PUSH_I64_PAIR_RET_VA, 0x0085c049);
  assert.equal(LUA_PROPERTY_CLOSURE_PUSH_I64_PAIR_BODY_BYTES, 0x19);
  assert.equal(LUA_PROPERTY_CLOSURE_PUSH_I64_PAIR_INSNS, 11);
  assert.equal(LUA_PROPERTY_CLOSURE_PUSH_I64_PAIR_STACK_ALIGN_MASK, 0xfffffff8);
  assert.equal(LUA_PROPERTY_CLOSURE_PUSH_I64_PAIR_IAT_VA, 0x00b183f8);
  assert.equal(LUA_PROPERTY_CLOSURE_PUSH_I64_PAIR_CALL_CLEANUP, 0x0c);
  assert.equal(LUA_PROPERTY_CLOSURE_PUSH_I64_PAIR_SIGN_MASK, 0x80000000);
  assert.equal(LUA_PROPERTY_CLOSURE_PUSH_I64_PAIR_E8_CALLERS, 5);
  assert.equal(luaEnginePusherPushI64PairRetVa(), 0x0085c049);
  assert.equal(luaEnginePusherPushI64PairBodyBytes(), 0x19);
  assert.equal(luaEnginePusherPushI64PairInsnCount(), 11);
  assert.equal(luaEnginePusherPushI64PairStackAlignMask(), 0xfffffff8);
  assert.equal(luaEnginePusherPushI64PairIatVa(), 0x00b183f8);
  assert.equal(luaEnginePusherPushI64PairCallCleanup(), 0x0c);
  assert.equal(luaEnginePusherPushI64PairE8Callers(), 5);
  // ---- lane width laws: lo and hi are FULL 32-bit lanes ----
  assert.equal(luaEnginePusherPushI64PairLo(0xffffffff, 0), 0xffffffff);
  assert.equal(luaEnginePusherPushI64PairLo(0x00010000, 0), 0x00010000);
  assert.equal(luaEnginePusherPushI64PairLo(0x000001ff, 0), 0x000001ff);
  assert.equal(luaEnginePusherPushI64PairLo(0x12345678, 0x9abcdef0), 0x12345678);
  assert.equal(luaEnginePusherPushI64PairHi(0, 0xffffffff), 0xffffffff);
  assert.equal(luaEnginePusherPushI64PairHi(0, 0x80000000), 0x80000000);
  assert.equal(luaEnginePusherPushI64PairHi(0, 0x00010000), 0x00010000);
  assert.equal(luaEnginePusherPushI64PairHi(0x12345678, 0x9abcdef0), 0x9abcdef0);
  // ---- sign law: bit 63 (= hi bit 31), lo bit 31 is irrelevant ----
  assert.equal(luaEnginePusherPushI64PairSign(0, 0x80000000), 1);
  assert.equal(luaEnginePusherPushI64PairSign(0x80000000, 0), 0);
  assert.equal(luaEnginePusherPushI64PairSign(0xffffffff, 0xffffffff), 1);
  assert.equal(luaEnginePusherPushI64PairSign(0xffffffff, 0x7fffffff), 0);
  // ---- wrap composite (model-only BigInt oracle law) ----
  assert.equal(luaEnginePusherPushI64PairSigned64(0xffffffff, 0xffffffff), -1n);
  assert.equal(luaEnginePusherPushI64PairSigned64(0xffffffff, 0), 0xffffffffn);
  assert.equal(luaEnginePusherPushI64PairSigned64(0x80000000, 0), 0x80000000n);
  assert.equal(luaEnginePusherPushI64PairSigned64(0, 0x80000000),
    -(0x8000000000000000n));
  assert.equal(luaEnginePusherPushI64PairSigned64(0x12345678, 0x9abcdef0),
    -(0x6543210fedcba988n));
});

test("native/Wasm differential: v25g PUSH_I64_PAIR band WIDE drive", () => {
  const native = loadExports();
  /* WIDE drive: byte-gate exports must NOT be pre-masked — drive 0x100 /
   * 0x1ff / 0xffffffff on both lanes. */
  const wide = [0x00000100, 0x000001ff, 0xffffffff];
  for (const v of wide) {
    assert.equal(native.pushI64PairLo(v, 0xdeadbeef) >>> 0, v);
    assert.equal(native.pushI64PairLo(v, 0xdeadbeef) >>> 0,
      luaEnginePusherPushI64PairLo(v, 0xdeadbeef));
    assert.equal(native.pushI64PairHi(0xdeadbeef, v) >>> 0, v);
    assert.equal(native.pushI64PairHi(0xdeadbeef, v) >>> 0,
      luaEnginePusherPushI64PairHi(0xdeadbeef, v));
  }
  const pairs = [
    [0x12345678, 0x9abcdef0],
    [0xffffffff, 0xffffffff],
    [0x00000000, 0x80000000],
    [0x80000000, 0x00000000],
  ];
  for (const [lo, hi] of pairs) {
    assert.equal(native.pushI64PairLo(lo, hi) >>> 0, lo);
    assert.equal(native.pushI64PairHi(lo, hi) >>> 0, hi);
    assert.equal(native.pushI64PairLo(lo, hi) >>> 0,
      luaEnginePusherPushI64PairLo(lo, hi));
    assert.equal(native.pushI64PairHi(lo, hi) >>> 0,
      luaEnginePusherPushI64PairHi(lo, hi));
    assert.equal(native.pushI64PairSign(lo, hi) | 0,
      luaEnginePusherPushI64PairSign(lo, hi));
  }
  assert.equal(native.pushI64PairSign(0x80000000, 0) | 0, 0);
  assert.equal(native.pushI64PairSign(0, 0x80000000) | 0, 1);
  assert.equal(native.pushI64PairRetVa() >>> 0, 0x0085c049);
  assert.equal(native.pushI64PairBodyBytes() >>> 0, 0x19);
  assert.equal(native.pushI64PairInsnCount() | 0, 11);
  assert.equal(native.pushI64PairStackAlignMask() >>> 0, 0xfffffff8);
  assert.equal(native.pushI64PairIatVa() >>> 0, 0x00b183f8);
  assert.equal(native.pushI64PairCallCleanup() | 0, 0x0c);
  assert.equal(native.pushI64PairE8Callers() | 0, 5);
});

