test("ABI v56 vecband mutants: seven translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce; the
   * permanent tripwire is the assert.equal/notEqual pair + explicit PE
   * truth. (Applied-and-restored sha256-identical runs recorded in
   * lua-v56-vecband NOTES.) */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: vecA flag byte -> full-word passthrough (0x100 -> 0x100). PE
  // `test eax,eax; setne bl` @0x8b9303/0x8b930a is BYTE-GATED.
  assert.equal(native.vecbandVecAFlagByte(0x100) >>> 0, 0x01);
  assert.notEqual(native.vecbandVecAFlagByte(0x100) >>> 0, 0x100);
  assert.equal(luaEngineVecbandVecAFlagByte(0x100), 0x01);
  assert.notEqual(luaEngineVecbandVecAFlagByte(0x100), 0x100);
  assert.equal(native.vecbandVecAFlagByte(0xffffffff) >>> 0, 0x01);
  // M2: vecB arg word -> byte mask (0x100 -> 0). PE `mov esi,eax`
  // @0x8b9418 keeps the FULL checkinteger word.
  assert.equal(native.vecbandVecBArgWord(0x100) >>> 0, 0x100);
  assert.notEqual(native.vecbandVecBArgWord(0x100) >>> 0, 0x00);
  assert.equal(native.vecbandVecBArgWord(0xffffffff) >>> 0, 0xffffffff);
  assert.equal(luaEngineVecbandVecBArgWord(0x100), 0x100);
  assert.notEqual(luaEngineVecbandVecBArgWord(0x100), 0x00);
  // M3: object_resolve type gate -> byte mask (0x100 -> 0). PE
  // `test eax,eax` @0x8b928b/0x8b939b is FULL-WORD.
  assert.equal(native.vecbandObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.notEqual(native.vecbandObjectResolve(0x100, 0x1234) >>> 0, 0x00);
  assert.equal(luaEngineVecbandObjectResolve(0x100, 0x1234), 0x1234);
  // M4: wrapper result gate -> byte mask (0x100 -> 0). PE `test
  // edi,edi` @0x8b921c is FULL-WORD.
  assert.equal(native.vecbandWrapperResultGate(0x100) >>> 0, 1);
  assert.notEqual(native.vecbandWrapperResultGate(0x100) >>> 0, 0);
  assert.equal(luaEngineVecbandWrapperResultGate(0x100), 1);
  assert.notEqual(luaEngineVecbandWrapperResultGate(0x100), 0);
  // M5: vec-B body bytes folded to VEC-A (0x107 -> 0x10a). PE ret
  // @0x8b9487 - VA 0x8b9380 = 0x108.
  assert.equal(native.vecbandVecBBodyBytes() >>> 0, 0x107);
  assert.notEqual(native.vecbandVecBBodyBytes() >>> 0, 0x10a);
  assert.equal(luaEngineVecbandVecBBodyBytes(), 0x107);
  assert.notEqual(luaEngineVecbandVecBBodyBytes(), 0x10a);
  // M6: wrap key folded to the check key (0xc82a2b -> 0xc82a13). PE
  // push 0xc82a2b @0x8b9229 (rawgetp metatable key) != check key
  // 0xc82a13 @0x8b91ee.
  assert.equal(native.vecbandWrapKey() >>> 0, 0x00c82a2b);
  assert.notEqual(native.vecbandWrapKey() >>> 0, 0x00c82a13);
  assert.equal(luaEngineVecbandWrapKey(), 0x00c82a2b);
  assert.notEqual(luaEngineVecbandWrapKey(), 0x00c82a13);
  assert.notEqual(luaEngineVecbandCheckKey(), luaEngineVecbandWrapKey());
  // M7: getRef edx index 4 -> 7 (fold to the v52 vec-construction
  // index). PE `mov edx,4` @0x8b92be/0x8b93ce.
  assert.equal(native.vecbandVecGetrefEdx(4) >>> 0, 4);
  assert.notEqual(native.vecbandVecGetrefEdx(4) >>> 0, 7);
  assert.equal(LUA_VECBAND_VEC_GETREF_EDX, 0x04);
  assert.notEqual(LUA_VECBAND_VEC_GETREF_EDX, 0x07);
});

test("JS oracle: ABI v57 sibling band (MakeShockwave 0x8b9490 + Play 0x8b95a0)", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed branch-by-branch from fresh
   * cpu-dump/008b9490.txt + 008b95a0.txt (and the installer dumps
   * 00895250.txt / 00895450.txt) — NOT derived from the model or C++.
   *
   * SIB-A 0x8b9490 "MakeShockwave" (89 capstone TRUE insns, ret
   * @0x8b959f, body 0x10f; the "96" census includes B's prologue):
   * ebx-framed + aligned ebp subframe; L=edi=[ebx+8]; lua_type(L,1)
   * @0xb18400 FULL-WORD test @0x8b94ba; nil -> obj=0; else push 0
   * (flags); push KEY 0xc82a13 @0x8b94c5; edx=1; call 0x85c590;
   * obj=[eax+4] @[ebp-4]. touserdata(L, 0xfff0b9d7) @0xb183b0
   * @0x8b94e5 — NO add esp,8 (all locals ebp-relative; the 8 dwords
   * cleaned by the fused add esp,0x20 @0x8b951c). arg3 = checkinteger
   * (L,5) @0xb183f4 -> `mov esi,eax` FULL WORD -> out+0x10 -> push;
   * arg2 = checknumber(L,4) f32 -> out+0x0c; arg1 = checknumber(L,3)
   * f32 -> out+0x08; getArgObject(L, edx=2) @0x8baa50 @0x8b9531 ->
   * r0=[eax] -> out+0x00, r1=[eax+4] -> out+0x04; out 6 dwords @
   * [ebp-0x50] = [r0, r1, num3, num4, int5, ud] (ud=[ebp-8]);
   * real_fn=ud[0]; ecx=obj1; args (&out, num3, num4, int5); ret 0.
   *
   * SIB-B 0x8b95a0 "Play" (99 TRUE insns, ret @0x8b96c8, body 0x128;
   * the "97" census is a mid-body linear decode from 0x8b95c0): same
   * frame; L=esi=[ebx+8]; lua_type FULL-WORD @0x8b95ca; KEY **0xc82a16**
   * @0x8b95d5 (next band above 0xc82a13); edx=1; 0x85c590; obj=[eax+4];
   * NO getArgObject (single E8 = 0x85c590). touserdata @0x8b95f5 -> edi,
   * NO add esp,8 — the 2 leftover dwords become the arg4/arg5 SLOTS
   * (movss [esp]=num6, movss [esp+4]=num7 after fused add esp,0x30
   * @0x8b967b; capstone esp-tracking: final stack = [int2, num3, int4,
   * bool5, num6, num7]). arg0 = checkinteger(L,2) FULL WORD (`mov
   * edx,eax` @0x8b967e); arg1 = checknumber(L,3) f32; arg2 =
   * checkinteger(L,4) FULL WORD (movd xmm1 @0x8b96ab); arg3 =
   * toboolean(L,5) FULL-WORD test @0x8b962e -> setne byte [ebp-0x20]
   * @0x8b9638 -> MEMORY-reloaded dword (stale high bytes, only LOW BYTE
   * deterministic); arg4 = checknumber(L,6) f32; arg5 = checknumber
   * (L,7) f32. real_fn=ud[0]; ecx=obj1; ret 0. */
  // Sibling records.
  assert.equal(LUA_V57_SIB_A_VA, 0x008b9490);
  assert.equal(LUA_V57_SIB_A_RET_VA, 0x008b959f);
  assert.equal(LUA_V57_SIB_A_BODY_BYTES, 0x10f);
  assert.equal(LUA_V57_SIB_A_INSNS, 89);
  assert.equal(luaEngineV57SibAVa(), 0x008b9490);
  assert.equal(luaEngineV57SibARetVa(), 0x008b959f);
  assert.equal(luaEngineV57SibABodyBytes(), 0x10f);
  assert.equal(luaEngineV57SibAInsnCount(), 89);
  assert.equal(LUA_V57_SIB_B_VA, 0x008b95a0);
  assert.equal(LUA_V57_SIB_B_RET_VA, 0x008b96c8);
  assert.equal(LUA_V57_SIB_B_BODY_BYTES, 0x128);
  assert.equal(LUA_V57_SIB_B_INSNS, 99);
  assert.equal(luaEngineV57SibBVa(), 0x008b95a0);
  assert.equal(luaEngineV57SibBRetVa(), 0x008b96c8);
  assert.equal(luaEngineV57SibBBodyBytes(), 0x128);
  assert.equal(luaEngineV57SibBInsnCount(), 99);
  // Shared resolve/gate law constants.
  assert.equal(LUA_V57_CHECK_FLAGS, 0);
  assert.equal(LUA_V57_CHECK_EDX, 1);
  assert.equal(LUA_V57_TYPE_INDEX, 0x01);
  assert.equal(LUA_V57_OBJECT_FIELD_OFF, 0x04);
  assert.equal(LUA_V57_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  assert.equal(LUA_V57_FN_OFF, 0x00);
  assert.equal(luaEngineV57CheckFlags(), 0);
  assert.equal(luaEngineV57CheckEdx(), 1);
  assert.equal(luaEngineV57ObjectFieldOff(), 0x04);
  assert.equal(luaEngineV57TypeIndex(), 0x01);
  assert.equal(luaEngineV57TouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineV57FnOff(), 0x00);
  // Keys: A = EntityRef class key (same as v56), B = the NEXT band.
  assert.equal(LUA_V57_KEY_A, 0x00c82a13);
  assert.equal(LUA_V57_KEY_B, 0x00c82a16);
  assert.equal(luaEngineV57KeyA(), 0x00c82a13);
  assert.equal(luaEngineV57KeyB(), 0x00c82a16);
  assert.notEqual(LUA_V57_KEY_A, LUA_V57_KEY_B);
  // Sibling-A getArgObject + out struct.
  assert.equal(LUA_V57_GET_ARG_OBJECT_VA, 0x008baa50);
  assert.equal(LUA_V57_GET_ARG_EDX, 0x02);
  assert.equal(luaEngineV57GetArgObjectVa(), 0x008baa50);
  assert.equal(luaEngineV57GetArgEdx(), 0x02);
  assert.equal(LUA_V57_SIB_A_ARG1_CHECKNUMBER_INDEX_U32, 0x03);
  assert.equal(LUA_V57_SIB_A_ARG2_CHECKNUMBER_INDEX_U32, 0x04);
  assert.equal(LUA_V57_SIB_A_ARG3_CHECKINTEGER_INDEX_U32, 0x05);
  assert.equal(LUA_V57_SIB_A_OUT_F32_COUNT, 4);
  assert.equal(LUA_V57_SIB_A_OUT_DWORDS, 6);
  assert.equal(LUA_V57_SIB_A_OUT_U32_OFF, 0x10);
  assert.equal(LUA_V57_SIB_A_OUT_UD_OFF, 0x14);
  assert.equal(luaEngineV57SibAArg1ChecknumberIndex(), 0x03);
  assert.equal(luaEngineV57SibAArg2ChecknumberIndex(), 0x04);
  assert.equal(luaEngineV57SibAArg3CheckintegerIndex(), 0x05);
  assert.equal(luaEngineV57SibAOutF32Count(), 4);
  assert.equal(luaEngineV57SibAOutDwords(), 6);
  assert.equal(luaEngineV57OutU32Off(), 0x10);
  assert.equal(luaEngineV57OutUdOff(), 0x14);
  // Sibling-B conductor indices (2..7 in Lua-stack order).
  assert.equal(LUA_V57_SIB_B_ARG0_CHECKINTEGER_INDEX_U32, 0x02);
  assert.equal(LUA_V57_SIB_B_ARG1_CHECKNUMBER_INDEX_U32, 0x03);
  assert.equal(LUA_V57_SIB_B_ARG2_CHECKINTEGER_INDEX_U32, 0x04);
  assert.equal(LUA_V57_SIB_B_ARG3_TOBOOLEAN_INDEX_U32, 0x05);
  assert.equal(LUA_V57_SIB_B_ARG4_CHECKNUMBER_INDEX_U32, 0x06);
  assert.equal(LUA_V57_SIB_B_ARG5_CHECKNUMBER_INDEX_U32, 0x07);
  assert.equal(luaEngineV57SibBArg0CheckintegerIndex(), 0x02);
  assert.equal(luaEngineV57SibBArg1ChecknumberIndex(), 0x03);
  assert.equal(luaEngineV57SibBArg2CheckintegerIndex(), 0x04);
  assert.equal(luaEngineV57SibBArg3TobooleanIndex(), 0x05);
  assert.equal(luaEngineV57SibBArg4ChecknumberIndex(), 0x06);
  assert.equal(luaEngineV57SibBArg5ChecknumberIndex(), 0x07);
  // IAT pins (host, transcribed).
  assert.equal(LUA_V57_IAT_LUA_TYPE, 0x00b18400);
  assert.equal(LUA_V57_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(LUA_V57_IAT_LUA_CHECKINTEGER, 0x00b183f4);
  assert.equal(LUA_V57_IAT_LUA_CHECKNUMBER, 0x00b18324);
  assert.equal(LUA_V57_IAT_LUA_TOBOOLEAN, 0x00b183e8);
  assert.equal(luaEngineV57IatLuaType(), 0x00b18400);
  assert.equal(luaEngineV57IatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineV57IatLuaCheckinteger(), 0x00b183f4);
  assert.equal(luaEngineV57IatLuaChecknumber(), 0x00b18324);
  assert.equal(luaEngineV57IatLuaToboolean(), 0x00b183e8);
  // Return: both siblings ret 0 Lua values (xor eax,eax).
  assert.equal(LUA_V57_RETURN_VALUE, 0);
  assert.equal(luaEngineV57ReturnValue(), 0);
  // Install sites (reachability, ret-8 SINGLE shape).
  assert.equal(LUA_V57_INSTALL_A_VA, 0x00895250);
  assert.equal(LUA_V57_INSTALL_A_LITERAL_VA, 0x00895263);
  assert.equal(LUA_V57_INSTALL_A_NAME_VA, 0x00b74c00);
  assert.equal(LUA_V57_INSTALL_A_REAL_FN_VA, 0x00703770);
  assert.equal(LUA_V57_INSTALL_B_VA, 0x00895450);
  assert.equal(LUA_V57_INSTALL_B_LITERAL_VA, 0x00895463);
  assert.equal(LUA_V57_INSTALL_B_NAME_VA, 0x00b70498);
  assert.equal(LUA_V57_INSTALL_B_REAL_FN_VA, 0x0092dc30);
  assert.equal(luaEngineV57InstallAVa(), 0x00895250);
  assert.equal(luaEngineV57InstallALiteralVa(), 0x00895263);
  assert.equal(luaEngineV57InstallANameVa(), 0x00b74c00);
  assert.equal(luaEngineV57InstallARealFnVa(), 0x00703770);
  assert.equal(luaEngineV57InstallBVa(), 0x00895450);
  assert.equal(luaEngineV57InstallBLiteralVa(), 0x00895463);
  assert.equal(luaEngineV57InstallBNameVa(), 0x00b70498);
  assert.equal(luaEngineV57InstallBRealFnVa(), 0x0092dc30);
});

test("native/Wasm differential: ABI v57 sibling band WIDE drive", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.abi() | 0, LUA_ENGINE_PURE_ABI_VERSION);
  // Sibling records.
  assert.equal(native.v57SibAVa() >>> 0, luaEngineV57SibAVa());
  assert.equal(native.v57SibARetVa() >>> 0, luaEngineV57SibARetVa());
  assert.equal(native.v57SibABodyBytes() >>> 0, luaEngineV57SibABodyBytes());
  assert.equal(native.v57SibAInsnCount() | 0, luaEngineV57SibAInsnCount());
  assert.equal(native.v57SibBVa() >>> 0, luaEngineV57SibBVa());
  assert.equal(native.v57SibBRetVa() >>> 0, luaEngineV57SibBRetVa());
  assert.equal(native.v57SibBBodyBytes() >>> 0, luaEngineV57SibBBodyBytes());
  assert.equal(native.v57SibBInsnCount() | 0, luaEngineV57SibBInsnCount());
  assert.equal(native.v57CheckFlags() | 0, luaEngineV57CheckFlags());
  assert.equal(native.v57CheckEdx() | 0, luaEngineV57CheckEdx());
  assert.equal(native.v57KeyA() >>> 0, luaEngineV57KeyA());
  assert.equal(native.v57KeyB() >>> 0, luaEngineV57KeyB());
  assert.equal(native.v57ObjectFieldOff() >>> 0, luaEngineV57ObjectFieldOff());
  assert.equal(native.v57TypeIndex() >>> 0, luaEngineV57TypeIndex());
  assert.equal(native.v57TouserdataIndex() >>> 0, luaEngineV57TouserdataIndex());
  assert.equal(native.v57FnOff() >>> 0, luaEngineV57FnOff());
  assert.equal(native.v57GetArgObjectVa() >>> 0, luaEngineV57GetArgObjectVa());
  assert.equal(native.v57GetArgEdx() >>> 0, luaEngineV57GetArgEdx());
  assert.equal(native.v57IatLuaType() >>> 0, luaEngineV57IatLuaType());
  assert.equal(native.v57IatLuaTouserdata() >>> 0, luaEngineV57IatLuaTouserdata());
  assert.equal(native.v57IatLuaCheckinteger() >>> 0, luaEngineV57IatLuaCheckinteger());
  assert.equal(native.v57IatLuaChecknumber() >>> 0, luaEngineV57IatLuaChecknumber());
  assert.equal(native.v57IatLuaToboolean() >>> 0, luaEngineV57IatLuaToboolean());
  assert.equal(native.v57SibAArg1ChecknumberIndex() >>> 0,
    luaEngineV57SibAArg1ChecknumberIndex());
  assert.equal(native.v57SibAArg2ChecknumberIndex() >>> 0,
    luaEngineV57SibAArg2ChecknumberIndex());
  assert.equal(native.v57SibAArg3CheckintegerIndex() >>> 0,
    luaEngineV57SibAArg3CheckintegerIndex());
  assert.equal(native.v57SibAOutF32Count() | 0, luaEngineV57SibAOutF32Count());
  assert.equal(native.v57SibAOutDwords() | 0, luaEngineV57SibAOutDwords());
  assert.equal(native.v57OutU32Off() >>> 0, luaEngineV57OutU32Off());
  assert.equal(native.v57OutUdOff() >>> 0, luaEngineV57OutUdOff());
  assert.equal(native.v57SibBArg0CheckintegerIndex() >>> 0,
    luaEngineV57SibBArg0CheckintegerIndex());
  assert.equal(native.v57SibBArg1ChecknumberIndex() >>> 0,
    luaEngineV57SibBArg1ChecknumberIndex());
  assert.equal(native.v57SibBArg2CheckintegerIndex() >>> 0,
    luaEngineV57SibBArg2CheckintegerIndex());
  assert.equal(native.v57SibBArg3TobooleanIndex() >>> 0,
    luaEngineV57SibBArg3TobooleanIndex());
  assert.equal(native.v57SibBArg4ChecknumberIndex() >>> 0,
    luaEngineV57SibBArg4ChecknumberIndex());
  assert.equal(native.v57SibBArg5ChecknumberIndex() >>> 0,
    luaEngineV57SibBArg5ChecknumberIndex());
  assert.equal(native.v57ReturnValue() | 0, luaEngineV57ReturnValue());
  // Install sites.
  assert.equal(native.v57InstallAVa() >>> 0, luaEngineV57InstallAVa());
  assert.equal(native.v57InstallALiteralVa() >>> 0, luaEngineV57InstallALiteralVa());
  assert.equal(native.v57InstallANameVa() >>> 0, luaEngineV57InstallANameVa());
  assert.equal(native.v57InstallARealFnVa() >>> 0, luaEngineV57InstallARealFnVa());
  assert.equal(native.v57InstallBVa() >>> 0, luaEngineV57InstallBVa());
  assert.equal(native.v57InstallBLiteralVa() >>> 0, luaEngineV57InstallBLiteralVa());
  assert.equal(native.v57InstallBNameVa() >>> 0, luaEngineV57InstallBNameVa());
  assert.equal(native.v57InstallBRealFnVa() >>> 0, luaEngineV57InstallBRealFnVa());
  // WIDE drive (byte-gate discipline: uint32_t + explicit & 0xff).
  const wide = [0, 0x1, 0x100, 0x1ff, 0x10000, 0xffffffff];
  for (const value of wide) {
    assert.equal(native.v57ObjectResolve(value, 0x1234) >>> 0,
      luaEngineV57ObjectResolve(value, 0x1234));
    assert.equal(native.v57BoolLowByte(value) >>> 0, luaEngineV57BoolLowByte(value));
    assert.equal(native.v57IntWord(value) >>> 0, luaEngineV57IntWord(value));
  }
  // WIDE invariants (beyond parity): bool LOW-BYTE, ints FULL WORD.
  assert.equal(native.v57BoolLowByte(0x100) >>> 0, 0x01);
  assert.equal(native.v57BoolLowByte(0xffffffff) >>> 0, 0x01);
  assert.equal(native.v57IntWord(0x100) >>> 0, 0x100);
  assert.equal(native.v57IntWord(0x10000) >>> 0, 0x10000);
  assert.equal(native.v57IntWord(0xffffffff) >>> 0, 0xffffffff);
  // Out lane offsets.
  assert.equal(native.v57OutF32OffAt(0) >>> 0, 0);
  assert.equal(native.v57OutF32OffAt(1) >>> 0, 4);
  assert.equal(native.v57OutF32OffAt(2) >>> 0, 8);
  assert.equal(native.v57OutF32OffAt(3) >>> 0, 0xc);
  assert.equal(native.v57OutF32OffAt(4) >>> 0, 0);
  assert.equal(native.v57OutU32Off() >>> 0, 0x10);
  assert.equal(native.v57OutUdOff() >>> 0, 0x14);
});

