test("ABI v57 sibling mutants: seven translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce; the
   * permanent tripwire is the assert.equal/notEqual pair + explicit PE
   * truth. (Applied-and-restored sha256-identical runs recorded in
   * lua-v57-siblings NOTES.) */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: bool low byte -> full-word passthrough (0x100 -> 0x100). PE
  // `test eax,eax; setne byte [ebp-0x20]` @0x8b962e/0x8b9638 is
  // BYTE-GATED (and the pushed dword is a memory reload with stale high
  // bytes — only the low byte is deterministic).
  assert.equal(native.v57BoolLowByte(0x100) >>> 0, 0x01);
  assert.notEqual(native.v57BoolLowByte(0x100) >>> 0, 0x100);
  assert.equal(luaEngineV57BoolLowByte(0x100), 0x01);
  assert.notEqual(luaEngineV57BoolLowByte(0x100), 0x100);
  assert.equal(native.v57BoolLowByte(0xffffffff) >>> 0, 0x01);
  // M2: int word -> byte mask (0x100 -> 0). PE `mov esi,eax` @0x8b94fa
  // (A arg3) and `mov edx,eax` @0x8b967e (B arg0) keep the FULL
  // checkinteger word.
  assert.equal(native.v57IntWord(0x100) >>> 0, 0x100);
  assert.notEqual(native.v57IntWord(0x100) >>> 0, 0x00);
  assert.equal(native.v57IntWord(0xffffffff) >>> 0, 0xffffffff);
  assert.equal(luaEngineV57IntWord(0x100), 0x100);
  assert.notEqual(luaEngineV57IntWord(0x100), 0x00);
  // M3: object_resolve type gate -> byte mask (0x100 -> 0). PE `test
  // eax,eax` @0x8b94ba/0x8b95ca is FULL-WORD.
  assert.equal(native.v57ObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.notEqual(native.v57ObjectResolve(0x100, 0x1234) >>> 0, 0x00);
  assert.equal(luaEngineV57ObjectResolve(0x100, 0x1234), 0x1234);
  // M4: sibling-B key folded to sibling-A (0xc82a16 -> 0xc82a13). PE
  // push 0xc82a16 @0x8b95d5 != push 0xc82a13 @0x8b94c5.
  assert.equal(native.v57KeyB() >>> 0, 0x00c82a16);
  assert.notEqual(native.v57KeyB() >>> 0, 0x00c82a13);
  assert.equal(luaEngineV57KeyB(), 0x00c82a16);
  assert.notEqual(luaEngineV57KeyB(), 0x00c82a13);
  assert.notEqual(luaEngineV57KeyA(), luaEngineV57KeyB());
  // M5: sibling-B body bytes folded to sibling-A (0x128 -> 0x10f). PE
  // ret @0x8b96c8 - VA 0x8b95a0 = 0x128.
  assert.equal(native.v57SibBBodyBytes() >>> 0, 0x128);
  assert.notEqual(native.v57SibBBodyBytes() >>> 0, 0x10f);
  assert.equal(luaEngineV57SibBBodyBytes(), 0x128);
  assert.notEqual(luaEngineV57SibBBodyBytes(), 0x10f);
  // M6: getArgObject edx 2 -> 1 (fold to the check edx). PE `mov
  // edx,2` @0x8b951f (ecx=esi(L) @0x8b9529).
  assert.equal(native.v57GetArgEdx() >>> 0, 0x02);
  assert.notEqual(native.v57GetArgEdx() >>> 0, 0x01);
  assert.equal(luaEngineV57GetArgEdx(), 0x02);
  assert.notEqual(luaEngineV57GetArgEdx(), 0x01);
  // M7: sibling-A out u32 off 0x10 -> 0x0c (fold to the num4 f32 slot).
  // PE movq [ebp-0x40],xmm0 @0x8b9563: int5 @ out+0x10, ud @ out+0x14.
  assert.equal(native.v57OutU32Off() >>> 0, 0x10);
  assert.notEqual(native.v57OutU32Off() >>> 0, 0x0c);
  assert.equal(luaEngineV57OutU32Off(), 0x10);
  assert.notEqual(luaEngineV57OutU32Off(), 0x0c);
  assert.equal(native.v57OutUdOff() >>> 0, 0x14);
  assert.notEqual(native.v57OutUdOff() >>> 0, 0x10);
});

test("JS oracle: ABI v58 wrapper 0x8b96d0 (AdjustVolume/AdjustPitch shared body)", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed branch-by-branch from fresh
   * cpu-dump/008b96d0.txt + the installer dump 008954b0.txt — NOT
   * derived from the model or C++.
   *
   * 0x8b96d0 (48 capstone TRUE insns, ret @0x8b9751, body 0x81 = RET_VA - VA): SIMPLE
   * ebp frame (`push ebp; mov ebp,esp; sub esp,0x10; push esi; push
   * edi`), NOT the ebx-framed + aligned-ebp v56/v57 template; L =
   * esi=[ebp+8]; locals [ebp-4] (obj1) + [ebp-0xc] (num3). lua_type
   * (L,1) @0xb18400 @0x8b96de, add esp,8, FULL-WORD test @0x8b96e7;
   * nil -> obj1=0; else push 0 (flags); push KEY 0xc82a16 @0x8b96f2
   * (SAME key as v57 Play); edx=1; ecx=esi; call 0x85c590 @0x8b96fe;
   * obj=[eax+4] @[ebp-4]. touserdata(L, 0xfff0b9d7) @0xb183b0
   * @0x8b9712 -> edi — NO add esp,8; then checknumber(L,3) @0xb18324
   * @0x8b971d and checkinteger(L,2) @0xb183f4 @0x8b9729 — all THREE
   * pairs left pushed, ONE fused `add esp,0x14` @0x8b9732; the leftover
   * upvidx dword is reused as the arg1 SLOT: movss [esp],xmm0 @0x8b9740
   * writes num3 f32 exactly into it (v57 Play esp lesson). arg0 = int2
   * = checkinteger result -> `push eax` @0x8b9745 FULL WORD; arg1 =
   * num3 f32. real_fn = ud[0]; ecx = obj1 (this) @0x8b9735; stack args
   * (int2, num3); xor eax,eax @0x8b974b -> ret 0. */
  // Body records.
  assert.equal(LUA_V58_VA, 0x008b96d0);
  assert.equal(LUA_V58_RET_VA, 0x008b9751);
  assert.equal(LUA_V58_BODY_BYTES, 0x81);
  assert.equal(LUA_V58_INSNS, 48);
  assert.equal(luaEngineV58Va(), 0x008b96d0);
  assert.equal(luaEngineV58RetVa(), 0x008b9751);
  assert.equal(luaEngineV58BodyBytes(), 0x81);
  assert.equal(luaEngineV58InsnCount(), 48);
  // Shared resolve/gate law constants.
  assert.equal(LUA_V58_CHECK_FLAGS, 0);
  assert.equal(LUA_V58_CHECK_EDX, 1);
  assert.equal(LUA_V58_TYPE_INDEX, 0x01);
  assert.equal(LUA_V58_OBJECT_FIELD_OFF, 0x04);
  assert.equal(LUA_V58_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  assert.equal(LUA_V58_FN_OFF, 0x00);
  assert.equal(luaEngineV58CheckFlags(), 0);
  assert.equal(luaEngineV58CheckEdx(), 1);
  assert.equal(luaEngineV58TypeIndex(), 0x01);
  assert.equal(luaEngineV58ObjectFieldOff(), 0x04);
  assert.equal(luaEngineV58TouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineV58FnOff(), 0x00);
  // Key: the SAME 0xc82a16 band as v57 Play (the differentiator vs v57
  // is the SIMPLE ebp frame + TWO args — no bool, no getArgObject).
  assert.equal(LUA_V58_KEY, 0x00c82a16);
  assert.equal(luaEngineV58Key(), 0x00c82a16);
  assert.equal(LUA_V58_KEY, LUA_V57_KEY_B);
  // Conductor indices (arg0 checkinteger idx 2, arg1 checknumber idx 3).
  assert.equal(LUA_V58_ARG0_CHECKINTEGER_INDEX_U32, 0x02);
  assert.equal(LUA_V58_ARG1_CHECKNUMBER_INDEX_U32, 0x03);
  assert.equal(luaEngineV58Arg0CheckintegerIndex(), 0x02);
  assert.equal(luaEngineV58Arg1ChecknumberIndex(), 0x03);
  // IAT pins (host, transcribed).
  assert.equal(LUA_V58_IAT_LUA_TYPE, 0x00b18400);
  assert.equal(LUA_V58_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(LUA_V58_IAT_LUA_CHECKNUMBER, 0x00b18324);
  assert.equal(LUA_V58_IAT_LUA_CHECKINTEGER, 0x00b183f4);
  assert.equal(luaEngineV58IatLuaType(), 0x00b18400);
  assert.equal(luaEngineV58IatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineV58IatLuaChecknumber(), 0x00b18324);
  assert.equal(luaEngineV58IatLuaCheckinteger(), 0x00b183f4);
  // Return: ret 0 Lua values (xor eax,eax @0x8b974b).
  assert.equal(LUA_V58_RETURN_VALUE, 0);
  assert.equal(luaEngineV58ReturnValue(), 0);
  // Install site (ret-8 SINGLE-reg shape — v50 helper-13 0x89fd80
  // lineage; wrapper literal dword @0x8954c9 = push 0x8b96d0 @0x8954c8).
  assert.equal(LUA_V58_INSTALL_VA, 0x008954b0);
  assert.equal(LUA_V58_INSTALL_LITERAL_VA, 0x008954c9);
  assert.equal(LUA_V58_INSTALL_REAL_FN_A_VA, 0x0092df40);
  assert.equal(LUA_V58_INSTALL_NAME_A_VA, 0x00b74bf0); /* "AdjustVolume" */
  assert.equal(LUA_V58_INSTALL_CALLER_A_VA, 0x0086da96);
  assert.equal(LUA_V58_INSTALL_REAL_FN_B_VA, 0x0092e050);
  assert.equal(LUA_V58_INSTALL_NAME_B_VA, 0x00b74bc4); /* "AdjustPitch" */
  assert.equal(LUA_V58_INSTALL_CALLER_B_VA, 0x0086daa7);
  assert.equal(luaEngineV58InstallVa(), 0x008954b0);
  assert.equal(luaEngineV58InstallLiteralVa(), 0x008954c9);
  assert.equal(luaEngineV58InstallRealFnAVa(), 0x0092df40);
  assert.equal(luaEngineV58InstallNameAVa(), 0x00b74bf0);
  assert.equal(luaEngineV58InstallCallerAVa(), 0x0086da96);
  assert.equal(luaEngineV58InstallRealFnBVa(), 0x0092e050);
  assert.equal(luaEngineV58InstallNameBVa(), 0x00b74bc4);
  assert.equal(luaEngineV58InstallCallerBVa(), 0x0086daa7);
  assert.notEqual(LUA_V58_INSTALL_NAME_A_VA, LUA_V58_INSTALL_NAME_B_VA);
  assert.notEqual(LUA_V58_INSTALL_REAL_FN_A_VA, LUA_V58_INSTALL_REAL_FN_B_VA);
});

test("native/Wasm differential: ABI v58 wrapper 0x8b96d0 WIDE drive", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.abi() | 0, LUA_ENGINE_PURE_ABI_VERSION);
  // Body records.
  assert.equal(native.v58Va() >>> 0, luaEngineV58Va());
  assert.equal(native.v58RetVa() >>> 0, luaEngineV58RetVa());
  assert.equal(native.v58BodyBytes() >>> 0, luaEngineV58BodyBytes());
  assert.equal(native.v58InsnCount() | 0, luaEngineV58InsnCount());
  assert.equal(native.v58CheckFlags() | 0, luaEngineV58CheckFlags());
  assert.equal(native.v58CheckEdx() | 0, luaEngineV58CheckEdx());
  assert.equal(native.v58Key() >>> 0, luaEngineV58Key());
  assert.equal(native.v58ObjectFieldOff() >>> 0, luaEngineV58ObjectFieldOff());
  assert.equal(native.v58TypeIndex() >>> 0, luaEngineV58TypeIndex());
  assert.equal(native.v58TouserdataIndex() >>> 0, luaEngineV58TouserdataIndex());
  assert.equal(native.v58FnOff() >>> 0, luaEngineV58FnOff());
  assert.equal(native.v58IatLuaType() >>> 0, luaEngineV58IatLuaType());
  assert.equal(native.v58IatLuaTouserdata() >>> 0, luaEngineV58IatLuaTouserdata());
  assert.equal(native.v58IatLuaChecknumber() >>> 0, luaEngineV58IatLuaChecknumber());
  assert.equal(native.v58IatLuaCheckinteger() >>> 0, luaEngineV58IatLuaCheckinteger());
  assert.equal(native.v58Arg0CheckintegerIndex() >>> 0,
    luaEngineV58Arg0CheckintegerIndex());
  assert.equal(native.v58Arg1ChecknumberIndex() >>> 0,
    luaEngineV58Arg1ChecknumberIndex());
  assert.equal(native.v58ReturnValue() | 0, luaEngineV58ReturnValue());
  // Install sites.
  assert.equal(native.v58InstallVa() >>> 0, luaEngineV58InstallVa());
  assert.equal(native.v58InstallLiteralVa() >>> 0, luaEngineV58InstallLiteralVa());
  assert.equal(native.v58InstallRealFnAVa() >>> 0, luaEngineV58InstallRealFnAVa());
  assert.equal(native.v58InstallNameAVa() >>> 0, luaEngineV58InstallNameAVa());
  assert.equal(native.v58InstallCallerAVa() >>> 0, luaEngineV58InstallCallerAVa());
  assert.equal(native.v58InstallRealFnBVa() >>> 0, luaEngineV58InstallRealFnBVa());
  assert.equal(native.v58InstallNameBVa() >>> 0, luaEngineV58InstallNameBVa());
  assert.equal(native.v58InstallCallerBVa() >>> 0, luaEngineV58InstallCallerBVa());
  // WIDE drive (uint32_t full-word discipline — the v58 body has NO
  // byte-gated lane: gate + int word are FULL-WORD, per PE).
  const wide = [0, 0x1, 0x100, 0x1ff, 0x10000, 0xffffffff];
  for (const value of wide) {
    assert.equal(native.v58ObjectResolve(value, 0x1234) >>> 0,
      luaEngineV58ObjectResolve(value, 0x1234));
    assert.equal(native.v58IntWord(value) >>> 0, luaEngineV58IntWord(value));
  }
  // WIDE invariants: FULL WORD survives both laws.
  assert.equal(native.v58ObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.equal(native.v58IntWord(0x100) >>> 0, 0x100);
  assert.equal(native.v58IntWord(0x10000) >>> 0, 0x10000);
  assert.equal(native.v58IntWord(0xffffffff) >>> 0, 0xffffffff);
});

