  // Return: ret 0 Lua values (xor eax,eax @0x8b97c5).
  assert.equal(LUA_V59_RETURN_VALUE, 0);
  assert.equal(luaEngineV59ReturnValue(), 0);
  // Install site (ret-8 SINGLE-reg shape — byte-identical to the v58
