  // 0x8b9760 @0x895528 inside installer 0x895510).
  assert.equal(LUA_V59_INSTALL_VA, 0x00895510);
  assert.equal(LUA_V59_INSTALL_LITERAL_VA, 0x00895529);
  assert.equal(LUA_V59_INSTALL_REAL_FN_A_VA, 0x0092e230);
  assert.equal(LUA_V59_INSTALL_NAME_A_VA, 0x00b1d6f4); /* "Stop" */
  assert.equal(LUA_V59_INSTALL_CALLER_A_VA, 0x0086dab8);
  assert.equal(LUA_V59_INSTALL_REAL_FN_B_VA, 0x0092cf40);
  assert.equal(LUA_V59_INSTALL_NAME_B_VA, 0x00b74bac); /* "Preload" */
  assert.equal(LUA_V59_INSTALL_CALLER_B_VA, 0x0086dada);
  assert.equal(luaEngineV59InstallVa(), 0x00895510);
  assert.equal(luaEngineV59InstallLiteralVa(), 0x00895529);
  assert.equal(luaEngineV59InstallRealFnAVa(), 0x0092e230);
  assert.equal(luaEngineV59InstallNameAVa(), 0x00b1d6f4);
  assert.equal(luaEngineV59InstallCallerAVa(), 0x0086dab8);
  assert.equal(luaEngineV59InstallRealFnBVa(), 0x0092cf40);
  assert.equal(luaEngineV59InstallNameBVa(), 0x00b74bac);
