test("ABI v59 wrapper mutants: six translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce; the
   * permanent tripwire is the assert.equal/notEqual pair + explicit PE
   * truth. (Applied-and-restored sha256-identical runs recorded in
   * lua-v59-8b9760 NOTES.) */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: int word -> byte mask (0x100 -> 0). PE `push eax` @0x8b97bf
  // keeps the FULL checkinteger(L,2) word.
  assert.equal(native.v59IntWord(0x100) >>> 0, 0x100);
  assert.notEqual(native.v59IntWord(0x100) >>> 0, 0x00);
  assert.equal(native.v59IntWord(0xffffffff) >>> 0, 0xffffffff);
  assert.equal(luaEngineV59IntWord(0x100), 0x100);
  assert.notEqual(luaEngineV59IntWord(0x100), 0x00);
  // M2: object_resolve type gate -> byte mask (0x100 -> 0). PE `test
  // eax,eax` @0x8b977a is FULL-WORD.
  assert.equal(native.v59ObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.notEqual(native.v59ObjectResolve(0x100, 0x1234) >>> 0, 0x00);
  assert.equal(luaEngineV59ObjectResolve(0x100, 0x1234), 0x1234);
  // M3: key folded to 0xc82a13 (the v57 MakeShockwave band). PE push
  // 0xc82a16 @0x8b9786 != push 0xc82a13 @0x8b94c5.
  assert.equal(native.v59Key() >>> 0, 0x00c82a16);
  assert.notEqual(native.v59Key() >>> 0, 0x00c82a13);
  assert.equal(luaEngineV59Key(), 0x00c82a16);
  assert.notEqual(luaEngineV59Key(), 0x00c82a13);
  // M4: body bytes folded to the v58 body length (0x6b -> 0x81). PE
  // ret @0x8b97cb - VA 0x8b9760 = 0x6b.
  assert.equal(native.v59BodyBytes() >>> 0, 0x6b);
  assert.notEqual(native.v59BodyBytes() >>> 0, 0x81);
  assert.equal(luaEngineV59BodyBytes(), 0x6b);
  assert.notEqual(luaEngineV59BodyBytes(), 0x81);
  // M5: install literal folded to the v58 Adjust literal (0x895529 ->
  // 0x8954c9). PE dword @0x895529 = 0x8b9760 (push @0x895528).
  assert.equal(native.v59InstallLiteralVa() >>> 0, 0x00895529);
  assert.notEqual(native.v59InstallLiteralVa() >>> 0, 0x008954c9);
  assert.equal(luaEngineV59InstallLiteralVa(), 0x00895529);
  assert.notEqual(luaEngineV59InstallLiteralVa(), 0x008954c9);
  // M6: arg0 checkinteger index 2 -> 3 (fold to a 2-arg body). PE push
  // 2 @0x8b97ad (checkinteger idx 2) is the ONLY conductor.
  assert.equal(native.v59Arg0CheckintegerIndex() >>> 0, 0x02);
  assert.notEqual(native.v59Arg0CheckintegerIndex() >>> 0, 0x03);
  assert.equal(luaEngineV59Arg0CheckintegerIndex(), 0x02);
  assert.notEqual(luaEngineV59Arg0CheckintegerIndex(), 0x03);
});

test("JS oracle: ABI v60 wrapper 0x8b97d0 (StopLoopingSounds — ZERO-ARG)", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed branch-by-branch from the fresh
   * capstone TRUE body (0x8b97d0..0x8b981f) + installer dump
   * 00895570.txt — NOT derived from the model or C++.
   *
   * 0x8b97d0 (32 capstone TRUE insns, ret @0x8b981f, body 0x4f =
   * RET_VA - VA): SIMPLE ebp frame (`push ebp; mov ebp,esp; push esi;
   * mov esi,[ebp+8]; push edi` — v58-shaped, NOT the v59 aligned
   * no-ebx); L = esi = [ebp+8]; obj1 lives in EDI (REGISTER) the whole
   * body — ZERO mem stores (the v59 [esp+0xc] slot is absent).
   * lua_type(L,1) @0xb18400 @0x8b97db, add esp,8, FULL-WORD test
   * @0x8b97e4; nil -> obj1=0; else push 0 (flags); push KEY 0xc82a16
   * @0x8b97ee (SAME key as v57/v58/v59); edx=1; ecx=esi; call 0x85c590
   * @0x8b97fa; obj=[eax+4] @0x8b9802. touserdata(L, 0xfff0b9d7)
   * @0xb183b0 @0x8b980b -> add esp,8 @0x8b9811 (cleanup PRESENT — the
   * v59 fused no-cleanup is NOT this body); ecx = obj1 AFTER cleanup
   * @0x8b9814; eax = [eax] (ud[0], FN_OFF 0) @0x8b9816; `call eax`
   * @0x8b9818 with ZERO pushed args — NO checkinteger/checknumber/
   * toboolean anywhere (indirect list is ONLY [0xb18400] + [0xb183b0]
   * + eax). xor eax,eax @0x8b981b -> ret 0. */
  // Body records.
  assert.equal(LUA_V60_VA, 0x008b97d0);
  assert.equal(LUA_V60_RET_VA, 0x008b981f);
  assert.equal(LUA_V60_BODY_BYTES, 0x4f);
  assert.equal(LUA_V60_INSNS, 32);
  assert.equal(luaEngineV60Va(), 0x008b97d0);
  assert.equal(luaEngineV60RetVa(), 0x008b981f);
  assert.equal(luaEngineV60BodyBytes(), 0x4f);
  assert.equal(luaEngineV60InsnCount(), 32);
  // Shared resolve/gate law constants.
  assert.equal(LUA_V60_CHECK_FLAGS, 0);
  assert.equal(LUA_V60_CHECK_EDX, 1);
  assert.equal(LUA_V60_TYPE_INDEX, 0x01);
  assert.equal(LUA_V60_OBJECT_FIELD_OFF, 0x04);
  assert.equal(LUA_V60_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  assert.equal(LUA_V60_FN_OFF, 0x00);
  assert.equal(luaEngineV60CheckFlags(), 0);
  assert.equal(luaEngineV60CheckEdx(), 1);
  assert.equal(luaEngineV60TypeIndex(), 0x01);
  assert.equal(luaEngineV60ObjectFieldOff(), 0x04);
  assert.equal(luaEngineV60TouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineV60FnOff(), 0x00);
  // Key: the SAME 0xc82a16 band as v57/v58/v59 (the differentiator is
  // the SIMPLE ebp frame + ZERO args — no int, no bool, no checknumber,
  // no getArgObject).
  assert.equal(LUA_V60_KEY, 0x00c82a16);
  assert.equal(luaEngineV60Key(), 0x00c82a16);
  assert.equal(LUA_V60_KEY, LUA_V58_KEY);
  assert.equal(LUA_V60_KEY, LUA_V59_KEY);
  // IAT pins (host, transcribed — NO checkinteger/checknumber:
  // this ZERO-ARG body has only type/touserdata).
  assert.equal(LUA_V60_IAT_LUA_TYPE, 0x00b18400);
  assert.equal(LUA_V60_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(luaEngineV60IatLuaType(), 0x00b18400);
  assert.equal(luaEngineV60IatLuaTouserdata(), 0x00b183b0);
  // Return: ret 0 Lua values (xor eax,eax @0x8b981b).
  assert.equal(LUA_V60_RETURN_VALUE, 0);
  assert.equal(luaEngineV60ReturnValue(), 0);
  // Install site (ret-8 IMMEDIATE-held SINGLE shape — the v59 NOTES
  // next-frontier "0x895570 area"; wrapper literal dword @0x895583 =
  // push 0x8b97d0 @0x895582; real_fn 0x92e300 + name 0xb74bd0 are
  // BODY IMMEDIATES, caller @0x86dac9's pushed dwords DEAD).
  assert.equal(LUA_V60_INSTALL_VA, 0x00895570);
  assert.equal(LUA_V60_INSTALL_LITERAL_VA, 0x00895583);
  assert.equal(LUA_V60_INSTALL_REAL_FN_VA, 0x0092e300);
  assert.equal(LUA_V60_INSTALL_NAME_VA, 0x00b74bd0); /* "StopLoopingSounds" */
  assert.equal(LUA_V60_INSTALL_CALLER_VA, 0x0086dac9);
  assert.equal(luaEngineV60InstallVa(), 0x00895570);
  assert.equal(luaEngineV60InstallLiteralVa(), 0x00895583);
  assert.equal(luaEngineV60InstallRealFnVa(), 0x0092e300);
  assert.equal(luaEngineV60InstallNameVa(), 0x00b74bd0);
  assert.equal(luaEngineV60InstallCallerVa(), 0x0086dac9);
});

