test("JS oracle: ABI v61 wrapper 0x8b9820 (IsPlaying — int arg + byte-gated bool return)", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed branch-by-branch from the fresh
   * capstone TRUE body (0x8b9820..0x8b98a0) + installer dump — NOT
   * derived from the model or C++.
   *
   * 0x8b9820 (48 capstone TRUE insns, ret @0x8b98a0, body 0x80 =
   * RET_VA - VA): ALIGNED-ebp no-ebx frame (`push ebp; mov ebp,esp;
   * and esp,0xfffffff8; sub esp,8; push esi; push edi` — v59-shaped,
   * NOT v60's SIMPLE ebp); L = edi = [ebp+8]; obj1 lives in the
   * [esp+0xc] SPILL SLOT (mem-stores 2, both @[esp+0xc]).
   * lua_type(L,1) @0xb18400 @0x8b9831, add esp,8, FULL-WORD test
   * @0x8b983a; nil -> obj1=0 @[esp+0xc] + jmp @0x8b9842; else push 0
   * (flags); push KEY 0xc82a16 @0x8b9846 (SAME key as v57..v60);
   * edx=1; ecx=edi; call 0x85c590 @0x8b9852; obj=[eax+4] @0x8b985a
   * -> [esp+0xc] @0x8b985d. touserdata(L, 0xfff0b9d7) @0xb183b0
   * @0x8b9867 -> esi (NO add esp,8 — the v56/v57/v59 lesson);
   * arg0 = int2 = luaL_checkinteger(L,2) @0xb183f4 @0x8b9872 (push 2;
   * push edi) -> eax; ESP-TRACKING: real_fn = ud[0] (FN_OFF 0) loaded
   * BEFORE cleanup @0x8b9878, ONE fused add esp,0x10 @0x8b987a, then
   * obj1 = [esp+0xc] @0x8b987d AFTER the restore (write level == read
   * level -> same [ebp-4] slot; contrast v59's read-before-cleanup
   * @[esp+0x1c]); `push eax` @0x8b9881 = int2 FULL WORD; `call edx`
   * @0x8b9882 = real_fn(obj1, int2). BYTE-GATED RETURN: xor ecx,ecx;
   * test al,al @0x8b9886; setne cl @0x8b9888 ((eax & 0xff) != 0);
   * push ecx; push edi (L); lua_pushboolean(L, res) @0xb183ec
   * @0x8b988d; add esp,8; mov eax,1 @0x8b9896 -> ret 1 Lua value;
   * ret @0x8b98a0. */
  // Body records.
  assert.equal(LUA_V61_VA, 0x008b9820);
  assert.equal(LUA_V61_RET_VA, 0x008b98a0);
  assert.equal(LUA_V61_BODY_BYTES, 0x80);
  assert.equal(LUA_V61_INSNS, 48);
  assert.equal(luaEngineV61Va(), 0x008b9820);
  assert.equal(luaEngineV61RetVa(), 0x008b98a0);
  assert.equal(luaEngineV61BodyBytes(), 0x80);
  assert.equal(luaEngineV61InsnCount(), 48);
  // Shared resolve/gate law constants.
  assert.equal(LUA_V61_CHECK_FLAGS, 0);
  assert.equal(LUA_V61_CHECK_EDX, 1);
  assert.equal(LUA_V61_TYPE_INDEX, 0x01);
  assert.equal(LUA_V61_OBJECT_FIELD_OFF, 0x04);
  assert.equal(LUA_V61_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  assert.equal(LUA_V61_FN_OFF, 0x00);
  assert.equal(luaEngineV61CheckFlags(), 0);
  assert.equal(luaEngineV61CheckEdx(), 1);
  assert.equal(luaEngineV61TypeIndex(), 0x01);
  assert.equal(luaEngineV61ObjectFieldOff(), 0x04);
  assert.equal(luaEngineV61TouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineV61FnOff(), 0x00);
  // Key: the SAME 0xc82a16 band as v57..v60 (the differentiator is the
  // aligned-ebp frame + ONE int arg + ONE byte-gated bool return).
  assert.equal(LUA_V61_KEY, 0x00c82a16);
  assert.equal(luaEngineV61Key(), 0x00c82a16);
  assert.equal(LUA_V61_KEY, LUA_V60_KEY);
  // Int lane (arg0): checkinteger index 2 (push 2 @0x8b986d).
  assert.equal(LUA_V61_ARG0_CHECKINTEGER_INDEX_U32, 0x02);
  assert.equal(luaEngineV61Arg0CheckintegerIndex(), 0x02);
  // IAT pins (host, transcribed — this body is the FIRST in the band
  // with lua_pushboolean; type + touserdata + checkinteger + pushboolean).
  assert.equal(LUA_V61_IAT_LUA_TYPE, 0x00b18400);
  assert.equal(LUA_V61_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(LUA_V61_IAT_LUA_CHECKINTEGER, 0x00b183f4);
  assert.equal(LUA_V61_IAT_LUA_PUSHBOOLEAN, 0x00b183ec);
  assert.equal(luaEngineV61IatLuaType(), 0x00b18400);
  assert.equal(luaEngineV61IatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineV61IatLuaCheckinteger(), 0x00b183f4);
  assert.equal(luaEngineV61IatLuaPushboolean(), 0x00b183ec);
  assert.equal(LUA_V61_IAT_LUA_PUSHBOOLEAN, LUA_PROPERTY_CLOSURE_IAT_LUA_PUSHBOOLEAN);
  // Return: BYTE-gated lua_pushboolean (test al,al @0x8b9886) -> ret 1.
  assert.equal(LUA_V61_RETURN_VALUE, 1);
  assert.equal(luaEngineV61ReturnValue(), 1);
  // Laws, oracle side, on unmasked wide values.
  // object_resolve = FULL-WORD lua_type gate: 0x100 IS nonzero.
  assert.equal(luaEngineV61ObjectResolve(0, 0x1234), 0);
  assert.equal(luaEngineV61ObjectResolve(0x100, 0x1234), 0x1234);
  assert.equal(luaEngineV61ObjectResolve(0xffffffff, 0x1234), 0x1234);
  // int_word = FULL WORD passthrough (push eax @0x8b9881).
  assert.equal(luaEngineV61IntWord(0x100), 0x100);
  assert.equal(luaEngineV61IntWord(0x10000), 0x10000);
  assert.equal(luaEngineV61IntWord(0xffffffff), 0xffffffff);
  // return_gate = BYTE (test al,al @0x8b9886): only (result & 0xff).
  assert.equal(luaEngineV61ReturnGate(0), 0);
  assert.equal(luaEngineV61ReturnGate(1), 1);
  assert.equal(luaEngineV61ReturnGate(0xff), 1);
  assert.equal(luaEngineV61ReturnGate(0x100), 0);
  assert.equal(luaEngineV61ReturnGate(0x1ff), 1);
  assert.equal(luaEngineV61ReturnGate(0xff00), 0);
  assert.equal(luaEngineV61ReturnGate(0xffffff00), 0);
  assert.equal(luaEngineV61ReturnGate(0xffffffff), 1);
  // Install site (ret-8 IMMEDIATE-held SINGLE shape — the v60 NOTES
  // next-frontier "0x8955d0 area"; wrapper literal dword @0x8955e3 =
  // push 0x8b9820 @0x8955e2; real_fn 0x92e560 + name 0xb70584 are
  // BODY IMMEDIATES @0x8955e8/@0x8955fd, caller @0x86daeb's pushed
  // dwords DEAD).
  assert.equal(LUA_V61_INSTALL_VA, 0x008955d0);
  assert.equal(LUA_V61_INSTALL_LITERAL_VA, 0x008955e3);
  assert.equal(LUA_V61_INSTALL_REAL_FN_VA, 0x0092e560);
  assert.equal(LUA_V61_INSTALL_NAME_VA, 0x00b70584); /* "IsPlaying" */
  assert.equal(LUA_V61_INSTALL_CALLER_VA, 0x0086daeb);
  assert.equal(luaEngineV61InstallVa(), 0x008955d0);
  assert.equal(luaEngineV61InstallLiteralVa(), 0x008955e3);
  assert.equal(luaEngineV61InstallRealFnVa(), 0x0092e560);
  assert.equal(luaEngineV61InstallNameVa(), 0x00b70584);
  assert.equal(luaEngineV61InstallCallerVa(), 0x0086daeb);
});

test("native/Wasm differential: ABI v61 wrapper 0x8b9820 WIDE drive", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.abi() | 0, LUA_ENGINE_PURE_ABI_VERSION);
  // Body records.
  assert.equal(native.v61Va() >>> 0, luaEngineV61Va());
  assert.equal(native.v61RetVa() >>> 0, luaEngineV61RetVa());
  assert.equal(native.v61BodyBytes() >>> 0, luaEngineV61BodyBytes());
  assert.equal(native.v61InsnCount() | 0, luaEngineV61InsnCount());
  assert.equal(native.v61CheckFlags() | 0, luaEngineV61CheckFlags());
  assert.equal(native.v61CheckEdx() | 0, luaEngineV61CheckEdx());
  assert.equal(native.v61Key() >>> 0, luaEngineV61Key());
  assert.equal(native.v61ObjectFieldOff() >>> 0, luaEngineV61ObjectFieldOff());
  assert.equal(native.v61TypeIndex() >>> 0, luaEngineV61TypeIndex());
  assert.equal(native.v61TouserdataIndex() >>> 0, luaEngineV61TouserdataIndex());
  assert.equal(native.v61FnOff() >>> 0, luaEngineV61FnOff());
  assert.equal(native.v61Arg0CheckintegerIndex() >>> 0,
    luaEngineV61Arg0CheckintegerIndex());
  assert.equal(native.v61IatLuaType() >>> 0, luaEngineV61IatLuaType());
  assert.equal(native.v61IatLuaTouserdata() >>> 0, luaEngineV61IatLuaTouserdata());
  assert.equal(native.v61IatLuaCheckinteger() >>> 0, luaEngineV61IatLuaCheckinteger());
  assert.equal(native.v61IatLuaPushboolean() >>> 0, luaEngineV61IatLuaPushboolean());
  assert.equal(native.v61ReturnValue() | 0, luaEngineV61ReturnValue());
  // Install sites.
  assert.equal(native.v61InstallVa() >>> 0, luaEngineV61InstallVa());
  assert.equal(native.v61InstallLiteralVa() >>> 0, luaEngineV61InstallLiteralVa());
  assert.equal(native.v61InstallRealFnVa() >>> 0, luaEngineV61InstallRealFnVa());
  assert.equal(native.v61InstallNameVa() >>> 0, luaEngineV61InstallNameVa());
  assert.equal(native.v61InstallCallerVa() >>> 0, luaEngineV61InstallCallerVa());
  // WIDE drive (uint32_t discipline — full-word obj gate + full-word
  // int lane + the BYTE-GATED return law, all RAW values; the Wasm ABI
  // does not narrow i32 arguments, so pre-masking would hide defects).
  const wide = [
    0x00000000, 0x00000001, 0x000000ff, 0x00000100, 0x000001ff,
    0x0000ffff, 0x00010000, 0x7fffffff, 0x80000000, 0xffffff00,
    0xfffffffe, 0xffffffff,
  ];
  for (const value of wide) {
    assert.equal(native.v61ObjectResolve(value, 0x1234) >>> 0,
      luaEngineV61ObjectResolve(value, 0x1234), `obj ${value}`);
    assert.equal(native.v61IntWord(value) >>> 0,
      luaEngineV61IntWord(value), `int ${value}`);
    assert.equal(native.v61ReturnGate(value) >>> 0,
      luaEngineV61ReturnGate(value), `gate ${value}`);
  }
  // WIDE invariants: FULL WORD survives the obj + int laws; the return
  // gate is BYTE (`test al,al` @0x8b9886).
  assert.equal(native.v61ObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.equal(native.v61IntWord(0x100) >>> 0, 0x100);
  assert.equal(native.v61ReturnGate(0x100) >>> 0, 0);
  assert.equal(native.v61ReturnGate(0x1ff) >>> 0, 1);
  assert.equal(native.v61ReturnGate(0xffffff00) >>> 0, 0);
});

test("header pins every ABI v61 wrapper constant to its PE literal", () => {
  const h = readFileSync(header, "utf8");
  // ABI pin.
  assert.match(h, /ISAAC_LUA_ENGINE_PURE_HELPERS_ABI_VERSION = 103/);
  // Body records + shared laws.
  assert.match(h, /ISAAC_LUA_V61_VA = 0x008b9820u/);
  assert.match(h, /ISAAC_LUA_V61_RET_VA = 0x008b98a0u/);
  assert.match(h, /ISAAC_LUA_V61_INSNS = 48/);
  assert.match(h, /ISAAC_LUA_V61_CHECK_FLAGS = 0/);
  assert.match(h, /ISAAC_LUA_V61_CHECK_EDX = 1/);
  assert.match(h, /ISAAC_LUA_V61_TYPE_INDEX = 0x01u/);
  assert.match(h, /ISAAC_LUA_V61_OBJECT_FIELD_OFF = 0x04u/);
  assert.match(h, /ISAAC_LUA_V61_KEY = 0x00c82a16u/);
  assert.match(h, /ISAAC_LUA_V61_TOUSERDATA_INDEX_U32 = 0xfff0b9d7u/);
  assert.match(h, /ISAAC_LUA_V61_FN_OFF = 0x00u/);
  assert.match(h, /ISAAC_LUA_V61_ARG0_CHECKINTEGER_INDEX_U32 = 0x02u/);
  assert.match(h, /ISAAC_LUA_V61_IAT_LUA_TYPE = 0x00b18400u/);
  assert.match(h, /ISAAC_LUA_V61_IAT_LUA_TOUSERDATA = 0x00b183b0u/);
  assert.match(h, /ISAAC_LUA_V61_IAT_LUA_CHECKINTEGER = 0x00b183f4u/);
  assert.match(h, /ISAAC_LUA_V61_IAT_LUA_PUSHBOOLEAN = 0x00b183ecu/);
  assert.match(h, /ISAAC_LUA_V61_RETURN_VALUE = 1/);
  assert.match(h, /ISAAC_LUA_V61_INSTALL_VA = 0x008955d0u/);
  assert.match(h, /ISAAC_LUA_V61_INSTALL_LITERAL_VA = 0x008955e3u/);
  assert.match(h, /ISAAC_LUA_V61_INSTALL_REAL_FN_VA = 0x0092e560u/);
  assert.match(h, /ISAAC_LUA_V61_INSTALL_NAME_VA = 0x00b70584u/);
  assert.match(h, /ISAAC_LUA_V61_INSTALL_CALLER_VA = 0x0086daebu/);
  // Law prototypes.
  assert.match(h, /isaac_lua_engine_v61_object_resolve\(/);
  assert.match(h, /isaac_lua_engine_v61_int_word\(/);
  assert.match(h, /isaac_lua_engine_v61_return_gate\(/);
  // No-arg getters (spot-check first/last of each group).
  for (const name of [
    "isaac_lua_engine_v61_va",
    "isaac_lua_engine_v61_arg0_checkinteger_index",
    "isaac_lua_engine_v61_install_caller_va",
  ]) {
    assert.match(h, new RegExp(name + "\\("));
  }
  // Byte-gate discipline: the return law is uint32_t & 0xff — NO
  // uint8_t scalar anywhere in the family header.
  const hCode = h.replace(/\/\*[\s\S]*?\*\//g, "").replace(/\/\/[^\n]*/g, "");
  assert.doesNotMatch(hCode, /\buint8_t\b/);
});

test("ABI v61 wrapper mutants: six translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce; the
   * permanent tripwire is the assert.equal/notEqual pair + explicit PE
   * truth. (Applied-and-restored sha256-identical runs recorded in
   * lua-v61-8b9820 NOTES.) */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: return_gate byte mask -> FULL WORD (0x100 -> 1 instead of 0 /
  // 0xff00 -> 1 instead of 0). PE `test al,al` @0x8b9886 is BYTE —
  // bits bit7..bit0 only; a full-word translation would be wrong on
  // every low-byte-zero value.
  assert.equal(native.v61ReturnGate(0x100) >>> 0, 0);
  assert.notEqual(native.v61ReturnGate(0x100) >>> 0, 1);
  assert.equal(native.v61ReturnGate(0xff00) >>> 0, 0);
  assert.equal(native.v61ReturnGate(0x1ff) >>> 0, 1);
  assert.equal(luaEngineV61ReturnGate(0x100), 0);
  assert.notEqual(luaEngineV61ReturnGate(0x100), 1);
  assert.equal(luaEngineV61ReturnGate(0xff00), 0);
  // M2: object_resolve type gate -> byte mask (0x100 -> 0). PE `test
  // eax,eax` @0x8b983a is FULL-WORD.
  assert.equal(native.v61ObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.notEqual(native.v61ObjectResolve(0x100, 0x1234) >>> 0, 0x00);
  assert.equal(luaEngineV61ObjectResolve(0x100, 0x1234), 0x1234);
  // M3: int_word -> byte mask (0x100 -> 0). PE `push eax` @0x8b9881
  // keeps the FULL checkinteger word.
  assert.equal(native.v61IntWord(0x100) >>> 0, 0x100);
  assert.notEqual(native.v61IntWord(0x100) >>> 0, 0x00);
  assert.equal(luaEngineV61IntWord(0x100), 0x100);
  // M4: key folded to 0xc82a13 (the v57 MakeShockwave band). PE push
  // 0xc82a16 @0x8b9846 != push 0xc82a13 @0x8b94c5.
  assert.equal(native.v61Key() >>> 0, 0x00c82a16);
  assert.notEqual(native.v61Key() >>> 0, 0x00c82a13);
  assert.equal(luaEngineV61Key(), 0x00c82a16);
  assert.notEqual(luaEngineV61Key(), 0x00c82a13);
  // M5: body bytes folded to a zero-length body (0x80 -> 0x60 would be
  // the v60 body... use the v60 fold: 0x80 - 0x20 = 0x60). PE ret
  // @0x8b98a0 - VA 0x8b9820 = 0x80.
  assert.equal(native.v61BodyBytes() >>> 0, 0x80);
  assert.notEqual(native.v61BodyBytes() >>> 0, 0x60);
  assert.equal(luaEngineV61BodyBytes(), 0x80);
  assert.notEqual(luaEngineV61BodyBytes(), 0x60);
  // M6: install real_fn folded to the v60 real_fn (0x92e560 ->
  // 0x92e300). PE `mov dword ptr [eax], 0x92e560` @0x8955e8 inside
  // installer 0x8955d0 is the immediate.
  assert.equal(native.v61InstallRealFnVa() >>> 0, 0x0092e560);
  assert.notEqual(native.v61InstallRealFnVa() >>> 0, 0x0092e300);
  assert.equal(luaEngineV61InstallRealFnVa(), 0x0092e560);
  assert.notEqual(luaEngineV61InstallRealFnVa(), 0x0092e300);
});

test("JS oracle: ABI v62 wrapper 0x8b98b0 (SetAmbientSound — int + 2 float lanes, ret 0)", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed branch-by-branch from the fresh
   * capstone TRUE body (0x8b98b0..0x8b9948) — NOT derived from the
   * model or C++.
   *
   * 0x8b98b0 (54 capstone TRUE insns, ret @0x8b9948, body 0x98 =
   * RET_VA - VA): SIMPLE ebp frame (`push ebp; mov ebp,esp; sub
   * esp,0x14; push esi; push edi` — v60-shaped, NOT v61's ALIGNED-ebp);
   * L = edi = [ebp+8]; obj1 lives in the [ebp-4] SPILL SLOT (mem-stores
   * 2, both @[ebp-4]; ebp-relative -> esp-shift immune).
   * lua_type(L,1) @0xb18400 @0x8b98be, add esp,8, FULL-WORD test
   * @0x8b98c7; nil -> obj1=0 @[ebp-4] + jmp @0x8b98ec; else push 0
   * (flags); push KEY 0xc82a16 @0x8b98d2 (SAME key as v57B..v61);
   * edx=1; ecx=edi; call 0x85c590 @0x8b98de; obj=[eax+4] @0x8b98e6
   * -> [ebp-4] @0x8b98e9. touserdata(L, 0xfff0b9d7) @0xb183b0
   * @0x8b98f2 -> esi (NO add esp,8 — the 2 arg dwords stay pushed,
   * v56/v57/v59 lesson); arg2 = num4 = luaL_checknumber(L,4) @0xb18324
   * @0x8b98fd -> x87 -> `fstp dword ptr [ebp-0x10]` @0x8b9905; arg1 =
   * num3 = luaL_checknumber(L,3) @0xb18324 @0x8b9909 -> `fstp dword
   * ptr [ebp-8]` @0x8b9915; arg0 = int2 = luaL_checkinteger(L,2)
   * @0xb183f4 @0x8b991b -> eax; SIX dwords pushed, ONE fused
   * add esp,0x18 @0x8b9926. ESP-TRACKING (v62 lesson): AFTER the
   * restored esp, movss [esp+4] @0x8b992c (num4) + movss [esp] @0x8b9937
   * (num3) write into the DEAD SAVED-REGISTER slots ([esp+4]=[ebp-0x18]
   * saved esi, [esp]=[ebp-0x1c] saved edi — the register copies stay
   * live); `push eax` @0x8b993c = int2 FULL WORD; real_fn = [esi]
   * (ud[0], FN_OFF 0) @0x8b993d AFTER all pushes (register-held esi);
   * `call eax` @0x8b993f. Final stack: [esp+0]=int2, [esp+4]=B(num3),
   * [esp+8]=A(num4), [esp+0xc]=junk — real_fn 0x92e620 ret 0xc consumes
   * exactly 3 dwords. this = obj1 in ECX (`mov ecx,[ebp-4]` @0x8b9929
   * after cleanup). xor eax,eax @0x8b9942 -> ret 0 Lua values (NO
   * byte-gated lane — no pushboolean; v61's byte-gated body is NOT
   * this body); pop edi; pop esi; mov esp,ebp; pop ebp; ret @0x8b9948. */
  // Body records.
  assert.equal(LUA_V62_VA, 0x008b98b0);
  assert.equal(LUA_V62_RET_VA, 0x008b9948);
  assert.equal(LUA_V62_BODY_BYTES, 0x98);
  assert.equal(LUA_V62_INSNS, 54);
  assert.equal(luaEngineV62Va(), 0x008b98b0);
  assert.equal(luaEngineV62RetVa(), 0x008b9948);
  assert.equal(luaEngineV62BodyBytes(), 0x98);
  assert.equal(luaEngineV62InsnCount(), 54);
  // Shared resolve/gate law constants.
  assert.equal(LUA_V62_CHECK_FLAGS, 0);
  assert.equal(LUA_V62_CHECK_EDX, 1);
  assert.equal(LUA_V62_TYPE_INDEX, 0x01);
  assert.equal(LUA_V62_OBJECT_FIELD_OFF, 0x04);
  assert.equal(LUA_V62_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  assert.equal(LUA_V62_FN_OFF, 0x00);
  assert.equal(luaEngineV62CheckFlags(), 0);
  assert.equal(luaEngineV62CheckEdx(), 1);
  assert.equal(luaEngineV62TypeIndex(), 0x01);
  assert.equal(luaEngineV62ObjectFieldOff(), 0x04);
  assert.equal(luaEngineV62TouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineV62FnOff(), 0x00);
  // Key: the SAME 0xc82a16 band as v57B..v61 (the differentiator is the
  // SIMPLE ebp frame + THREE args: int + 2 checknumber float lanes).
  assert.equal(LUA_V62_KEY, 0x00c82a16);
  assert.equal(luaEngineV62Key(), 0x00c82a16);
  assert.equal(LUA_V62_KEY, LUA_V61_KEY);
  // Arg lanes: arg0 = checkinteger idx 2 (push 2 @0x8b9916), arg1 =
  // checknumber idx 3 (push 3 @0x8b9908), arg2 = checknumber idx 4
  // (push 4 @0x8b98f8) — the band's first float-lane wrapper.
  assert.equal(LUA_V62_ARG0_CHECKINTEGER_INDEX_U32, 0x02);
  assert.equal(LUA_V62_ARG1_CHECKNUMBER_INDEX_U32, 0x03);
  assert.equal(LUA_V62_ARG2_CHECKNUMBER_INDEX_U32, 0x04);
  assert.equal(luaEngineV62Arg0CheckintegerIndex(), 0x02);
  assert.equal(luaEngineV62Arg1ChecknumberIndex(), 0x03);
  assert.equal(luaEngineV62Arg2ChecknumberIndex(), 0x04);
  // IAT pins (host, transcribed): type + touserdata + checkinteger +
  // checknumber (0xb18324, v22/v56/v57 pin-bound family-wide).
  assert.equal(LUA_V62_IAT_LUA_TYPE, 0x00b18400);
  assert.equal(LUA_V62_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(LUA_V62_IAT_LUA_CHECKINTEGER, 0x00b183f4);
  assert.equal(LUA_V62_IAT_LUA_CHECKNUMBER, 0x00b18324);
  assert.equal(luaEngineV62IatLuaType(), 0x00b18400);
  assert.equal(luaEngineV62IatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineV62IatLuaCheckinteger(), 0x00b183f4);
  assert.equal(luaEngineV62IatLuaChecknumber(), 0x00b18324);
  assert.equal(LUA_V62_IAT_LUA_CHECKNUMBER, LUA_VECBAND_VEC_CHECKNUMBER_IAT_VA);
  // Return: unconditional xor eax,eax @0x8b9942 -> ret 0 Lua values
  // (NO pushboolean, NO byte gate — contrast v61 RETURN_VALUE 1).
  assert.equal(LUA_V62_RETURN_VALUE, 0);
  assert.equal(luaEngineV62ReturnValue(), 0);
  // Laws, oracle side, on unmasked wide values.
  // object_resolve = FULL-WORD lua_type gate: 0x100 IS nonzero.
  assert.equal(luaEngineV62ObjectResolve(0, 0x1234), 0);
  assert.equal(luaEngineV62ObjectResolve(0x100, 0x1234), 0x1234);
  assert.equal(luaEngineV62ObjectResolve(0xffffffff, 0x1234), 0x1234);
  // int_word = FULL WORD passthrough (push eax @0x8b993c).
  assert.equal(luaEngineV62IntWord(0x100), 0x100);
  assert.equal(luaEngineV62IntWord(0x10000), 0x10000);
  assert.equal(luaEngineV62IntWord(0xffffffff), 0xffffffff);
  // Install site (ret-8 IMMEDIATE-held SINGLE shape — the v61 NOTES
  // next-frontier "0x895643"; wrapper literal dword @0x895643 = push
  // 0x8b98b0 @0x895642; real_fn 0x92e620 + name 0xb74bb4 are BODY
  // IMMEDIATES @0x895648/@0x89565d, caller @0x86dafc's pushed dwords
  // DEAD). name 0xb74bb4 = "SetAmbientSound" (.rdata cstr).
  assert.equal(LUA_V62_INSTALL_VA, 0x00895630);
  assert.equal(LUA_V62_INSTALL_LITERAL_VA, 0x00895643);
  assert.equal(LUA_V62_INSTALL_REAL_FN_VA, 0x0092e620);
  assert.equal(LUA_V62_INSTALL_NAME_VA, 0x00b74bb4); /* "SetAmbientSound" */
  assert.equal(LUA_V62_INSTALL_CALLER_VA, 0x0086dafc);
  assert.equal(luaEngineV62InstallVa(), 0x00895630);
  assert.equal(luaEngineV62InstallLiteralVa(), 0x00895643);
  assert.equal(luaEngineV62InstallRealFnVa(), 0x0092e620);
  assert.equal(luaEngineV62InstallNameVa(), 0x00b74bb4);
  assert.equal(luaEngineV62InstallCallerVa(), 0x0086dafc);
});

test("native/Wasm differential: ABI v62 wrapper 0x8b98b0 WIDE drive", () => {
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  assert.equal(native.abi() | 0, LUA_ENGINE_PURE_ABI_VERSION);
  // Body records.
  assert.equal(native.v62Va() >>> 0, luaEngineV62Va());
  assert.equal(native.v62RetVa() >>> 0, luaEngineV62RetVa());
  assert.equal(native.v62BodyBytes() >>> 0, luaEngineV62BodyBytes());
  assert.equal(native.v62InsnCount() | 0, luaEngineV62InsnCount());
  assert.equal(native.v62CheckFlags() | 0, luaEngineV62CheckFlags());
  assert.equal(native.v62CheckEdx() | 0, luaEngineV62CheckEdx());
  assert.equal(native.v62Key() >>> 0, luaEngineV62Key());
  assert.equal(native.v62ObjectFieldOff() >>> 0, luaEngineV62ObjectFieldOff());
  assert.equal(native.v62TypeIndex() >>> 0, luaEngineV62TypeIndex());
  assert.equal(native.v62TouserdataIndex() >>> 0, luaEngineV62TouserdataIndex());
  assert.equal(native.v62FnOff() >>> 0, luaEngineV62FnOff());
  assert.equal(native.v62Arg0CheckintegerIndex() >>> 0,
    luaEngineV62Arg0CheckintegerIndex());
  assert.equal(native.v62Arg1ChecknumberIndex() >>> 0,
    luaEngineV62Arg1ChecknumberIndex());
  assert.equal(native.v62Arg2ChecknumberIndex() >>> 0,
    luaEngineV62Arg2ChecknumberIndex());
  assert.equal(native.v62IatLuaType() >>> 0, luaEngineV62IatLuaType());
  assert.equal(native.v62IatLuaTouserdata() >>> 0, luaEngineV62IatLuaTouserdata());
  assert.equal(native.v62IatLuaCheckinteger() >>> 0, luaEngineV62IatLuaCheckinteger());
  assert.equal(native.v62IatLuaChecknumber() >>> 0, luaEngineV62IatLuaChecknumber());
  assert.equal(native.v62ReturnValue() | 0, luaEngineV62ReturnValue());
  // Install sites.
  assert.equal(native.v62InstallVa() >>> 0, luaEngineV62InstallVa());
  assert.equal(native.v62InstallLiteralVa() >>> 0, luaEngineV62InstallLiteralVa());
  assert.equal(native.v62InstallRealFnVa() >>> 0, luaEngineV62InstallRealFnVa());
  assert.equal(native.v62InstallNameVa() >>> 0, luaEngineV62InstallNameVa());
  assert.equal(native.v62InstallCallerVa() >>> 0, luaEngineV62InstallCallerVa());
  // WIDE drive (uint32_t discipline — full-word obj gate + full-word
  // int lane, RAW values; the Wasm ABI does not narrow i32 arguments,
  // so pre-masking would hide defects). No byte-gated law in this body
  // (ret 0 unconditionally), so no return-gate function exists.
  const wide = [
    0x00000000, 0x00000001, 0x000000ff, 0x00000100, 0x000001ff,
    0x0000ffff, 0x00010000, 0x7fffffff, 0x80000000, 0xffffff00,
    0xfffffffe, 0xffffffff,
  ];
  for (const value of wide) {
    assert.equal(native.v62ObjectResolve(value, 0x1234) >>> 0,
      luaEngineV62ObjectResolve(value, 0x1234), `obj ${value}`);
    assert.equal(native.v62IntWord(value) >>> 0,
      luaEngineV62IntWord(value), `int ${value}`);
  }
  // WIDE invariants: FULL WORD survives both laws (`test eax,eax`
  // @0x8b98c7 + `push eax` @0x8b993c).
  assert.equal(native.v62ObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.equal(native.v62IntWord(0x100) >>> 0, 0x100);
  assert.equal(native.v62IntWord(0xffffffff) >>> 0, 0xffffffff);
});

