test("ABI v62 wrapper mutants: six translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce; the
   * permanent tripwire is the assert.equal/notEqual pair + explicit PE
   * truth. (Applied-and-restored sha256-identical runs recorded in
   * lua-v62-8b98b0 NOTES.) */
  const native = loadExports();
  assert.equal(native.abi() | 0, 103);
  // M1: object_resolve type gate -> byte mask (0x100 -> 0). PE `test
  // eax,eax` @0x8b98c7 is FULL-WORD.
  assert.equal(native.v62ObjectResolve(0x100, 0x1234) >>> 0, 0x1234);
  assert.notEqual(native.v62ObjectResolve(0x100, 0x1234) >>> 0, 0x00);
  assert.equal(luaEngineV62ObjectResolve(0x100, 0x1234), 0x1234);
  // M2: int_word -> byte mask (0x100 -> 0). PE `push eax` @0x8b993c
  // keeps the FULL checkinteger word.
  assert.equal(native.v62IntWord(0x100) >>> 0, 0x100);
  assert.notEqual(native.v62IntWord(0x100) >>> 0, 0x00);
  assert.equal(luaEngineV62IntWord(0x100), 0x100);
  // M3: key folded to 0xc82a13 (the v57 MakeShockwave band). PE push
  // 0xc82a16 @0x8b98d2 != push 0xc82a13 @0x8b94c5.
  assert.equal(native.v62Key() >>> 0, 0x00c82a16);
  assert.notEqual(native.v62Key() >>> 0, 0x00c82a13);
  assert.equal(luaEngineV62Key(), 0x00c82a16);
  assert.notEqual(luaEngineV62Key(), 0x00c82a13);
  // M4: body bytes folded to the v61 body (0x98 -> 0x80). PE ret
  // @0x8b9948 - VA 0x8b98b0 = 0x98.
  assert.equal(native.v62BodyBytes() >>> 0, 0x98);
  assert.notEqual(native.v62BodyBytes() >>> 0, 0x80);
  assert.equal(luaEngineV62BodyBytes(), 0x98);
  assert.notEqual(luaEngineV62BodyBytes(), 0x80);
  // M5: arg2 checknumber index folded to arg1 (0x04 -> 0x03). PE
  // `push 4` @0x8b98f8 before the FIRST checknumber call @0x8b98fd.
  assert.equal(native.v62Arg2ChecknumberIndex() >>> 0, 0x04);
  assert.notEqual(native.v62Arg2ChecknumberIndex() >>> 0, 0x03);
  assert.equal(luaEngineV62Arg2ChecknumberIndex(), 0x04);
  assert.notEqual(luaEngineV62Arg2ChecknumberIndex(), 0x03);
  // M6: install real_fn folded to the v61 real_fn (0x92e620 ->
  // 0x92e560). PE `mov dword ptr [eax], 0x92e620` @0x895648 inside
  // installer 0x895630 is the immediate.
  assert.equal(native.v62InstallRealFnVa() >>> 0, 0x0092e620);
  assert.notEqual(native.v62InstallRealFnVa() >>> 0, 0x0092e560);
  assert.equal(luaEngineV62InstallRealFnVa(), 0x0092e620);
  assert.notEqual(luaEngineV62InstallRealFnVa(), 0x0092e560);
});

test("JS oracle: ABI v63 Lua-registered getter bodies 0x85e370 + 0x85e380", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed from the fresh capstone TRUE bodies
   * + the registration run (lua-v62-getters NOTES) — NOT derived from the
   * model or C++:
   *   0x85e370: 8b81d8690200 mov eax,[ecx+0x269d8]
   *             2b81d4690200 sub eax,[ecx+0x269d4]
   *             c1f803       sar eax,3
   *             c3           ret
   *   0x85e380: 8d8108650200 lea eax,[ecx+0x26508]
   *             c3           ret
   * Both ret 0 thiscall getters; 0 E8 / 0 indirect / 0 mem-stores; zero
   * rel32 callers image-wide (reachability = the Lua closure registration
   * only). */
  // Body geometry.
  assert.equal(luaEngineV63NumBossesVa(), 0x0085e370);
  assert.equal(luaEngineV63NumBossesRetVa(), 0x0085e37f);
  assert.equal(luaEngineV63NumBossesBodyBytes(), 0x0f);
  assert.equal(luaEngineV63NumBossesInsnCount(), 4);
  assert.equal(luaEngineV63NumBossesHeadOff(), 0x269d8);
  assert.equal(luaEngineV63NumBossesBaseOff(), 0x269d4);
  assert.equal(luaEngineV63NumBossesStrideShift(), 3);
  assert.equal(luaEngineV63ShakeCountdownVa(), 0x0085e380);
  assert.equal(luaEngineV63ShakeCountdownRetVa(), 0x0085e386);
  assert.equal(luaEngineV63ShakeCountdownBodyBytes(), 0x06);
  assert.equal(luaEngineV63ShakeCountdownInsnCount(), 2);
  assert.equal(luaEngineV63ShakeCountdownFieldOff(), 0x26508);
  // Registration / install pins (push immediates + installer fills).
  assert.equal(luaEngineV63NumBossesInstallHelperVa(), 0x00894bc0);
  assert.equal(luaEngineV63NumBossesInstallFillVa(), 0x00894bdb);
  assert.equal(luaEngineV63NumBossesInstallLiteralVa(), 0x0086d81f);
  assert.equal(luaEngineV63NumBossesInstallRealFnVa(), 0x0085e370);
  assert.equal(luaEngineV63NumBossesInstallNameVa(), 0x00b74950);
  assert.equal(luaEngineV63NumBossesInstallTrampolineVa(), 0x008b8e80);
  assert.equal(luaEngineV63NumBossesInstallCallerVa(), 0x0086d81e);
  assert.equal(luaEngineV63NumBossesInstallCallVa(), 0x0086d82a);
  assert.equal(luaEngineV63ShakeCountdownInstallHelperVa(), 0x00894e00);
  assert.equal(luaEngineV63ShakeCountdownInstallFillVa(), 0x00894e26);
  assert.equal(luaEngineV63ShakeCountdownInstallLiteralVa(), 0x0086d8ac);
  assert.equal(luaEngineV63ShakeCountdownInstallRealFnVa(), 0x0085e380);
  assert.equal(luaEngineV63ShakeCountdownInstallNameVa(), 0x00b74a04);
  assert.equal(luaEngineV63ShakeCountdownInstallTrampolineVa(), 0x008b8f70);
  assert.equal(luaEngineV63ShakeCountdownInstallCallerVa(), 0x0086d8ab);
  assert.equal(luaEngineV63ShakeCountdownInstallCallVa(), 0x0086d8b7);
  // SAR-3 law, PE-truth table computed from raw x86 semantics (32-bit wrap
  // sub + ARITHMETIC shift right by 3 — floor /8):
  //   (0,9) -> -2 = 0xfffffffe, NOT C-truncating -1; 0x80000000 ->
  //   0xf0000000, NOT logical >>> 0x10000000.
  const truth = [
    [0x00000008, 0x00000010, 0xffffffff],
    [0x00000000, 0x00000009, 0xfffffffe],
    [0x00000010, 0x00000000, 0x00000002],
    [0x7fffffff, 0x80000000, 0xffffffff],
    [0x80000000, 0x7fffffff, 0x00000000],
    [0xfffffff7, 0x00000000, 0xfffffffe],
    [0x10000000, 0x00000000, 0x02000000],
    [0xffffffe0, 0x00000000, 0xfffffffc],
    [0x0000000c, 0x00000000, 0x00000001],
    [0x00000007, 0x00000000, 0x00000000],
    [0xffffffff, 0xfffffff8, 0x00000000],
    [0xfffffff8, 0xffffffff, 0xffffffff],
    [0x00000000, 0x80000000, 0xf0000000],
    [0x80000000, 0x00000000, 0xf0000000],
    [0x00000100, 0x00000000, 0x00000020],
    [0xffffffff, 0x00000000, 0xffffffff],
  ];
  for (const [head, base, want] of truth) {
    assert.equal(luaEngineV63NumBossesCount(head, base), want,
      `num_bosses(0x${head.toString(16)}, 0x${base.toString(16)})`);
  }
  // LEA identity: this + 0x26508, u32 wrap.
  const leaTruth = [
    [0x00000000, 0x00026508],
    [0x00026508, 0x0004ca10],
    [0xffffffff, 0x00026507],
    [0x12345678, 0x1236bb80],
    [0x80000000, 0x80026508],
    [0x7fffffff, 0x80026507],
    [0xdeadbeef, 0xdeb023f7],
    [0x00000001, 0x00026509],
  ];
  for (const [base, want] of leaTruth) {
    assert.equal(luaEngineV63ShakeCountdownPtr(base), want,
      `shake_ptr(0x${base.toString(16)})`);
  }
  // WIDE fixed drive (<=500 draws total for the wave): 64 head values x 2
  // base values for the sar law + 64 values for the lea law, cross-checked
  // against an inline independent implementation.
  const wide = [];
  for (let i = 0; i < 64; i += 1) {
    wide.push((i * 0x04030201 + 0x10203040) >>> 0);
  }
  for (const h of wide) {
    for (const b of [0, 0xffffffff]) {
      const s = (h - b) | 0;
      const want = (s >> 3) >>> 0;
      assert.equal(luaEngineV63NumBossesCount(h, b), want,
        `wide num_bosses(0x${h.toString(16)}, 0x${b.toString(16)})`);
    }
  }
  for (const p of wide) {
    assert.equal(luaEngineV63ShakeCountdownPtr(p), (p + 0x26508) >>> 0,
      `wide shake_ptr(0x${p.toString(16)})`);
  }
});

