test("ABI v65 wrapper mutants: nine translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce; the
   * permanent tripwire is the assert.equal/notEqual pair + explicit PE
   * truth. (Applied-and-restored sha256-identical runs recorded in
   * lua-v65-lit2 NOTES. No wasm this wave — mutants are exercised on
   * the model + header, which the oracle and header-pin tests observe
   * directly.) */
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  // M1: object_resolve type gate -> byte mask (0x100 -> 0). PE `test
  // eax,eax` @0x8b9a07 is FULL-WORD.
  assert.equal(luaEngineV65ObjectResolve(0x100, 0x1234), 0x1234);
  assert.notEqual(luaEngineV65ObjectResolve(0x100, 0x1234), 0x00);
  // M2: int_word -> byte mask (0x100 -> 0). PE `push eax` @0x8b9a65
  // keeps the FULL checkinteger word.
  assert.equal(luaEngineV65IntWord(0x100), 0x100);
  assert.notEqual(luaEngineV65IntWord(0x100), 0x00);
  // M3: key folded to 0xc82a16 (the v62 SetAmbientSound class). PE push
  // 0xc82a19 @0x8b9a12 != push 0xc82a16 @0x8b98d2 — MusicManager key.
  assert.equal(luaEngineV65Key(), 0x00c82a19);
  assert.notEqual(luaEngineV65Key(), 0x00c82a16);
  // M4: body bytes folded to the audit end (0x81 -> 0x82). PE ret
  // @0x8b9a71 - VA 0x8b99f0 = 0x81 (0x8b9a72 is the int3 after ret).
  assert.equal(luaEngineV65BodyBytes(), 0x81);
  assert.notEqual(luaEngineV65BodyBytes(), 0x82);
  // M5: insn count folded to the v64 body (48 -> 50). PE 0x8b99f0..ret
  // @0x8b9a71 = 48 capstone TRUE insns (0x8b9950's 50 insns are the
  // v64 GetAmbientSoundVolume body).
  assert.equal(luaEngineV65InsnCount(), 48);
  assert.notEqual(luaEngineV65InsnCount(), 50);
  // M6: install A real_fn folded to B's (0x7e1d50 -> 0x7e1e70). PE
  // `mov dword ptr [eax], 0x7e1d50` @0x895728 inside installer A.
  assert.equal(luaEngineV65InstallARealFnVa(), 0x007e1d50);
  assert.notEqual(luaEngineV65InstallARealFnVa(), 0x007e1e70);
  // M7: install B name folded to A's (0xb74c50 -> 0xb70498). PE
  // `push 0xb74c50` @0x89579d != `push 0xb70498` @0x89573d — "Crossfade"
  // vs "Play".
  assert.equal(luaEngineV65InstallBNameVa(), 0x00b74c50);
  assert.notEqual(luaEngineV65InstallBNameVa(), 0x00b70498);
  // M8: install count folded to 1 (lose the DOUBLE-literal law). PE:
  // exactly TWO image-wide 32-bit LE literals of 0x8b99f0 (@0x895723 +
  // @0x895783 — whole-.text scan).
  assert.equal(luaEngineV65InstallCount(), 2);
  assert.notEqual(luaEngineV65InstallCount(), 1);
  // M9: arg1 checknumber index folded to v62's arg2 (0x03 -> 0x04). PE
  // `push 3` @0x8b9a38 before the FIRST checknumber call @0x8b9a3d.
  assert.equal(luaEngineV65Arg1ChecknumberIndex(), 0x03);
  assert.notEqual(luaEngineV65Arg1ChecknumberIndex(), 0x04);
});

test("JS oracle: ABI v66 wrapper 0x8b9a80 (MusicManager Fadein — int + TWO float lanes, ret 0)", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed branch-by-branch from the fresh
   * capstone TRUE body (0x8b9a80..0x8b9b18) — NOT derived from the
   * model or C++.
   *
   * 0x8b9a80 (54 capstone TRUE insns, ret @0x8b9b18, body 0x98 =
   * RET_VA - VA): SIMPLE ebp frame (`push ebp; mov ebp,esp; sub
   * esp,0x14; push esi; push edi; mov edi,[ebp+8]` — v62-shaped; v65's
   * L=esi is NOT this body: **L = edi = [ebp+8]**); obj1 lives in the
   * [ebp-4] SPILL SLOT (mem-stores 2, both @[ebp-4]; ebp-relative ->
   * esp-shift immune).
   * lua_type(L,1) @0xb18400 @0x8b9a8e, add esp,8, FULL-WORD test
   * @0x8b9a97; nil -> obj1=0 @[ebp-4] + jmp @0x8b9abc; else push 0
   * (flags); push KEY 0xc82a19 @0x8b9aa2 (MusicManager — the v65 key
   * band); edx=1; ecx=edi; call 0x85c590 @0x8b9aae; obj=[eax+4]
   * @0x8b9ab6 -> [ebp-4] @0x8b9ab9. touserdata(L, 0xfff0b9d7)
   * @0xb183b0 @0x8b9ac2 -> esi (mov esi,eax @0x8b9acb BETWEEN the next
   * call's arg pushes — NO add esp,8, v56/v57/v59 lesson); arg2 = num4
   * = luaL_checknumber(L,4) @0xb18324 @0x8b9acd -> x87 -> `fstp dword
   * ptr [ebp-0x10]` @0x8b9ad5 (float32 lane); arg1 = num3 =
   * luaL_checknumber(L,3) @0xb18324 @0x8b9ad9 -> `fstp dword ptr
   * [ebp-8]` @0x8b9ae5; arg0 = int2 = luaL_checkinteger(L,2) @0xb183f4
   * @0x8b9aeb -> eax. EIGHT dwords, ONE fused add esp,0x18 @0x8b9af6
   * cleans SIX — the TWO dead dwords (0xfff0b9d7 + first edi L copy)
   * stay at [esp+4]/[esp]. ESP-TRACKING (v66 lesson): the TWO f32
   * lanes land via movss [esp+4],xmm0 @0x8b9afc (num4) + movss
   * [esp],xmm0 @0x8b9b07 (num3) — dead-slot overwrites, the v62
   * 3-arg lesson extended to TWO lanes; this = obj1 = [ebp-4] into
   * ECX @0x8b9af9 (after cleanup); `push eax` @0x8b9b0c = int2 FULL
   * WORD; real_fn = [esi] (ud[0], FN_OFF 0) @0x8b9b0d AFTER all pushes
   * (register-held esi); `call eax` @0x8b9b0f. Final stack:
   * [esp+0]=int2, [esp+4]=B(num3 f32), [esp+8]=A(num4 f32),
   * [esp+0xc]=junk (saved edi slot) — real_fn 0x7e2080 `ret 0xc`
   * consumes exactly 3 dwords. xor eax,eax @0x8b9b12 -> ret 0 Lua
   * values (NO byte-gated lane — no pushboolean; v61's byte-gated
   * body is NOT this body); ret @0x8b9b18. */
  // Body records.
  assert.equal(LUA_V66_VA, 0x008b9a80);
  assert.equal(LUA_V66_RET_VA, 0x008b9b18);
  assert.equal(LUA_V66_BODY_BYTES, 0x98);
  assert.equal(LUA_V66_INSNS, 54);
  assert.equal(luaEngineV66Va(), 0x008b9a80);
  assert.equal(luaEngineV66RetVa(), 0x008b9b18);
  assert.equal(luaEngineV66BodyBytes(), 0x98);
  assert.equal(luaEngineV66InsnCount(), 54);
  // Shared resolve/gate law constants.
  assert.equal(LUA_V66_CHECK_FLAGS, 0);
  assert.equal(LUA_V66_CHECK_EDX, 1);
  assert.equal(LUA_V66_TYPE_INDEX, 0x01);
  assert.equal(LUA_V66_OBJECT_FIELD_OFF, 0x04);
  assert.equal(LUA_V66_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  assert.equal(LUA_V66_FN_OFF, 0x00);
  assert.equal(luaEngineV66CheckFlags(), 0);
  assert.equal(luaEngineV66CheckEdx(), 1);
  assert.equal(luaEngineV66TypeIndex(), 0x01);
  assert.equal(luaEngineV66ObjectFieldOff(), 0x04);
  assert.equal(luaEngineV66TouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineV66FnOff(), 0x00);
  // Key: MusicManager class 0xc82a19 (push @0x8b9aa2) — the v65 key
  // band (NOT v62's 0xc82a16, different class).
  assert.equal(LUA_V66_KEY, 0x00c82a19);
  assert.equal(luaEngineV66Key(), 0x00c82a19);
  assert.equal(LUA_V66_KEY, LUA_V65_KEY);
  // Arg lanes: arg0 = checkinteger idx 2 (push 2 @0x8b9ae2), arg1 =
  // checknumber idx 3 (push 3 @0x8b9ad3), arg2 = checknumber idx 4
  // (push 4 @0x8b9ac8) — the SECOND 3-arg body of the band (v62 =
  // int2+num3+num4 with key 0xc82a16) and the SECOND with TWO float
  // lanes.
  assert.equal(LUA_V66_ARG0_CHECKINTEGER_INDEX_U32, 0x02);
  assert.equal(LUA_V66_ARG1_CHECKNUMBER_INDEX_U32, 0x03);
  assert.equal(LUA_V66_ARG2_CHECKNUMBER_INDEX_U32, 0x04);
  assert.equal(luaEngineV66Arg0CheckintegerIndex(), 0x02);
  assert.equal(luaEngineV66Arg1ChecknumberIndex(), 0x03);
  assert.equal(luaEngineV66Arg2ChecknumberIndex(), 0x04);
  // IAT pins (host, transcribed): type + touserdata + checkinteger +
  // checknumber (0xb18324 appears TWICE — the TWO checknumber calls
  // @0x8b9acd + @0x8b9ad9, one IAT slot).
  assert.equal(LUA_V66_IAT_LUA_TYPE, 0x00b18400);
  assert.equal(LUA_V66_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(LUA_V66_IAT_LUA_CHECKINTEGER, 0x00b183f4);
  assert.equal(LUA_V66_IAT_LUA_CHECKNUMBER, 0x00b18324);
  assert.equal(luaEngineV66IatLuaType(), 0x00b18400);
  assert.equal(luaEngineV66IatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineV66IatLuaCheckinteger(), 0x00b183f4);
  assert.equal(luaEngineV66IatLuaChecknumber(), 0x00b18324);
  // Return: unconditional xor eax,eax @0x8b9b12 -> ret 0 Lua values
  // (NO pushboolean, NO byte gate).
  assert.equal(LUA_V66_RETURN_VALUE, 0);
  assert.equal(luaEngineV66ReturnValue(), 0);
  // Laws, oracle side, on unmasked wide values.
  assert.equal(luaEngineV66ObjectResolve(0, 0x1234), 0);
  assert.equal(luaEngineV66ObjectResolve(0x100, 0x1234), 0x1234);
  assert.equal(luaEngineV66ObjectResolve(0xffffffff, 0x1234), 0x1234);
  assert.equal(luaEngineV66IntWord(0x100), 0x100);
  assert.equal(luaEngineV66IntWord(0x10000), 0x10000);
  assert.equal(luaEngineV66IntWord(0xffffffff), 0xffffffff);
  // SINGLE-literal install (lit=1 — the unit's namesake): ONE
  // IMMEDIATE-held SINGLE ret-8 installer 0x8957d0 pushes the wrapper
  // with its OWN name/real_fn pair as body immediates: literal dword
  // @0x8957e3 = push 0x8b9a80 @0x8957e2; real_fn 0x7e2080 @0x8957e8/
  // imm @0x8957eb (= ZHL Music::Fadein(unsigned int, float, float),
  // HOST); name 0xb74b30 @0x8957fd = "Fadein" (.rdata cstr — SHARED
  // string with the v56 vec-band install @0x895190, DIFFERENT
  // site/class); caller @0x86db91 (pushed dwords DEAD). ret 8
  // @0x895826.
  assert.equal(LUA_V66_INSTALL_COUNT, 1);
  assert.equal(luaEngineV66InstallCount(), 1);
  assert.equal(LUA_V66_INSTALL_VA, 0x008957d0);
  assert.equal(LUA_V66_INSTALL_RET_VA, 0x00895826);
  assert.equal(LUA_V66_INSTALL_LITERAL_VA, 0x008957e3);
  assert.equal(LUA_V66_INSTALL_REAL_FN_VA, 0x007e2080);
  assert.equal(LUA_V66_INSTALL_NAME_VA, 0x00b74b30); /* "Fadein" */
  assert.equal(LUA_V66_INSTALL_CALLER_VA, 0x0086db91);
  assert.equal(luaEngineV66InstallVa(), 0x008957d0);
  assert.equal(luaEngineV66InstallRetVa(), 0x00895826);
  assert.equal(luaEngineV66InstallLiteralVa(), 0x008957e3);
  assert.equal(luaEngineV66InstallRealFnVa(), 0x007e2080);
  assert.equal(luaEngineV66InstallNameVa(), 0x00b74b30);
  assert.equal(luaEngineV66InstallCallerVa(), 0x0086db91);
  // WIDE fixed drive (<=500 draws total for the wave): 64 drawn values
  // x 2 law checks, cross-checked against inline independent
  // implementations.
  const wide = [];
  for (let i = 0; i < 64; i += 1) {
    wide.push((i * 0x04030201 + 0x10203040) >>> 0);
  }
  for (const v of wide) {
    assert.equal(luaEngineV66ObjectResolve(v, 0x1234), v !== 0 ? 0x1234 : 0,
      `wide obj(0x${v.toString(16)})`);
    assert.equal(luaEngineV66IntWord(v), v, `wide int(0x${v.toString(16)})`);
  }
});

