  assert.equal(LUA_V67_ISLAYERENABLED_RETURN_VALUE, 1);
  assert.equal(luaEngineV67IsLayerEnabledReturnValue(), 1);
  assert.equal(luaEngineV67IsLayerEnabledObjectResolve(0, 0x1234), 0);
  assert.equal(luaEngineV67IsLayerEnabledObjectResolve(0x100, 0x1234), 0x1234);
  assert.equal(luaEngineV67IsLayerEnabledIntWord(0x100), 0x100);
  // Return gate: BYTE test of al (0x100 -> 0 since AL = 0x00).
