  assert.equal(luaEngineV67IsLayerEnabledReturnGate(1), 1);
  assert.equal(luaEngineV67IsLayerEnabledReturnGate(0xff), 1);
  assert.equal(luaEngineV67IsLayerEnabledReturnGate(0x100), 0);
  assert.equal(luaEngineV67IsLayerEnabledReturnGate(0xffffffff), 1);
