  assert.equal(luaEngineV67IsLayerEnabledInstallCallerVa(), 0x0086dc19);

  /* IsEnabled 0x8b9d80: 39 insns ret @0x8b9de4 body 0x64; SIMPLE
   * ebp; obj1 in EDI; CHKFLAGS 1; NO args; touserdata + add esp,8;
   * real_fn 0x85e430 ret 0; BYTE test al,al / setne cl
   * @0x8b9dcc/@0x8b9dce; lua_pushboolean @0xb183ec; ret 1. */
