  assert.equal(luaEngineV67IsEnabledReturnValue(), 1);
  assert.equal(luaEngineV67IsEnabledObjectResolve(0, 0x1234), 0);
  assert.equal(luaEngineV67IsEnabledObjectResolve(0x100, 0x1234), 0x1234);
  assert.equal(luaEngineV67IsEnabledReturnGate(0), 0);
