  assert.equal(LUA_V67_VOLUMESLIDE_RETURN_VALUE, 0);
  assert.equal(luaEngineV67VolumeSlideReturnValue(), 0);
  assert.equal(luaEngineV67VolumeSlideObjectResolve(0, 0x1234), 0);
  assert.equal(luaEngineV67VolumeSlideObjectResolve(0x100, 0x1234), 0x1234);
  assert.equal(LUA_V67_VOLUMESLIDE_INSTALL_VA, 0x00895b10);
  assert.equal(LUA_V67_VOLUMESLIDE_INSTALL_LITERAL_VA, 0x00895b23);
  assert.equal(LUA_V67_VOLUMESLIDE_INSTALL_REAL_FN_VA, 0x007e2510);
  assert.equal(LUA_V67_VOLUMESLIDE_INSTALL_NAME_VA, 0x00b74cbc); /* "VolumeSlide" */
  assert.equal(LUA_V67_VOLUMESLIDE_INSTALL_CALLER_VA, 0x0086dc7f);
  assert.equal(luaEngineV67VolumeSlideInstallLiteralVa(), 0x00895b23);
  assert.equal(luaEngineV67VolumeSlideInstallNameVa(), 0x00b74cbc);
  assert.equal(luaEngineV67VolumeSlideInstallCallerVa(), 0x0086dc7f);

  /* GetCurrentMusicID 0x8b9e80: 35 insns ret @0x8b9edb body 0x5b;
   * SIMPLE ebp; obj1 in EDI; CHKFLAGS 1; NO args; touserdata + add
   * esp,8; real_fn 0x7e1780 ret 0; mov edx,eax (result) + mov
   * ecx,esi (L) + call 0x85bfd0 (closure push-i32-sext — v55 pusher
   * ROW 3 LANDED, edge pin); mov eax,1 -> ret 1. (2nd site @0x86dcb2
   * GetQueuedMusicID 0x7e1790/0xb74d40 — census.) */
