  assert.equal(LUA_V67_GETCURRENTMUSICID_CHECK_FLAGS, 1);
  assert.equal(LUA_V67_GETCURRENTMUSICID_SEXT_PUSH_VA, 0x0085bfd0);
  assert.equal(luaEngineV67GetCurrentMusicIdSextPushVa(), 0x0085bfd0);
  assert.equal(LUA_V67_GETCURRENTMUSICID_RETURN_VALUE, 1);
