  assert.equal(LUA_V67_GETCURRENTMUSICID_INSTALL_REAL_FN_VA, 0x007e1780);
  assert.equal(LUA_V67_GETCURRENTMUSICID_INSTALL_NAME_VA, 0x00b74c9c); /* "GetCurrentMusicID" */
