test("ABI v67 wrapper mutants: six translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce; the
   * permanent tripwire is the assert.equal/notEqual pair + explicit PE
   * truth. (Applied-and-restored sha256-identical runs recorded in
   * lua-v67-8b9b20 NOTES.) */
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  // M1: Queue gate folded to BYTE mask (0x100 -> 0). PE `test
  // eax,eax` @0x8b9b3a is FULL-WORD.
  assert.equal(luaEngineV67QueueObjectResolve(0x100, 0x1234), 0x1234);
  assert.notEqual(luaEngineV67QueueObjectResolve(0x100, 0x1234), 0x00);
  // M2: Queue int_word -> byte mask (0x100 -> 0). PE `push eax`
  // @0x8b9b7f keeps the FULL checkinteger word.
  assert.equal(luaEngineV67QueueIntWord(0x100), 0x100);
  assert.notEqual(luaEngineV67QueueIntWord(0x100), 0x00);
  // M3: Queue body bytes folded to the v66 Fadein body (0x6b -> 0x98).
  // PE ret @0x8b9b8b - VA 0x8b9b20 = 0x6b.
  assert.equal(luaEngineV67QueueBodyBytes(), 0x6b);
  assert.notEqual(luaEngineV67QueueBodyBytes(), 0x98);
  // M4: EnableLayer bool fold to BYTE mask (0x100 -> 0). PE
  // `test eax,eax; setne byte [esp+0x24]` @0x8b9cc8 is FULL-WORD
  // (v22 normalize) — 0x100 -> 1.
  assert.equal(luaEngineV67EnableLayerBoolWord(0x100), 1);
  assert.notEqual(luaEngineV67EnableLayerBoolWord(0x100), 0);
  // M5: IsEnabled/IsLayerEnabled return gate folded to FULL-WORD
  // normalize (0x100 -> 1). PE `test al,al` @0x8b9dcc/@0x8b9d56 is a
  // BYTE gate — 0x100 has AL=0x00 -> 0.
  assert.equal(luaEngineV67IsEnabledReturnGate(0x100), 0);
  assert.notEqual(luaEngineV67IsEnabledReturnGate(0x100), 1);
  assert.equal(luaEngineV67IsLayerEnabledReturnGate(0x100), 0);
  assert.notEqual(luaEngineV67IsLayerEnabledReturnGate(0x100), 1);
  // M6: Queue literal folded to the v66 Fadein literal (0x895849 ->
  // 0x8957e3). PE push 0x8b9b20 @0x895848 inside installer 0x895830.
  assert.equal(luaEngineV67QueueInstallLiteralVa(), 0x00895849);
  assert.notEqual(luaEngineV67QueueInstallLiteralVa(), 0x008957e3);
});

test("JS oracle: ABI v68 input/callback wrappers 0x897870/0x8978d0/0x89e300", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* Independent PE-truth, transcribed from fresh capstone TRUE bodies —
   * NOT derived from the model/C++. NO lua_type gate, NO 0x85c590 check
   * helper (the fourth-region direct-ud shape).
   *
   * GetButtonValue 0x897870 (35 insns, ret @0x8978c6, body 0x56):
   * ud = lua_touserdata(L,0xfff0b9d7) @0xb183b0 @0x89787f; checkinteger
   * @0xb183f4 x2 (idx 2 @0x897891 -> edi, idx 1 @0x89789a -> eax);
   * real_fn = [ud] (FN_OFF 0) @0x8978a1; call [ebp-4] @0x8978a6 cdecl
   * (checkint1, checkint2) — stack order: push edi @0x89789f (arg2),
   * push eax @0x8978a0 (arg1); cleanup 0x20 @0x8978ac; real_fn FLOAT
   * ret: fstp [ebp-4] @0x8978af + movss xmm1,[ebp-4] @0x8978b2
   * (store-forward F32_SLOT_OFF -4); call 0x85c050 @0x8978b7 = pusher
   * ROW 0 PUSHNUMBER_F32 (edge pin; laws stay the v55 row); eax=1 ret.
   * IsButtonTriggered 0x8978d0 (36, ret @0x897923, body 0x53): same
   * two checkinteger lanes + real_fn cdecl; BYTE-GATED return `test
   * al,al; setne cl` @0x897907/@0x897909 -> lua_pushboolean @0xb183ec
   * @0x897910; ret 1.
   * GetBuiltInCallbackState 0x89e300 (29, ret @0x89e343, body 0x43):
   * ALIGNED ebp (`and esp,0xfffffff8` @0x89e303); ud register-held;
   * checkinteger(L,1) @0x89e31c; `mov ecx,[esi]` real_fn @0x89e322,
   * `push eax; call ecx` @0x89e324/@0x89e325 (1 cdecl arg); BYTE gate
   * @0x89e329/@0x89e32b -> pushboolean @0x89e330; ret 1. */
  // Body records.
  assert.equal(LUA_V68_GETBUTTONVALUE_VA, 0x00897870);
  assert.equal(LUA_V68_GETBUTTONVALUE_RET_VA, 0x008978c6);
  assert.equal(luaEngineV68GetButtonValueVa(), 0x00897870);
  assert.equal(luaEngineV68GetButtonValueRetVa(), 0x008978c6);
  assert.equal(luaEngineV68GetButtonValueBodyBytes(), 0x56);
  assert.equal(luaEngineV68GetButtonValueInsnCount(), 35);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_VA, 0x008978d0);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_RET_VA, 0x00897923);
  assert.equal(luaEngineV68IsButtonTriggeredBodyBytes(), 0x53);
  assert.equal(luaEngineV68IsButtonTriggeredInsnCount(), 36);
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_VA, 0x0089e300);
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_RET_VA, 0x0089e343);
  assert.equal(luaEngineV68GetBuiltInCallbackStateBodyBytes(), 0x43);
  assert.equal(luaEngineV68GetBuiltInCallbackStateInsnCount(), 29);
  // Shared direct-ud laws.
  assert.equal(LUA_V68_GETBUTTONVALUE_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  assert.equal(LUA_V68_GETBUTTONVALUE_FN_OFF, 0x00);
  assert.equal(luaEngineV68GetButtonValueTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineV68GetButtonValueFnOff(), 0x00);
  // Arg lanes.
  assert.equal(LUA_V68_GETBUTTONVALUE_ARG0_CHECKINTEGER_INDEX_U32, 0x01);
  assert.equal(LUA_V68_GETBUTTONVALUE_ARG1_CHECKINTEGER_INDEX_U32, 0x02);
  assert.equal(luaEngineV68GetButtonValueArg0CheckintegerIndex(), 0x01);
  assert.equal(luaEngineV68GetButtonValueArg1CheckintegerIndex(), 0x02);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_ARG0_CHECKINTEGER_INDEX_U32, 0x01);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_ARG1_CHECKINTEGER_INDEX_U32, 0x02);
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_ARG0_CHECKINTEGER_INDEX_U32, 0x01);
  // IAT pins.
  assert.equal(LUA_V68_GETBUTTONVALUE_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(LUA_V68_GETBUTTONVALUE_IAT_LUA_CHECKINTEGER, 0x00b183f4);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_IAT_LUA_PUSHBOOLEAN, 0x00b183ec);
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_IAT_LUA_PUSHBOOLEAN, 0x00b183ec);
  assert.equal(luaEngineV68GetButtonValueIatLuaTouserdata(), 0x00b183b0);
  assert.equal(luaEngineV68GetButtonValueIatLuaCheckinteger(), 0x00b183f4);
  assert.equal(luaEngineV68IsButtonTriggeredIatLuaPushboolean(), 0x00b183ec);
  assert.equal(luaEngineV68GetBuiltInCallbackStateIatLuaPushboolean(), 0x00b183ec);
  // GetButtonValue float return lane + pusher edge.
  assert.equal(LUA_V68_GETBUTTONVALUE_F32_SLOT_OFF_U32, 0xffffffbc); /* ebp-4 */
  assert.equal(LUA_V68_GETBUTTONVALUE_NUMBER_PUSH_VA, 0x0085c050); /* pusher ROW 0 */
  assert.equal(luaEngineV68GetButtonValueF32SlotOff(), 0xffffffbc);
  assert.equal(luaEngineV68GetButtonValueNumberPushVa(), 0x0085c050);
  // GetBuiltInCallbackState aligned frame.
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_STACK_ALIGN_MASK, 0xfffffff8);
  assert.equal(luaEngineV68GetBuiltInCallbackStateStackAlignMask(), 0xfffffff8);
  // Returns.
  assert.equal(LUA_V68_GETBUTTONVALUE_RETURN_VALUE, 1);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_RETURN_VALUE, 1);
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_RETURN_VALUE, 1);
  assert.equal(luaEngineV68GetButtonValueReturnValue(), 1);
  assert.equal(luaEngineV68IsButtonTriggeredReturnValue(), 1);
  assert.equal(luaEngineV68GetBuiltInCallbackStateReturnValue(), 1);
  // BYTE-gate laws on unmasked wide values (0x100 has AL=0x00 -> 0).
  assert.equal(luaEngineV68IsButtonTriggeredReturnGate(0), 0);
  assert.equal(luaEngineV68IsButtonTriggeredReturnGate(1), 1);
  assert.equal(luaEngineV68IsButtonTriggeredReturnGate(0x100), 0);
  assert.equal(luaEngineV68IsButtonTriggeredReturnGate(0x101), 1);
  assert.equal(luaEngineV68IsButtonTriggeredReturnGate(0xff), 1);
  assert.equal(luaEngineV68IsButtonTriggeredReturnGate(0xffffffff), 1);
  assert.equal(luaEngineV68GetBuiltInCallbackStateReturnGate(0x100), 0);
  assert.equal(luaEngineV68GetBuiltInCallbackStateReturnGate(0x101), 1);
  // Installs (primary pair per wrapper; extras are census rows).
  assert.equal(LUA_V68_GETBUTTONVALUE_INSTALL_COUNT, 1);
  assert.equal(LUA_V68_GETBUTTONVALUE_INSTALL_VA, 0x00896750);
  assert.equal(LUA_V68_GETBUTTONVALUE_INSTALL_RET_VA, 0x008967a9);
  assert.equal(LUA_V68_GETBUTTONVALUE_INSTALL_LITERAL_VA, 0x00896767);
  assert.equal(LUA_V68_GETBUTTONVALUE_INSTALL_REAL_FN_VA, 0x0086fcd0);
  assert.equal(LUA_V68_GETBUTTONVALUE_INSTALL_NAME_VA, 0x00b75074); /* "GetButtonValue" */
  assert.equal(LUA_V68_GETBUTTONVALUE_INSTALL_CALLER_VA, 0x0086e137);
  assert.equal(luaEngineV68GetButtonValueInstallLiteralVa(), 0x00896767);
  assert.equal(luaEngineV68GetButtonValueInstallRealFnVa(), 0x0086fcd0);
  assert.equal(luaEngineV68GetButtonValueInstallNameVa(), 0x00b75074);
  assert.equal(luaEngineV68GetButtonValueInstallCallerVa(), 0x0086e137);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_INSTALL_LITERAL_VA, 0x00896707);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_INSTALL_REAL_FN_VA, 0x0086fc70);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_INSTALL_NAME_VA, 0x00b75098);
  assert.equal(LUA_V68_ISBUTTONTRIGGERED_INSTALL_CALLER_VA, 0x0086e115);
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_INSTALL_LITERAL_VA, 0x00896467);
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_INSTALL_REAL_FN_VA, 0x0086f4f0);
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_INSTALL_NAME_VA, 0x00b74f20);
  assert.equal(LUA_V68_GETBUILTINCALLBACKSTATE_INSTALL_CALLER_VA, 0x0086dfef);
  // WIDE fixed drive (family budget budget-aware): 15 values x law fns.
  const wide = [0, 1, 0x7f, 0x80, 0xff, 0x100, 0x1ff, 0x7fff, 0x8000,
    0xffff, 0x10000, 0x7fffffff, 0x80000000, 0xfffffffe, 0xffffffff];
  for (const v of wide) {
    assert.equal(luaEngineV68IsButtonTriggeredReturnGate(v),
      (v & 0xff) !== 0 ? 1 : 0, "ibt wide(0x" + v.toString(16) + ")");
    assert.equal(luaEngineV68GetBuiltInCallbackStateReturnGate(v),
      (v & 0xff) !== 0 ? 1 : 0, "gbcs wide(0x" + v.toString(16) + ")");
  }
});

test("JS oracle: ABI v68 class-singleton closures 0x898d90/0x898e00/0x898e70 + RandomVector 0x898ee0", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* MusicManager 0x898d90 (32, ret @0x898de8, body 0x58): ud =
   * touserdata; real_fn = [ud] @0x898da7; call eax @0x898da9 cdecl 0
   * args -> obj; FULL-WORD null gate `test edi,edi; je` @0x898dad/
   * @0x898daf (skip wrap, still ret 1); newuserdata(L,8) @0xb1839c
   * @0x898db4; ud[0] = 0xb753c8 vtable @0x898dc5; ud[4] = obj
   * @0x898dcb; lua_rawgetp(L, REG 0xfff0b9d8, 0xc82a19) @0xb183bc
   * @0x898dce (pushes the registered class object);
   * lua_setmetatable(L,-2) @0xb18398 @0x898dd7 attaches it to the ud;
   * ret 1. SFXManager 0x898e00 (32, ret @0x898e58): key 0xc82a16,
   * real_fn 0x420af0. Game_0 0x898e70 (32, ret @0x898ec8): key
   * 0xc82a13, real_fn 0x86fc60. RandomVector 0x898ee0 (39, ret
   * @0x898f4b, body 0x6b): real_fn cdecl 1 arg &vec8 (fills lo/hi);
   * newuserdata(L,0x10) @0x898f02; ud[0] = 0xb73574 (v45 Vector tag)
   * @0x898f18; payload self-off +8 @0x898f15 (`lea ecx,[esi+8]`);
   * 8-byte vec -> payload copy @0x898f3c/@0x898f3f; rawgetp(REG,
   * 0xc82980 Vector class key) @0x898f21; setmetatable(-2) @0x898f2a;
   * ret 1. */
  // Body records.
  assert.equal(LUA_V68_MUSICMANAGER_VA, 0x00898d90);
  assert.equal(LUA_V68_MUSICMANAGER_RET_VA, 0x00898de8);
  assert.equal(luaEngineV68MusicManagerBodyBytes(), 0x58);
  assert.equal(luaEngineV68MusicManagerInsnCount(), 32);
  assert.equal(LUA_V68_SFXMANAGER_VA, 0x00898e00);
  assert.equal(LUA_V68_SFXMANAGER_RET_VA, 0x00898e58);
  assert.equal(luaEngineV68SfxManagerBodyBytes(), 0x58);
  assert.equal(luaEngineV68SfxManagerInsnCount(), 32);
  assert.equal(LUA_V68_GAME0_VA, 0x00898e70);
  assert.equal(LUA_V68_GAME0_RET_VA, 0x00898ec8);
  assert.equal(luaEngineV68Game0BodyBytes(), 0x58);
  assert.equal(luaEngineV68Game0InsnCount(), 32);
  assert.equal(LUA_V68_RANDOMVECTOR_VA, 0x00898ee0);
  assert.equal(LUA_V68_RANDOMVECTOR_RET_VA, 0x00898f4b);
  assert.equal(luaEngineV68RandomVectorBodyBytes(), 0x6b);
  assert.equal(luaEngineV68RandomVectorInsnCount(), 39);
  // Shared direct-ud laws.
  assert.equal(LUA_V68_MUSICMANAGER_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  assert.equal(LUA_V68_MUSICMANAGER_FN_OFF, 0x00);
  assert.equal(LUA_V68_RANDOMVECTOR_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  // wrap template constants.
  assert.equal(LUA_V68_MUSICMANAGER_NEWUSERDATA_SIZE, 0x08);
  assert.equal(LUA_V68_MUSICMANAGER_UD_VTABLE_VA, 0x00b753c8);
  assert.equal(LUA_V68_MUSICMANAGER_UD_OBJECT_OFF, 0x04);
  assert.equal(LUA_V68_MUSICMANAGER_RAWGETP_KEY, 0x00c82a19); /* MusicManager class key (v67 KEY) */
  assert.equal(LUA_V68_SFXMANAGER_RAWGETP_KEY, 0x00c82a16);
  assert.equal(LUA_V68_GAME0_RAWGETP_KEY, 0x00c82a13);
  assert.equal(LUA_V68_MUSICMANAGER_REGISTRY_INDEX_U32, 0xfff0b9d8);
  assert.equal(LUA_V68_MUSICMANAGER_SETMETA_INDEX_U32, 0xfffffffe);
  assert.equal(LUA_V68_MUSICMANAGER_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(LUA_V68_MUSICMANAGER_IAT_LUA_NEWUSERDATA, 0x00b1839c);
  assert.equal(LUA_V68_MUSICMANAGER_IAT_LUA_RAWGETP, 0x00b183bc);
  assert.equal(LUA_V68_MUSICMANAGER_IAT_LUA_SETMETATABLE, 0x00b18398);
  assert.equal(luaEngineV68MusicManagerNewuserdataSize(), 0x08);
  assert.equal(luaEngineV68MusicManagerUdVtableVa(), 0x00b753c8);
  assert.equal(luaEngineV68MusicManagerUdObjectOff(), 0x04);
  assert.equal(luaEngineV68MusicManagerRawgetpKey(), 0x00c82a19);
  assert.equal(luaEngineV68MusicManagerRegistryIndex(), 0xfff0b9d8);
  assert.equal(luaEngineV68MusicManagerSetmetaIndex(), 0xfffffffe);
  assert.equal(luaEngineV68MusicManagerIatLuaNewuserdata(), 0x00b1839c);
  assert.equal(luaEngineV68MusicManagerIatLuaRawgetp(), 0x00b183bc);
  assert.equal(luaEngineV68MusicManagerIatLuaSetmetatable(), 0x00b18398);
  assert.equal(LUA_V68_RANDOMVECTOR_NEWUSERDATA_SIZE, 0x10);
  assert.equal(LUA_V68_RANDOMVECTOR_UD_VTABLE_VA, 0x00b73574); /* v45 Vector tag */
  assert.equal(LUA_V68_RANDOMVECTOR_UD_PAYLOAD_OFF, 0x08);
  assert.equal(LUA_V68_RANDOMVECTOR_RAWGETP_KEY, 0x00c82980); /* v45 Vector class key */
  assert.equal(LUA_V68_RANDOMVECTOR_SETMETA_INDEX_U32, 0xfffffffe);
  assert.equal(luaEngineV68RandomVectorNewuserdataSize(), 0x10);
  assert.equal(luaEngineV68RandomVectorUdVtableVa(), 0x00b73574);
  assert.equal(luaEngineV68RandomVectorUdPayloadOff(), 0x08);
  assert.equal(luaEngineV68RandomVectorRawgetpKey(), 0x00c82980);
  assert.equal(luaEngineV68RandomVectorRegistryIndex(), 0xfff0b9d8);
  assert.equal(luaEngineV68RandomVectorSetmetaIndex(), 0xfffffffe);
  assert.equal(luaEngineV68RandomVectorIatLuaNewuserdata(), 0x00b1839c);
  assert.equal(luaEngineV68RandomVectorIatLuaRawgetp(), 0x00b183bc);
  assert.equal(luaEngineV68RandomVectorIatLuaSetmetatable(), 0x00b18398);
  // FULL-WORD null gates: 0x100 -> wrap (never byte-masked).
  assert.equal(luaEngineV68MusicManagerNullGate(0), 0);
  assert.equal(luaEngineV68MusicManagerNullGate(1), 1);
  assert.equal(luaEngineV68MusicManagerNullGate(0x100), 1);
  assert.equal(luaEngineV68MusicManagerNullGate(0xffffffff), 1);
  assert.equal(luaEngineV68SfxManagerNullGate(0x100), 1);
  assert.equal(luaEngineV68Game0NullGate(0x100), 1);
  assert.equal(luaEngineV68Game0NullGate(0), 0);
  // Returns.
  assert.equal(LUA_V68_MUSICMANAGER_RETURN_VALUE, 1);
  assert.equal(LUA_V68_SFXMANAGER_RETURN_VALUE, 1);
  assert.equal(LUA_V68_GAME0_RETURN_VALUE, 1);
  assert.equal(LUA_V68_RANDOMVECTOR_RETURN_VALUE, 1);
  assert.equal(luaEngineV68MusicManagerReturnValue(), 1);
  assert.equal(luaEngineV68RandomVectorReturnValue(), 1);
  // Installs (primary pairs).
  assert.equal(LUA_V68_MUSICMANAGER_INSTALL_LITERAL_VA, 0x00895da1);
  assert.equal(LUA_V68_MUSICMANAGER_INSTALL_REAL_FN_VA, 0x00428cd0);
  assert.equal(LUA_V68_MUSICMANAGER_INSTALL_NAME_VA, 0x00b74c7c); /* "MusicManager" */
  assert.equal(LUA_V68_MUSICMANAGER_INSTALL_CALLER_VA, 0x0086dd52);
  assert.equal(LUA_V68_SFXMANAGER_INSTALL_LITERAL_VA, 0x00895d41);
  assert.equal(LUA_V68_SFXMANAGER_INSTALL_REAL_FN_VA, 0x00420af0);
  assert.equal(LUA_V68_SFXMANAGER_INSTALL_NAME_VA, 0x00b74be4);
  assert.equal(LUA_V68_SFXMANAGER_INSTALL_CALLER_VA, 0x0086dd41);
  assert.equal(LUA_V68_GAME0_INSTALL_LITERAL_VA, 0x00895ce1);
  assert.equal(LUA_V68_GAME0_INSTALL_REAL_FN_VA, 0x0086fc60);
  assert.equal(LUA_V68_GAME0_INSTALL_NAME_VA, 0x00b74d38); /* "Game_0" */
  assert.equal(LUA_V68_GAME0_INSTALL_CALLER_VA, 0x0086dd30);
  assert.equal(LUA_V68_RANDOMVECTOR_INSTALL_LITERAL_VA, 0x00895c87);
  assert.equal(LUA_V68_RANDOMVECTOR_INSTALL_REAL_FN_VA, 0x0067f070);
  assert.equal(LUA_V68_RANDOMVECTOR_INSTALL_NAME_VA, 0x00b74d28);
  assert.equal(LUA_V68_RANDOMVECTOR_INSTALL_CALLER_VA, 0x0086dd1f);
  assert.equal(luaEngineV68MusicManagerInstallLiteralVa(), 0x00895da1);
  assert.equal(luaEngineV68MusicManagerInstallRealFnVa(), 0x00428cd0);
  assert.equal(luaEngineV68MusicManagerInstallNameVa(), 0x00b74c7c);
  assert.equal(luaEngineV68MusicManagerInstallCallerVa(), 0x0086dd52);
  assert.equal(luaEngineV68RandomVectorInstallLiteralVa(), 0x00895c87);
  assert.equal(luaEngineV68RandomVectorInstallRealFnVa(), 0x0067f070);
  assert.equal(luaEngineV68RandomVectorInstallNameVa(), 0x00b74d28);
  assert.equal(luaEngineV68RandomVectorInstallCallerVa(), 0x0086dd1f);
  // WIDE fixed drive: 12 values x 3 null gates.
  const wide = [0, 1, 0x7f, 0x80, 0xff, 0x100, 0x1ff, 0x8000, 0x10000,
    0x7fffffff, 0x80000000, 0xffffffff];
  for (const v of wide) {
    const want = v !== 0 ? 1 : 0;
    assert.equal(luaEngineV68MusicManagerNullGate(v), want, "mm wide(0x" + v.toString(16) + ")");
    assert.equal(luaEngineV68SfxManagerNullGate(v), want, "sfx wide(0x" + v.toString(16) + ")");
    assert.equal(luaEngineV68Game0NullGate(v), want, "game wide(0x" + v.toString(16) + ")");
  }
});

test("JS oracle: ABI v68 GetRoomEntities 0x898490", () => {
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  /* GetRoomEntities 0x898490 (23 insns, ret @0x8984d6, body 0x46): ud
   * = touserdata @0x89849e; lea ecx,[ebp-8]; push ecx @0x8984a4/
   * @0x8984a7 (1 cdecl arg &vec8); real_fn = [ud] @0x8984a8; call eax
   * @0x8984aa — the HOST real_fn 0x86fb20 fills {L, ref} (createtable
   * + luaL_ref inside; reads engine L from [0xc71690]+0x18); cleanup
   * 0xc @0x8984ac; call 0x6a80f0 @0x8984b5 (this=&vec, arg1=L — the
   * shared 18-caller host helper cdq-sign-extends [this+4] and does
   * lua_rawgeti(L,REG,key) @0xb18318, PUSHING the cached entities
   * table; its laws stay HOST, edge pin only); luaL_unref(L=vec.lo,
   * LUA_REGISTRYINDEX 0xfff0b9d8, ref=vec.hi) @0xb1831c @0x8984c5
   * (fresh-ref release); add esp,0xc; eax=1; ret 1. */
  assert.equal(LUA_V68_GETROOMENTITIES_VA, 0x00898490);
  assert.equal(LUA_V68_GETROOMENTITIES_RET_VA, 0x008984d6);
  assert.equal(luaEngineV68GetRoomEntitiesVa(), 0x00898490);
  assert.equal(luaEngineV68GetRoomEntitiesRetVa(), 0x008984d6);
  assert.equal(luaEngineV68GetRoomEntitiesBodyBytes(), 0x46);
  assert.equal(luaEngineV68GetRoomEntitiesInsnCount(), 23);
  assert.equal(LUA_V68_GETROOMENTITIES_TOUSERDATA_INDEX_U32, 0xfff0b9d7);
  assert.equal(LUA_V68_GETROOMENTITIES_FN_OFF, 0x00);
  assert.equal(LUA_V68_GETROOMENTITIES_IAT_LUA_TOUSERDATA, 0x00b183b0);
  assert.equal(luaEngineV68GetRoomEntitiesTouserdataIndex(), 0xfff0b9d7);
  assert.equal(luaEngineV68GetRoomEntitiesFnOff(), 0x00);
  // vec local + unref laws.
  assert.equal(LUA_V68_GETROOMENTITIES_VEC_OFF_LO_U32, 0xfffffff8); /* ebp-8 (state) */
  assert.equal(LUA_V68_GETROOMENTITIES_VEC_OFF_REF_U32, 0xfffffffc); /* ebp-4 (ref) */
  assert.equal(LUA_V68_GETROOMENTITIES_REGISTRY_INDEX_U32, 0xfff0b9d8);
  assert.equal(LUA_V68_GETROOMENTITIES_IAT_LUA_LUAL_UNREF, 0x00b1831c); /* luaL_unref (NOT rawgeti 0xb18318) */
  assert.equal(LUA_V68_GETROOMENTITIES_RAWGETI_HELPER_VA, 0x006a80f0);
  assert.equal(luaEngineV68GetRoomEntitiesVecOffLo(), 0xfffffff8);
  assert.equal(luaEngineV68GetRoomEntitiesVecOffRef(), 0xfffffffc);
  assert.equal(luaEngineV68GetRoomEntitiesRegistryIndex(), 0xfff0b9d8);
  assert.equal(luaEngineV68GetRoomEntitiesIatLuaLualUnref(), 0x00b1831c);
  assert.equal(luaEngineV68GetRoomEntitiesRawgetiHelperVa(), 0x006a80f0);
  assert.equal(LUA_V68_GETROOMENTITIES_RETURN_VALUE, 1);
  assert.equal(luaEngineV68GetRoomEntitiesReturnValue(), 1);
  assert.equal(LUA_V68_GETROOMENTITIES_INSTALL_COUNT, 1);
  assert.equal(LUA_V68_GETROOMENTITIES_INSTALL_VA, 0x008961b0);
  assert.equal(LUA_V68_GETROOMENTITIES_INSTALL_RET_VA, 0x00896208);
  assert.equal(LUA_V68_GETROOMENTITIES_INSTALL_LITERAL_VA, 0x008961c1);
  assert.equal(LUA_V68_GETROOMENTITIES_INSTALL_REAL_FN_VA, 0x0086fb20);
  assert.equal(LUA_V68_GETROOMENTITIES_INSTALL_NAME_VA, 0x00b74dbc); /* "GetRoomEntities" */
  assert.equal(LUA_V68_GETROOMENTITIES_INSTALL_CALLER_VA, 0x0086de46);
  assert.equal(luaEngineV68GetRoomEntitiesInstallLiteralVa(), 0x008961c1);
  assert.equal(luaEngineV68GetRoomEntitiesInstallRealFnVa(), 0x0086fb20);
  assert.equal(luaEngineV68GetRoomEntitiesInstallNameVa(), 0x00b74dbc);
  assert.equal(luaEngineV68GetRoomEntitiesInstallCallerVa(), 0x0086de46);
});

