test("ABI v68 wrapper mutants: nine translation errors are tripwires", () => {
  /* Each mutant below is a value a BROKEN translation would produce; the
   * permanent tripwire is the assert.equal/notEqual pair + explicit PE
   * truth. (Applied-and-restored sha256-identical runs recorded in
   * lua-v68-8b9b20 NOTES.) */
  assert.equal(LUA_ENGINE_PURE_ABI_VERSION, HEADER_ABI_VERSION);
  // M1: IsButtonTriggered return gate folded to FULL-WORD normalize
  // (0x100 -> 1). PE `test al,al` @0x897907 is a BYTE gate — 0x100 has
  // AL=0x00 -> 0.
  assert.equal(luaEngineV68IsButtonTriggeredReturnGate(0x100), 0);
  assert.notEqual(luaEngineV68IsButtonTriggeredReturnGate(0x100), 1);
  // M2: GetBuiltInCallbackState return gate folded to FULL-WORD
  // normalize (0x100 -> 1). PE `test al,al` @0x89e329 is a BYTE gate.
  assert.equal(luaEngineV68GetBuiltInCallbackStateReturnGate(0x100), 0);
  assert.notEqual(luaEngineV68GetBuiltInCallbackStateReturnGate(0x100), 1);
  // M3: null gate folded to BYTE mask (0x100 -> 0). PE `test edi,edi`
  // @0x898dad (MusicManager) is FULL-WORD — 0x100 -> 1.
  assert.equal(luaEngineV68MusicManagerNullGate(0x100), 1);
  assert.notEqual(luaEngineV68MusicManagerNullGate(0x100), 0);
  assert.equal(luaEngineV68SfxManagerNullGate(0x100), 1);
  assert.equal(luaEngineV68Game0NullGate(0x100), 1);
  assert.notEqual(luaEngineV68Game0NullGate(0x100), 0);
  // M4: GetButtonValue pusher edge folded to the v55 sext pusher
  // (0x85c050 -> 0x85bfd0). PE call 0x85c050 @0x8978b7 = PUSHER_0
  // PUSHNUMBER_F32 (the f32 lane), NOT the i32 sext row.
  assert.equal(luaEngineV68GetButtonValueNumberPushVa(), 0x0085c050);
  assert.notEqual(luaEngineV68GetButtonValueNumberPushVa(), 0x0085bfd0);
  // M5: MusicManager rawgetp key folded to the SFXManager key
  // (0xc82a19 -> 0xc82a16). PE push 0xc82a19 @0x898dba.
  assert.equal(luaEngineV68MusicManagerRawgetpKey(), 0x00c82a19);
  assert.notEqual(luaEngineV68MusicManagerRawgetpKey(), 0x00c82a16);
  // M6: Game0 key folded to the MusicManager key (0xc82a13 -> 0xc82a19).
  // PE push 0xc82a13 @0x898e9a.
  assert.equal(luaEngineV68Game0RawgetpKey(), 0x00c82a13);
  assert.notEqual(luaEngineV68Game0RawgetpKey(), 0x00c82a19);
  // M7: GetRoomEntities unref IAT folded to lua_rawgeti (0xb1831c ->
  // 0xb18318). PE call [0xb1831c] @0x8984c5 is luaL_unref (the rawgeti
  // lives inside the host helper 0x6a80f0 @0x6a8104).
  assert.equal(luaEngineV68GetRoomEntitiesIatLuaLualUnref(), 0x00b1831c);
  assert.notEqual(luaEngineV68GetRoomEntitiesIatLuaLualUnref(), 0x00b18318);
  // M8: RandomVector payload self-off folded (8 -> 4). PE `lea
  // ecx,[esi+8]` @0x898f15 places the 8-byte vec at ud+8.
  assert.equal(luaEngineV68RandomVectorUdPayloadOff(), 0x08);
  assert.notEqual(luaEngineV68RandomVectorUdPayloadOff(), 0x04);
  // M9: GetButtonValue arg indices swapped (arg0 1 -> 2). PE pushes:
  // checkinteger idx 2 first @0x897891 (arg2), idx 1 @0x89789a (arg1);
  // stack order fixes arg0 = idx 1.
  assert.equal(luaEngineV68GetButtonValueArg0CheckintegerIndex(), 0x01);
  assert.notEqual(luaEngineV68GetButtonValueArg0CheckintegerIndex(), 0x02);
  assert.equal(luaEngineV68GetButtonValueArg1CheckintegerIndex(), 0x02);
});

