test("ABI v70: model pins + native==model sweep + header pin table", async () => {
  const m = await import("../scripts/decomp/lua-engine-pure-model.mjs");
  assert.equal(m.LUA_ENGINE_PURE_ABI_VERSION, 103);
  const native = loadExports();
  // Every model constant pins its PE literal.
  for (const [name, value] of V70_MODEL_PINS) {
    assert.equal(m[name], value, name);
  }
  // Site arrays pin PE truth.
  assert.deepEqual(m.LUA_V70_SCREENTOWORLD_SITE_CALLER_VAS, [0x0086e044, 0x0086e055, 0x0086e066, 0x0086e077, 0x0086e088]);
  assert.deepEqual(m.LUA_V70_SCREENTOWORLD_SITE_REAL_FN_VAS, [0x00870160, 0x00870220, 0x00870390, 0x008703c0, 0x008704c0]);
  assert.deepEqual(m.LUA_V70_SCREENTOWORLD_SITE_NAME_VAS, [0x00b7500c, 0x00b74fd4, 0x00b74fe4, 0x00b74fa4, 0x00b74fbc]);
  // Native wasm exports agree with the JS oracle on every v70 export.
  for (const [natKey, modelFn, args] of V70_FN_PAIRS) {
    const got = native[natKey](...args);
    const want = m[modelFn](...args);
    assert.equal(got >>> 0, want >>> 0, `${natKey} == ${modelFn} ${JSON.stringify(args)}`);
  }
  // Header pins every v70 enum + the census-row reason.
  const h = readFileSync(header, "utf8");
  assert.match(h, /ISAAC_LUA_ENGINE_PURE_HELPERS_ABI_VERSION = 103/);
  for (const [name] of V70_MODEL_PINS) {
    assert.ok(h.includes(name.replace("LUA_V70_", "ISAAC_LUA_V70_")), name);
  }
  assert.ok(h.includes("0x8c2850 TimeCounter stays a census row"));
  // TimeCounter real_fn literal is NOT an image VA (documented only).
  assert.equal(m.LUA_PROPERTY_FAMILY_ROWS.find((r) => r[2] === 0x8c2850)[8], 0x264fc);
});

test("ABI v70 mutants: six translation errors are tripwires", async () => {
  const m = await import("../scripts/decomp/lua-engine-pure-model.mjs");
  assert.equal(m.LUA_ENGINE_PURE_ABI_VERSION, 103);
  // M1: GetMousePosition bool gate normalized to FULL-WORD would map
  // 0x100 -> 1; PE test/setne @0x897812/0x897817 is BYTE-gated.
  assert.equal(m.luaEngineV70GetMousePositionBoolGate(0x100), 0);
  assert.notEqual(m.luaEngineV70GetMousePositionBoolGate(0x100), 1);
  // M2: GetItemConfig rawgetp key folded to the Vector key 0xc82980;
  // PE push 0xc829ad @0x89816a is the ItemConfig class key.
  assert.equal(m.luaEngineV70GetItemConfigRawgetpKey(), 0x00c829ad);
  assert.notEqual(m.luaEngineV70GetItemConfigRawgetpKey(), 0x00c82980);
  // M3: RegisterMod ref-pair arg count folded to 3 (SaveModData law);
  // PE pushes 2 strings + ref pair = 4 dwords, cleanup 0x10.
  assert.equal(m.luaEngineV70RegisterModRealFnArgCount(), 4);
  assert.equal(m.luaEngineV70RegisterModRealFnCleanup(), 0x10);
  assert.notEqual(m.luaEngineV70RegisterModRealFnArgCount(), 3);
  // M4: ScreenToWorld site count folded to 1 (single-body law); PE
  // 17-byte records at 0x86e044/0x86e055/0x86e066/0x86e077/0x86e088.
  assert.equal(m.luaEngineV70ScreenToWorldInstallCount(), 5);
  assert.notEqual(m.luaEngineV70ScreenToWorldInstallCount(), 1);
  // M5: RenderScaledText float lanes folded to 6 (RenderText law); PE
  // sub esp,0x20 + 8 movss lanes + string = 9 dwords, cleanup 0x24.
  assert.equal(m.luaEngineV70RenderScaledTextFloatLaneCount(), 8);
  assert.equal(m.luaEngineV70RenderScaledTextRealFnArgCount(), 9);
  assert.notEqual(m.luaEngineV70RenderScaledTextRealFnArgCount(), 7);
  // M6: GetFreeNearPosition checknumber index folded to 1; PE
  // `push 2` @0x898617 targets Lua arg 2.
  assert.equal(m.luaEngineV70GetFreeNearPositionArg2ChecknumberIndexU32(), 2);
  assert.notEqual(m.luaEngineV70GetFreeNearPositionArg2ChecknumberIndexU32(), 1);
});


