  assert.equal(LUA_ENGINE_8999E0_IAT_LUA_TYPE, 0xb18400);
  assert.equal(LUA_ENGINE_8999E0_CHECKGET_KEY, 0xc82a01);
  assert.equal(LUA_ENGINE_8999E0_CHECKGET_INDEX, 1);
  assert.equal(LUA_ENGINE_8999E0_CHECKGET_DEF_ARG, 1);
  assert.equal(LUA_ENGINE_8999E0_CHECKGET_FIELD_OFF, 4);
  assert.equal(LUA_ENGINE_8999E0_CHECKGET_HELPER_VA, 0x85c590);
  assert.equal(LUA_ENGINE_8999E0_METHOD_VTABLE_FIELD_OFF, 0);
  assert.equal(LUA_ENGINE_8999E0_METHOD_STACK_ARGS, 1); // obj pushed, cdecl cleanup
  assert.equal(LUA_ENGINE_8999E0_IAT_LUA_PUSHINTEGER, 0xb183f8);
