  assert.equal(LUA_ENGINE_899A50_IAT_LUA_TOUSERDATA, 0xb183b0);
  assert.equal(LUA_ENGINE_899A50_TOUSERDATA_INDEX_U32 >>> 0, 0xfff0b9d7);
  assert.equal(LUA_ENGINE_899A50_IAT_LUA_TYPE, 0xb18400);
  assert.equal(LUA_ENGINE_899A50_CHECKGET_KEY, 0xc829fe);
  assert.equal(LUA_ENGINE_899A50_CHECKGET_INDEX, 1);
  assert.equal(LUA_ENGINE_899A50_CHECKGET_DEF_ARG, 1);
  assert.equal(LUA_ENGINE_899A50_CHECKGET_FIELD_OFF, 4);
  assert.equal(LUA_ENGINE_899A50_CHECKGET_HELPER_VA, 0x85c590);
  assert.equal(LUA_ENGINE_899A50_METHOD_VTABLE_FIELD_OFF, 0);
  assert.equal(LUA_ENGINE_899A50_METHOD_STACK_ARGS, 2); // (&out, obj)
  assert.equal(LUA_ENGINE_899A50_NEWUSERDATA_SIZE, 0x10);
  assert.equal(LUA_ENGINE_899A50_UD_VTABLE_VA, 0xb7354c);
  assert.equal(LUA_ENGINE_899A50_UD_PAYLOAD_PTR_OFF, 4);
  assert.equal(LUA_ENGINE_899A50_UD_PAYLOAD_OFF, 8);
  assert.equal(LUA_ENGINE_899A50_REGISTRY_INDEX_U32 >>> 0, 0xfff0b9d8);
