test("ABI v75 mutants: three translation errors are tripwires", () => {
  const m = {
    luaEngine8999E0Type1GateTaken,
    luaEngine899A50Type1GateTaken,
  };
  const exp = loadExports();
  // M1: gate direction flipped (== 0) sends nil down the check/get
  // path; PE `test eax,eax; jne 0x899a0d` @0x899a05/07 takes the check
  // path strictly on NON-ZERO.
  assert.equal(m.luaEngine8999E0Type1GateTaken(0), 0);
  assert.notEqual(m.luaEngine8999E0Type1GateTaken(0), 1);
  // M2: pushinteger hi word folded to sign extension (hi = result >> 31
  // would map 0x80000000 -> negative i64); PE pushes literal 0 as the
  // hi dword @0x899a2e — ZERO extension.
  assert.equal(m.luaEngine8999E0Type1GateTaken(0x100), 1);
  assert.equal(exp.a8999e0PushintegerHiWord() >>> 0, 0);
  assert.notEqual(exp.a8999e0PushintegerHiWord() >>> 0, 1);
  // M3: box-ctor check/get key folded to the sibling band's 0xc82a01;
  // PE pushes 0xc829fe @0x899a82 and a distinct vtable 0xb7354c.
  assert.notEqual(LUA_ENGINE_899A50_CHECKGET_KEY, LUA_ENGINE_8999E0_CHECKGET_KEY);
  assert.notEqual(LUA_ENGINE_899A50_UD_VTABLE_VA, LUA_ENGINE_899930_UD_VTABLE_VA);
  assert.equal(exp.a899a50UdVtableVa() >>> 0, 0xb7354c);
});

