  assert.equal(LUA_ENGINE_899B70_CHECKGET_DEF_ARG, 1);
  assert.notEqual(LUA_ENGINE_899B00_CHECKGET_DEF_ARG,
    LUA_ENGINE_899B70_CHECKGET_DEF_ARG);
  // M3: sext-pusher helper VA folded to another pusher row; PE calls
