test("ABI v77 mutants: three translation errors are tripwires", () => {
  const m = {
    luaEngine899bd0Type1GateTaken,
    luaEngine899c70Type1GateTaken,
  };
  const exp = loadExports();
  // M1: gate encoding normalized to jne without flipping semantics is
  // fine, but a TRUE inversion (nil -> check path) maps 0 -> 1;
  // PE `je 0x899c01` @0x899be6 sends NIL straight to the cast with a
  // null object.
  assert.equal(m.luaEngine899bd0Type1GateTaken(0), 0);
  assert.notEqual(m.luaEngine899bd0Type1GateTaken(0), 1);
  // M2: twin def args folded (both 0 or both 1); PE pushes 1 @0x899be8
  // vs 0 @0x899c88 — missing-key behavior differs across the pair.
  assert.notEqual(LUA_ENGINE_899BD0_CHECKGET_DEF_ARG, LUA_ENGINE_899C70_CHECKGET_DEF_ARG);
  // M3: cast type descriptors swapped (src <-> dst); PE passes
  // SrcType 0xc5d7a4 THEN DstType 0xc5e8ec in __RTDynamicCast order.
  assert.notEqual(LUA_ENGINE_899BD0_CAST_SRC_TYPE_VA, LUA_ENGINE_899BD0_CAST_DST_TYPE_VA);
  assert.equal(exp.a899bd0CastSrcTypeVa() >>> 0, 0xc5d7a4);
  assert.equal(exp.a899bd0CastDstTypeVa() >>> 0, 0xc5e8ec);
});

