test("ABI v78 mutants: three translation errors are tripwires", () => {
  const m = {
    luaEngine899d10Type1GateTaken,
    luaEngine899db0Type1GateTaken,
  };
  const exp = loadExports();
  // M1: gate encoding normalized to jne without flipping semantics is
  // fine, but a TRUE inversion (nil -> check path) maps 0 -> 1;
  // PE `je 0x899d41` @0x899d26 sends NIL straight to the cast with a
  // null object.
  assert.equal(m.luaEngine899d10Type1GateTaken(0), 0);
  assert.notEqual(m.luaEngine899d10Type1GateTaken(0), 1);
  // M2: twin def args folded (both 0 or both 1); PE pushes 1 @0x899d28
  // vs 0 @0x899dc8 — missing-key behavior differs across the pair.
  assert.notEqual(LUA_ENGINE_899D10_CHECKGET_DEF_ARG, LUA_ENGINE_899DB0_CHECKGET_DEF_ARG);
  // M3: cast type descriptors swapped (src <-> dst); PE passes
  // SrcType 0xc5d7a4 THEN DstType 0xc5d804 in __RTDynamicCast order.
  assert.notEqual(LUA_ENGINE_899D10_CAST_SRC_TYPE_VA, LUA_ENGINE_899D10_CAST_DST_TYPE_VA);
  assert.equal(exp.a899d10CastSrcTypeVa() >>> 0, 0xc5d7a4);
  assert.equal(exp.a899d10CastDstTypeVa() >>> 0, 0xc5d804);
  assert.equal(exp.a899d10CastDstTypeVa() >>> 0, 0xc5d804);
});

