test("ABI v84 mutants: three translation errors are tripwires", () => {
  const m = {
    luaEngine899a4a0Type1GateTaken,
    luaEngine899a510Type1GateTaken,
  };
  const exp = loadExports();
  // M1: gate direction flipped (== 0) sends nil down the check/get
  // path; PE `test eax,eax; jne` takes the check path strictly on
  // NON-ZERO.
  assert.equal(m.luaEngine899a4a0Type1GateTaken(0), 0);
  assert.notEqual(m.luaEngine899a4a0Type1GateTaken(0), 1);
  // M2: twins' def args folded (both 0 or both 1); PE pushes 0 vs 1 —
  // missing-key behavior differs across the pair.
  assert.equal(LUA_ENGINE_899A4A0_CHECKGET_DEF_ARG, 0);
  assert.equal(LUA_ENGINE_899A510_CHECKGET_DEF_ARG, 1);
  assert.notEqual(LUA_ENGINE_899A4A0_CHECKGET_DEF_ARG, LUA_ENGINE_899A510_CHECKGET_DEF_ARG);
  // M3: sext-pusher helper VA folded to another row; PE calls
  // 0x85bfd0 (v55 ROW-3 sext pusher), not an adjacent row.
  assert.equal(exp.a899a510PusherHelperVa() >>> 0, 0x85bfd0);
  assert.notEqual(exp.a899a510PusherHelperVa() >>> 0, 0x85bfd8);
});

