test("ABI v86 mutants: three translation errors are tripwires", () => {
  const m = {
    luaEngine899a670Type1GateTaken,
    luaEngine899a700Type1GateTaken,
  };
  const exp = loadExports();
  // M1: true gate inversion (nil -> check path); PE `jne` takes the
  // check path strictly on NON-ZERO.
  assert.equal(m.luaEngine899a670Type1GateTaken(0), 0);
  assert.notEqual(m.luaEngine899a670Type1GateTaken(0), 1);
  // M2: float-pusher helper VA folded to an adjacent row; PE calls
  // 0x85c050 @0x89a759 (not v76's 0x85bfd0, not the next row).
  assert.equal(exp.a899a700FloatPusherHelperVa() >>> 0, 0x85c050);
  assert.notEqual(exp.a899a700FloatPusherHelperVa() >>> 0, 0x85bfd0);
  // M3: body A conversion folded from checknumber (double->f32 lane,
  // IAT 0xb18324 index 2 @0x89a6c2) to checkinteger (IAT 0xb183f4);
  // the f32 truncation lane would silently become an integer lane.
  assert.equal(exp.a899a670IatLuaChecknumber() >>> 0, 0xb18324);
  assert.notEqual(exp.a899a670IatLuaChecknumber() >>> 0, 0xb183f4);
  assert.equal(LUA_ENGINE_899A670_CHECKNUMBER_INDEX, 2);
});

