  // check path strictly on NON-ZERO.
  assert.equal(m.luaEngine899aae0Type1GateTaken(0), 0);
  assert.notEqual(m.luaEngine899aae0Type1GateTaken(0), 1);
  // M2: float-pusher helper VA folded to an adjacent row; PE calls
  // 0x85c050 @0x89ab39 (not v76's 0x85bfd0, not the next row).
  assert.equal(exp.a899aae0PusherHelperVa() >>> 0, 0x85c050);
