  assert.equal(LUA_ENGINE_899ABF0_END_VA, 0x89ac8a);
  assert.equal(LUA_ENGINE_899ABF0_NEXT_VA, 0x89ac90);
  assert.equal(LUA_ENGINE_899AC90_VA, 0x89ac90);
  assert.equal(LUA_ENGINE_899AC90_END_VA, 0x89ad6d);
  assert.equal(LUA_ENGINE_899AC90_NEXT_VA, 0x89ad70);
  assert.equal(LUA_ENGINE_899AB50_NEXT_VA, LUA_ENGINE_899ABF0_VA);
