test("ABI v90 mutants: three translation errors are tripwires", () => {
  const exp = loadExports();
  const m = { luaEngine899abf0Type1GateTaken };
  // M1: true gate inversion (nil -> check path); PE `jne` takes the
  // check path strictly on NON-ZERO.
  assert.equal(m.luaEngine899abf0Type1GateTaken(0), 0);
  assert.notEqual(m.luaEngine899abf0Type1GateTaken(0), 1);
  // M2: helper-box struct helper VA folded to an adjacent helper; PE
  // calls 0x8b1c80 @0x89acc3.
  assert.equal(exp.a899ac90StructHelperVa() >>> 0, 0x8b1c80);
  assert.notEqual(exp.a899ac90StructHelperVa() >>> 0, 0x8b1c78);
  // M3: helper-box metatable key folded to the box twin's slot; PE uses
  // 0xc829dd @0x89ad21 (vs the 0x18-box's 0xc8299b @0x89ac4c).
  assert.notEqual(LUA_ENGINE_899AC90_METATABLE_RAWGETP_KEY, LUA_ENGINE_899ABF0_METATABLE_RAWGETP_KEY);
  assert.equal(exp.a899ac90MetatableRawgetpKey() >>> 0, 0xc829dd);
});

