test("ABI v91 mutants: three translation errors are tripwires", () => {
  const m = {
    luaEngine899ad70Type1GateTaken,
    luaEngine899ae00Type1GateTaken,
  };
  const exp = loadExports();
  // M1: true gate inversion (nil -> check path); PE `jne` takes the
  // check path strictly on NON-ZERO.
  assert.equal(m.luaEngine899ad70Type1GateTaken(0), 0);
  assert.notEqual(m.luaEngine899ad70Type1GateTaken(0), 1);
  // M2: twins' def args folded (both 0 or both 1); PE pushes 0 @0x89ad94
  // vs 1 @0x89ae1d — missing-key behavior differs across the pair.
  assert.equal(LUA_ENGINE_899AD70_CHECKGET_DEF_ARG, 0);
  assert.equal(LUA_ENGINE_899AE00_CHECKGET_DEF_ARG, 1);
  assert.notEqual(LUA_ENGINE_899AD70_CHECKGET_DEF_ARG, LUA_ENGINE_899AE00_CHECKGET_DEF_ARG);
  // M3: twins' method stack args / return values folded; PE body A
  // pushes the f32 arg (1 stack arg, ret 0) while body B passes zero
  // args and returns 1.
  assert.equal(LUA_ENGINE_899AD70_METHOD_STACK_ARGS, 1);
  assert.equal(LUA_ENGINE_899AE00_METHOD_STACK_ARGS, 0);
  assert.equal(exp.a899ad70ReturnValue() >>> 0, 0);
  assert.equal(exp.a899ae00ReturnValue() >>> 0, 1);
});

