test("ABI v95 mutants: three translation errors are tripwires", () => {
  const exp = loadExports();
  // M1: twin box keys folded; PE pushes 0xc8297a @0x89b199 on the
  // v94 twin but 0xc829d7 @0x89b239 HERE — different registry slots.
  assert.equal(exp.a899b1e0MetatableRawgetpKey() >>> 0, 0xc829d7);
  assert.notEqual(
    exp.a899b1e0MetatableRawgetpKey() >>> 0,
    exp.a899b140MetatableRawgetpKey() >>> 0,
  );
  // M2: float-lane arg index folded from 2 to 1; PE pushes 2 before
  // luaL_checknumber @0x89b2cd — the method receives ARG 2's number.
  assert.equal(exp.a899b280ChecknumberIndex() >>> 0, 2);
  assert.notEqual(exp.a899b280ChecknumberIndex() >>> 0, 1);
  // M3: prologue realignment folded across the pair; PE `and
  // esp,-8` @0x89b283 exists ONLY on the setter — the twin keeps a
  // plain prologue (@0x89b1e0 has no and).
  assert.equal(exp.a899b280AlignedPrologue() >>> 0, 1);
  assert.equal(exp.a899b1e0AlignedPrologue() >>> 0, 0);
});

