test("ABI v98 mutants: three translation errors are tripwires", () => {
  const exp = loadExports();
  // M1: true gate inversion (nil -> check path); PE `jne` @0x89b558
  // takes the check path strictly on NON-ZERO.
  assert.equal(luaEngine899b540Type1GateTaken(0), 0);
  assert.notEqual(luaEngine899b540Type1GateTaken(0), 1);
  // M2: twin def args folded; PE pushes 0 @0x89b55e (setter) vs 1
  // @0x89b5cc (getter) — missing-key behavior differs across the pair.
  assert.notEqual(LUA_ENGINE_899B540_CHECKGET_DEF_ARG, LUA_ENGINE_899B5B0_CHECKGET_DEF_ARG);
  // M3: pushboolean IAT folded to the ADJACENT toboolean slot; PE
  // calls 0xb183ec @0x89b603, not 0xb183e8 @0x89b588.
  assert.equal(exp.a899b5b0IatLuaPushboolean() >>> 0, 0xb183ec);
  assert.notEqual(
    exp.a899b5b0IatLuaPushboolean() >>> 0,
    exp.a899b540IatLuaToboolean() >>> 0,
  );
});

